/* ================================================================
   ETHOS EMPIRE — dashboard.js  Phase 3: True 3D Globe Engine — p19
   Software-rendered 3D sphere — pure JS, no CSS 3D tricks.
   ================================================================ */
'use strict';

/* Stage 20: shared safe-JSON helper. Returns fallback on any parse failure or
   null/empty input. Used by storage readers across the file. */
function safeJsonParse(value, fallback) {
  if (value == null || value === '') return fallback;
  try {
    var p = JSON.parse(value);
    return (p === undefined) ? fallback : p;
  } catch (e) { return fallback; }
}
if (typeof window !== 'undefined') { window.safeJsonParse = safeJsonParse; }

/* Stage 29: shared focus-restore helpers for modal dialogs. Pattern matches the
   inline opener stash that Stage 28 added to the Cmd-K palette - record the
   element that was focused before the modal opened, restore it on close.
   Guarded against body/html and openers inside the modal being closed. */
function _eeStashFocusOpener(key, modal) {
  if (typeof window === 'undefined' || !key) return;
  try {
    var opener = document.activeElement;
    if (!opener) return;
    if (opener === document.body || opener === document.documentElement) return;
    if (modal && modal.contains && modal.contains(opener)) return;
    window['_eeOpener_' + key] = opener;
  } catch (e) {}
}
function _eeRestoreFocusOpener(key) {
  if (typeof window === 'undefined' || !key) return;
  try {
    var slot = '_eeOpener_' + key;
    var opener = window[slot];
    window[slot] = null;
    if (!opener) return;
    if (!document.body.contains(opener)) return;
    if (typeof opener.focus !== 'function') return;
    opener.focus();
  } catch (e) {}
}

/* Stage 31.2B-HOTFIX: graph-view overlays leak into workspaces.
   #wfPanel / #wfConnPanel / #proUpgradePanel are created by initGlobe via
   document.body.appendChild and use position:fixed; z-index:58. The workspace
   overlay #dashboardWorkspace is z-index:55. So when a user opens a planet
   focus panel and then switches to Plan Packs / Daily Log / etc., those
   panels stay docked over the workspace.

   This helper is safe to call at any time:
   - Calls EE_GRAPH_API.clearWorldFocus() when available (clears state +
     panels + planet .is-selected classes via the existing closure path).
   - Falls back to a defensive DOM sweep of the known panel IDs so even if
     EE_GRAPH_API hasn't loaded yet, nothing is left orphaned.
   - Never throws. */
function _eeCleanupGraphOverlays() {
  try {
    if (typeof window !== 'undefined' && window.EE_GRAPH_API) {
      /* Exit the World View first if it's open (it sits at z-index 60 over
         the workspace and contains the "Back to Map" button). */
      if (typeof window.EE_GRAPH_API.exitWorld === 'function') {
        window.EE_GRAPH_API.exitWorld();
      }
      /* Then clear any planet focus panel + Pro upgrade card + planet
         selected state. */
      if (typeof window.EE_GRAPH_API.clearWorldFocus === 'function') {
        window.EE_GRAPH_API.clearWorldFocus();
      }
    }
  } catch (e) {}
  /* Belt + braces - in case the GRAPH_API isn't loaded yet or a stray panel
     wasn't caught (e.g. Stage 31 upgrade card open without a focus). */
  try {
    ['wfPanel', 'wfConnPanel', 'proUpgradePanel'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el && el.parentNode) el.parentNode.removeChild(el);
    });
    /* Defensive: drop wv-open / wv-active classes if they somehow survived
       (they're toggled in the world enter/exit path, but be sure they can't
       leave #worldView capturing clicks over the workspace). */
    var wv = document.getElementById('worldView');
    if (wv) {
      wv.classList.remove('wv-open');
      wv.setAttribute('aria-hidden', 'true');
    }
    var dc = document.getElementById('dashCanvas');
    if (dc) dc.classList.remove('wv-active');
  } catch (e) {}
}
if (typeof window !== 'undefined') { window._eeCleanupGraphOverlays = _eeCleanupGraphOverlays; }

/* ════════════════════════════════════════════════════════════════
   STAGE 31 — Empire Pro plan-tier helpers + Pro-locked planet set
   ════════════════════════════════════════════════════════════════
   Two-tier model (per Stage 31 spec):
     'base' = $30 Empire Core: dashboard + base universe map + base packs
     'pro'  = $40 Empire Pro:  unlocks premium planets, deeper systems

   Current backend reality:
     window.EE_IS_PRO is true when the Firebase profile has an active
     subscription. The backend does NOT yet distinguish $30 vs $40 plans.
     For now we treat any active subscription as 'pro' tier so existing
     paying users are not surprised by new locks. Anyone WITHOUT an active
     subscription falls to 'base' and will see the Pro-locked planets as
     visible-but-locked with an upgrade card on click.

   TODO (backend): once Stripe is wired to distinguish $30 vs $40 SKUs,
   replace the EE_IS_PRO check below with a real read of the user's plan
   level (e.g. EE_USER_PLAN === 'empire-pro') and bump the Firebase profile
   schema accordingly. Until then the upgrade button below routes through
   the existing plan-comparison / upgrade modal - no fake checkout. */
function getDashboardPlanTier() {
  /* Stage 33-B-6: dev flag reads only fire when EE_DEV_FLAGS_ALLOWED is
     true (localhost / 127.0.0.1 / ::1 / .local / file:). In production
     all five overrides are ignored at the gate and the function falls
     through to the real Firestore-derived plan from Stage 33-B-5.
     Precedence inside dev: force_base_tier > empire_pro_unlocked >
     real plan level. force_base wins so a Pro tester can still preview
     the locked state. */
  var devAllowed = typeof window !== 'undefined' && window.EE_DEV_FLAGS_ALLOWED === true;
  if (devAllowed) {
    try { if (localStorage.getItem('ethos_force_base_tier') === '1') return 'base'; } catch (e) {}
    try { if (localStorage.getItem('ethos_empire_pro_unlocked') === 'true') return 'pro'; } catch (e) {}
  }
  /* Stage 33-B-5: wrap getUserPlanLevel() so the Stage 31 Pro-lock and the
     Stage 2 plan-pack gate share one source of truth. 'empire-pro' and
     'dev' both behave as the Pro tier; 'empire-core' resolves to 'base'. */
  if (typeof getUserPlanLevel === 'function') {
    var level = getUserPlanLevel();
    if (level === 'empire-pro' || level === 'dev') return 'pro';
    if (level === 'empire-core' || level === 'free') return 'base';
  }
  return 'base';
}
function isEmpireProUnlocked() { return getDashboardPlanTier() === 'pro'; }
function openEmpireProUpgrade(featureName) {
  /* Preferred path: the Stage 2 plan-comparison modal already shows both
     tiers and routes the chosen tier to checkout. */
  if (typeof window !== 'undefined') {
    if (typeof window.showPlanComparisonModal === 'function') {
      try { window.showPlanComparisonModal(); return; } catch (e) {}
    }
    if (typeof window.openUpgradeModal === 'function') {
      try { window.openUpgradeModal(featureName || 'Empire Pro'); return; } catch (e) {}
    }
    if (typeof window.showUpgradeModal === 'function') {
      try { window.showUpgradeModal(featureName || 'Empire Pro'); return; } catch (e) {}
    }
    if (typeof window.showToast === 'function') {
      window.showToast('Upgrade is not connected yet - check back soon.', 'warning', 2400);
    }
  }
}

/* Set of planet IDs that require Empire Pro. Keep this conservative -
   currently working sections (Money/Business/AI - which back real Plan Packs
   and Knowledge Graph worlds) should NOT be locked here unless the user
   explicitly wants to gate them. Adding the lock visual + upgrade card path
   without touching what those planets actually link to means a paying $40
   user gets the existing experience, a $30 user sees the upsell. */
var LOCKED_PRO_PLANETS = { gnAi: 1, gnBusiness: 1, gnMoney: 1 };

if (typeof window !== 'undefined') {
  window.getDashboardPlanTier = getDashboardPlanTier;
  window.isEmpireProUnlocked  = isEmpireProUnlocked;
  window.openEmpireProUpgrade = openEmpireProUpgrade;
  window.LOCKED_PRO_PLANETS   = LOCKED_PRO_PLANETS;
}

/* ── Auth ready → reveal dashboard ── */
document.addEventListener('ee:authReady', function (e) {
  initDashboard(e.detail || {});
});

function initDashboard(detail) {
  /* Stage 27: ee:authReady may fire more than once (re-login, session refresh).
     Without this guard, initSidebar/initHeader/initWorkspaceSystem would each
     attach a fresh document keydown listener on every fire, so Escape and
     Cmd-K would trigger N times after N auth events. */
  if (window.__eeInitDashboardRan) return;
  window.__eeInitDashboardRan = true;
  var root = document.getElementById('dashRoot');
  if (root) {
    root.style.opacity    = '0';
    root.style.transition = 'opacity 0.55s ease';
    root.style.visibility = 'visible';
    requestAnimationFrame(function () {
      requestAnimationFrame(function () { root.style.opacity = '1'; });
    });
  }

  var name = detail.name || 'Builder';

  var avatarEl = document.getElementById('tbProfAv');
  if (avatarEl) {
    var parts = name.trim().split(' ');
    avatarEl.textContent = (parts[0][0] + (parts[1] ? parts[1][0] : '')).toUpperCase();
  }

  var vaultEl = document.getElementById('sbVaultName');
  if (vaultEl) vaultEl.textContent = name + "'s Empire";

  setTimeout(function () {
    initGlobe();
    startWaveChart();
    buildMinimap();
    initSidebar();
    initWorkspaceSystem();
    initRightPanel();
    initHeader();
    /* Stage 34-C: wire Explore + Tools top-bar dropdowns. Runs after
       initHeader so the markup is in the DOM and the profile dropdown
       handlers are already bound (we never reach into them). */
    if (typeof bindTopMenuDropdowns === 'function') bindTopMenuDropdowns();
    /* Stage 34-D-HOTFIX-R2: arm wheel/trackpad/touch scroll guards for
       Explore/Tools/Profile/Search dropdowns so their CSS overflow
       actually scrolls under wheel and trackpad input (idempotent —
       guarded by _eeScrollGuardBound). Profile + Search panels are
       mounted by initHeader earlier, so they are already in the DOM. */
    if (typeof bindDropdownScrollGuards === 'function') bindDropdownScrollGuards();
    /* Stage 34-D-HOTFIX-R3: arm workspace scroll guards so wheel/trackpad
       gestures over Plan Packs / Active Plan / Daily Log / Tasks / Notes
       / Templates / Settings scroll the panel instead of being absorbed
       by the graph stage's preventDefault wheel handler. Idempotent —
       _eeWorkspaceScrollGuardBound prevents duplicate listeners. */
    if (typeof bindWorkspaceScrollGuards === 'function') bindWorkspaceScrollGuards();
    /* Stage 34-D: promote the top-menu navigation by hiding the old left
       sidebar via a single layout class. Sidebar markup/JS/CSS remain in
       place so we can roll back at runtime with
       window.disableTopMenuLayoutForDebug(). */
    if (typeof applyTopMenuLayout === 'function') applyTopMenuLayout();
    initSidebarCollapse();

    /* Stage 6: install workspace wrappers (empty states, calendar/tags renderers)
       AFTER the closure has registered its base renderers. */
    if (typeof installStage6WorkspaceWrappers === 'function') installStage6WorkspaceWrappers();

    /* Stage 15: replace the Notes workspace with the full Notes Hub */
    if (typeof installStage15NotesHub === 'function') installStage15NotesHub();

    /* Stage 16: replace the Calendar empty state with the full Calendar workspace */
    if (typeof installStage16Calendar === 'function') installStage16Calendar();

    /* Stage 17: replace the Templates placeholder with the full Templates workspace */
    if (typeof installStage17TemplatesHub === 'function') installStage17TemplatesHub();

    /* Stage 18: replace the Tags empty state with the cross-system Tags workspace */
    if (typeof installStage18TagsHub === 'function') installStage18TagsHub();

    /* Stage 21: replace Tasks empty state with the full Tasks workspace */
    if (typeof installStage21TasksHub === 'function') installStage21TasksHub();

    /* Stage 24: replace Daily Log empty state with the full Daily Log workspace */
    if (typeof installStage24DailyLogHub === 'function') installStage24DailyLogHub();

    /* Stage 19: install global Cmd-K search palette */
    if (typeof installStage19GlobalSearch === 'function') installStage19GlobalSearch();

    /* Stage 6: mobile defaults + hamburger + keyboard shortcuts */
    if (typeof eeApplyMobileDefaults === 'function') eeApplyMobileDefaults();
    if (typeof eeInstallMobileHamburger === 'function') eeInstallMobileHamburger();
    if (typeof installStage6Shortcuts === 'function') installStage6Shortcuts();

    /* Stage 6: restore last UI state (falls back to graph view) */
    if (typeof eeRestoreUiState === 'function') {
      eeRestoreUiState();
    } else if (typeof window.switchDashboardView === 'function') {
      window.switchDashboardView('graph');
    }

    /* Stage 12: one-shot backfill of per-day completion timestamps */
    if (typeof backfillCompletionDatesIfMissing === 'function') {
      backfillCompletionDatesIfMissing();
    }

    /* Stage 14: one-shot backfill of checklist item timestamps */
    if (typeof backfillChecklistTimestampsIfMissing === 'function') {
      backfillChecklistTimestampsIfMissing();
    }

    /* Stage 13: pinned daily reminder banner */
    if (typeof updateDailyReminderBanner === 'function') {
      updateDailyReminderBanner();
    }

    /* Stage 2: first-load upgrade modal for free users (once per day) */
    if (typeof maybeShowFirstLoadUpgradeModal === 'function') {
      maybeShowFirstLoadUpgradeModal();
    }
  }, 120);
}

/* ══════════════════════════════════════════════════════════════
   3D GLOBE ENGINE
══════════════════════════════════════════════════════════════ */

var SPHERE_R = 310;  /* sphere radius in px — zoomed out to show more of the map */
var FOCAL    = 580;  /* perspective focal length — must stay > max bubble orbit */

/* 8 satellite nodes — unit-sphere coordinates (normalized on init) */
var SAT_NODES = [
  { id: 'gnDiscipline', lx:  0,      ly:  1,     lz:  0,      color: [168, 85,  247] },
  { id: 'gnMastery',    lx:  0.707,  ly:  0.5,   lz:  0.5,    color: [59,  130, 246] },
  { id: 'gnMindset',    lx: -0.707,  ly:  0.5,   lz:  0.5,    color: [236, 72,  153] },
  { id: 'gnLegacy',     lx:  0.707,  ly:  0.5,   lz: -0.5,    color: [20,  184, 166] },
  { id: 'gnHealth',     lx: -0.707,  ly:  0.5,   lz: -0.5,    color: [6,   182, 212] },
  { id: 'gnBusiness',   lx:  0,      ly: -0.5,   lz:  0.866,  color: [244, 114, 182] },
  { id: 'gnMoney',      lx:  0.75,   ly: -0.5,   lz: -0.433,  color: [245, 197, 66]  },
  { id: 'gnAi',         lx: -0.75,   ly: -0.5,   lz: -0.433,  color: [99,  102, 241] }
];

/* Normalize all nodes to exact unit sphere */
SAT_NODES.forEach(function (n) {
  var len = Math.sqrt(n.lx * n.lx + n.ly * n.ly + n.lz * n.lz);
  if (len > 0) { n.lx /= len; n.ly /= len; n.lz /= len; }
});

/* 24 ambient mini-nodes via Fibonacci sphere distribution */
var MINI_NODES = (function () {
  var pts = [];
  var phi = Math.PI * (3 - Math.sqrt(5));
  for (var i = 0; i < 24; i++) {
    var y  = 1 - (i / 23) * 2;
    var r  = Math.sqrt(Math.max(0, 1 - y * y));
    var th = phi * i;
    pts.push({ lx: Math.cos(th) * r, ly: y, lz: Math.sin(th) * r });
  }
  return pts;
}());

/* 2 energy particles per connection line */
var PARTICLES = (function () {
  var arr = [];
  SAT_NODES.forEach(function (_, i) {
    arr.push({ ni: i, t: Math.random(),              speed: 0.004 + Math.random() * 0.004 });
    arr.push({ ni: i, t: (Math.random() + 0.5) % 1, speed: 0.003 + Math.random() * 0.005 });
  });
  return arr;
}());

/* ── Secondary floating bubbles — outer orbit, no core connection ── */
var BUBBLE_NODES = (function () {
  var labels = [
    'Goals','Habits','Focus','Journaling','Routine','Purpose',
    'Deep Work','Content','Brand','Offers','Clients','Network',
    'Learning','Knowledge','Systems','Strategy','Ideas','Reflection',
    'Recovery','Community','Partnerships','Assets','Discipline Lab',
    'Wealth Systems','Content Vault','Marketing','Identity','Execution',
    'Growth','Vision'
  ];
  var colors = [
    [168,85,247],[59,130,246],[236,72,153],[20,184,166],[6,182,212],
    [244,114,182],[245,197,66],[99,102,241],[212,175,55],[34,197,94],
    [251,113,133],[167,139,250],[52,211,153],[251,191,36],[96,165,250]
  ];
  var phi = Math.PI * (3 - Math.sqrt(5));
  var n   = labels.length;
  return labels.map(function (label, i) {
    var y  = 1 - (i / (n - 1)) * 2;
    var r  = Math.sqrt(Math.max(0, 1 - y * y));
    var th = phi * i;
    /* Vary radial distance: 1.45–1.76× SPHERE_R so bubbles orbit outside the main sphere */
    var radMult = 1.45 + (i % 3) * 0.10 + (Math.abs(y) < 0.5 ? 0.14 : 0);
    return {
      label:   label,
      lx: Math.cos(th) * r,
      ly: y,
      lz: Math.sin(th) * r,
      color:   colors[i % colors.length],
      radMult: Math.min(radMult, 1.76)
    };
  });
}());

