/* Build a unified list of marketplace entries that combine real packs + teasers
   and merge in PACK_META. Real packs are openable; teasers are not. */
function buildMarketplaceEntries() {
  var list = [];
  /* Real packs */
  PLAN_PACKS_DATA.forEach(function (p) {
    var meta  = PACK_META[p.id] || {};
    var theme = PACK_THEMES[meta.theme] || PACK_THEMES['sunrise-gold'];
    list.push({
      id: p.id, title: p.title, icon: p.icon, category: p.category,
      totalDays: p.totalDays, desc: p.desc,
      promise:    meta.promise || p.desc,
      difficulty: meta.difficulty || 'Medium',
      worlds:     meta.worlds || [],
      tags:       meta.tags   || [p.category],
      featured:   !!meta.featured,
      status:     meta.status || 'active',
      theme: theme, themeKey: meta.theme || 'sunrise-gold',
      openable:   true
    });
  });
  /* Teasers */
  PLAN_PACKS_TEASERS.forEach(function (t) {
    var theme = PACK_THEMES[t[6]] || PACK_THEMES['sunrise-gold'];
    list.push({
      id: t[0], title: t[1], icon: t[2], category: t[3],
      totalDays: t[4], desc: t[5], promise: t[5],
      difficulty: 'Medium', worlds: [], tags: String(t[7]).split(','),
      featured: !!t[8],
      status: 'coming-soon',
      theme: theme, themeKey: t[6],
      openable: false
    });
  });
  return list;
}

