/* Top-bar copy per view. The subtitle line can be overridden dynamically
   via the `extraData` arg (e.g. 'Day 3 of 21' for an active plan). */
var TOPBAR_CONTEXT = {
  graph:         { title: 'Knowledge Graph', subtitle: 'Live Map',                          placeholder: 'Search worlds and lessons...' },
  'plan-packs':  { title: 'Plan Packs',      subtitle: 'Empire Pro - 50 guided systems',    placeholder: 'Search packs...' },
  'active-plan': { title: 'My Active Plan',  subtitle: 'No active plan',                    placeholder: 'Search your plan...' },
  notes:         { title: 'Notes',           subtitle: 'World-linked knowledge',            placeholder: 'Search notes...' },
  daily:         { title: 'Daily Log',       subtitle: "Today's reflections",               placeholder: 'Search daily logs...' },
  tasks:         { title: 'Tasks',           subtitle: 'Daily execution',                   placeholder: 'Search tasks...' },
  templates:     { title: 'Templates',       subtitle: 'Reusable structures',               placeholder: 'Search templates...' },
  dataview:      { title: 'Dataview',        subtitle: 'Query your empire',                 placeholder: 'Search data...' },
  calendar:      { title: 'Calendar',        subtitle: 'Schedule and milestones',           placeholder: 'Search calendar...' },
  tags:          { title: 'Tags',            subtitle: 'Structured labels',                 placeholder: 'Search tags...' },
  settings:      { title: 'Settings',        subtitle: 'Account, billing, and dashboard controls', placeholder: 'Search settings...' }
};

/* Stage 34-B: workflow mode registry. Single-entry for now - the arrows are
   wired so the cycling mechanism is verifiable, but cycleWorkflowMode wraps
   around a length-1 array so the result stays on Planet Workflow. Stage
   34-E will expand the registry; Stage 34-F will swap actual canvas
   rendering per mode. Until then this is a pure UI scaffold. */
var WORKFLOW_MODES = [
  { id: 'planet', title: 'Planet Workflow', subtitle: 'Knowledge Graph' }
];

function getCurrentWorkflowMode() {
  var id = (window.dashboardState && window.dashboardState.workflowMode) || 'planet';
  for (var i = 0; i < WORKFLOW_MODES.length; i++) {
    if (WORKFLOW_MODES[i].id === id) return WORKFLOW_MODES[i];
  }
  return WORKFLOW_MODES[0];
}

function updateWorkflowSwitcher() {
  var sw = document.getElementById('tbWorkflowSwitcher');
  if (!sw) return;
  var mode = getCurrentWorkflowMode();
  var titleEl = document.getElementById('tbWfTitle');
  var subEl   = document.getElementById('tbWfSub');
  if (titleEl) titleEl.textContent = mode.title;
  if (subEl)   subEl.textContent   = mode.subtitle;
  /* Visibility is owned by updateTopBarContext (viewId === 'graph'); this
     helper only refreshes the labels. */
}

function cycleWorkflowMode(direction) {
  if (!WORKFLOW_MODES.length) return;
  var currentId = (window.dashboardState && window.dashboardState.workflowMode) || 'planet';
  var idx = 0;
  for (var i = 0; i < WORKFLOW_MODES.length; i++) {
    if (WORKFLOW_MODES[i].id === currentId) { idx = i; break; }
  }
  var nextIdx = (idx + (direction > 0 ? 1 : -1) + WORKFLOW_MODES.length) % WORKFLOW_MODES.length;
  if (window.dashboardState) window.dashboardState.workflowMode = WORKFLOW_MODES[nextIdx].id;
  /* Subtle visual tick so the click is visible even when the mode is
     unchanged (length === 1). Class removed after a short transition. */
  var sw = document.getElementById('tbWorkflowSwitcher');
  if (sw) {
    sw.classList.add('is-ticking');
    setTimeout(function () { sw.classList.remove('is-ticking'); }, 220);
  }
  updateWorkflowSwitcher();
}

function _bindWorkflowSwitcherEvents() {
  var prev = document.getElementById('tbWfPrev');
  var next = document.getElementById('tbWfNext');
  if (prev && !prev._eeBound) { prev._eeBound = true; prev.addEventListener('click', function () { cycleWorkflowMode(-1); }); }
  if (next && !next._eeBound) { next._eeBound = true; next.addEventListener('click', function () { cycleWorkflowMode( 1); }); }
}

/* ════════════════════════════════════════════════════════════════
   Stage 34-C — Top-bar Explore + Tools dropdowns
   ════════════════════════════════════════════════════════════════
   Apple-style glass capsules that route through the same
   switchDashboardView() path as the existing sidebar. The sidebar
   stays mounted so both surfaces work in parallel; Stage 34-D will
   hide the side rail once these are verified. */
var TOP_MENU_VIEWS = {
  explore: ['graph', 'plan-packs', 'active-plan', 'notes', 'daily', 'tasks', 'templates'],
  tools:   ['dataview', 'calendar', 'tags', 'settings']
};

function closeTopMenuDropdowns() {
  ['tbExploreDrop', 'tbToolsDrop'].forEach(function (id) {
    var drop = document.getElementById(id);
    if (drop) {
      drop.classList.remove('is-open');
      drop.setAttribute('aria-hidden', 'true');
    }
  });
  ['tbExploreBtn', 'tbToolsBtn'].forEach(function (id) {
    var btn = document.getElementById(id);
    if (btn) {
      btn.classList.remove('is-open');
      btn.setAttribute('aria-expanded', 'false');
    }
  });
}

function toggleTopMenuDropdown(type) {
  if (type !== 'explore' && type !== 'tools') return;
  var btnId  = (type === 'explore') ? 'tbExploreBtn'  : 'tbToolsBtn';
  var dropId = (type === 'explore') ? 'tbExploreDrop' : 'tbToolsDrop';
  var btn  = document.getElementById(btnId);
  var drop = document.getElementById(dropId);
  if (!btn || !drop) return;
  var alreadyOpen = drop.classList.contains('is-open');
  closeTopMenuDropdowns();
  if (!alreadyOpen) {
    drop.classList.add('is-open');
    drop.setAttribute('aria-hidden', 'false');
    btn.classList.add('is-open');
    btn.setAttribute('aria-expanded', 'true');
  }
}

function handleTopMenuViewClick(viewId) {
  if (!viewId) return;
  closeTopMenuDropdowns();
  if (typeof window.switchDashboardView === 'function') {
    window.switchDashboardView(viewId);
  }
}

function _refreshTopMenuActive(viewId) {
  var current = viewId || (window.dashboardState && window.dashboardState.currentView) || '';
  ['explore', 'tools'].forEach(function (type) {
    var btnId  = (type === 'explore') ? 'tbExploreBtn'  : 'tbToolsBtn';
    var dropId = (type === 'explore') ? 'tbExploreDrop' : 'tbToolsDrop';
    var btn  = document.getElementById(btnId);
    var drop = document.getElementById(dropId);
    var owns = TOP_MENU_VIEWS[type].indexOf(current) >= 0;
    if (btn) btn.classList.toggle('is-active', owns);
    if (drop) Array.prototype.forEach.call(drop.querySelectorAll('.tb-menu-item'), function (it) {
      it.classList.toggle('is-active', it.getAttribute('data-view') === current);
    });
  });
}

/* Stage 34-D — top-menu primary layout toggle.
   Adds .layout-top-menus on #dashRoot so the CSS hides the old left
   sidebar and zeros the --sidebar-w grid column. Sidebar DOM/JS/CSS are
   left untouched as a fallback. Browser-side rollback uses
   window.disableTopMenuLayoutForDebug() — no localStorage, no payment-
   adjacent flags. The default opt-in flag is window.EE_USE_TOP_MENU_LAYOUT
   (true unless explicitly set false before this runs). */
function applyTopMenuLayout() {
  var root = document.getElementById('dashRoot');
  if (!root) return;
  var enabled = (window.EE_USE_TOP_MENU_LAYOUT !== false);
  root.classList.toggle('layout-top-menus', enabled);
}
function disableTopMenuLayoutForDebug() {
  window.EE_USE_TOP_MENU_LAYOUT = false;
  var root = document.getElementById('dashRoot');
  if (root) root.classList.remove('layout-top-menus');
}
function enableTopMenuLayoutForDebug() {
  window.EE_USE_TOP_MENU_LAYOUT = true;
  var root = document.getElementById('dashRoot');
  if (root) root.classList.add('layout-top-menus');
}

/* Stage 34-D-HOTFIX-R3 — workspace scroll guards.
   #workspaceContent (and worldView / lessonPanel) live inside
   <main id="dashCanvas">, which is the graph "stage" — and stage owns
   a wheel listener registered with { passive: false } that calls
   preventDefault() whenever appMode is 'map' (js:~5979). That means
   wheel events bubbling from a dashboard workspace view (Plan Packs,
   Active Plan, Daily Log, Tasks, Notes, Templates, Settings) reach the
   stage and get their default scroll cancelled. The scrollbar works
   because it scrolls programmatically without dispatching a wheel
   event; mouse/trackpad gestures hit the stage handler first.
   Fix: per-surface stopPropagation (same pattern the codebase already
   uses on panelEl/coreLibEl/rpPanel and the R2 dropdown guard).
   Passive: true — never preventDefault, so the surface's own native
   scroll runs untouched. */
function _protectScrollableSurface(el) {
  if (!el || el._eeWorkspaceScrollGuardBound) return;
  el._eeWorkspaceScrollGuardBound = true;
  var stop = function (e) { e.stopPropagation(); };
  el.addEventListener('wheel',      stop, { passive: true });
  el.addEventListener('touchstart', stop, { passive: true });
  el.addEventListener('touchmove',  stop, { passive: true });
}
function bindWorkspaceScrollGuards() {
  /* Bind once per element. innerHTML swaps inside workspaceContent
     don't detach the listener (it's on the container, not the children),
     so this can safely be called from showWorkspaceView on every view
     change — the flag short-circuits after the first call. */
  ['workspaceContent', 'dashboardWorkspace', 'worldView', 'lessonPanel'].forEach(function (id) {
    _protectScrollableSurface(document.getElementById(id));
  });
}

/* Stage 34-D-HOTFIX-R2 — wheel / trackpad / touch scroll guards.
   The dropdowns have CSS-correct max-height + overflow-y, but wheel and
   touch events were still propagating into background canvas/page
   handlers (the codebase has the same guard pattern at coreLibEl,
   panelEl, rpPanel — see js:5841, 7871, 17565). Stop propagation in
   passive mode so the panel's own native scroll runs normally but the
   event never reaches downstream graph/page handlers. No preventDefault
   — that would kill the scroll we are trying to enable. */
function _protectMenuScroll(el) {
  if (!el || el._eeScrollGuardBound) return;
  el._eeScrollGuardBound = true;
  var stop = function (e) { e.stopPropagation(); };
  el.addEventListener('wheel',      stop, { passive: true });
  el.addEventListener('touchstart', stop, { passive: true });
  el.addEventListener('touchmove',  stop, { passive: true });
}
function bindDropdownScrollGuards() {
  ['tbExploreDrop', 'tbToolsDrop', 'tbProfDrop', 'tbSrchDrop'].forEach(function (id) {
    _protectMenuScroll(document.getElementById(id));
  });
}

function bindTopMenuDropdowns() {
  var explore = document.getElementById('tbExploreBtn');
  var tools   = document.getElementById('tbToolsBtn');
  if (explore && !explore._eeBound) {
    explore._eeBound = true;
    explore.addEventListener('click', function (e) { e.stopPropagation(); toggleTopMenuDropdown('explore'); });
  }
  if (tools && !tools._eeBound) {
    tools._eeBound = true;
    tools.addEventListener('click', function (e) { e.stopPropagation(); toggleTopMenuDropdown('tools'); });
  }
  /* Item delegation - one handler per dropdown panel. */
  ['tbExploreDrop', 'tbToolsDrop'].forEach(function (id) {
    var drop = document.getElementById(id);
    if (!drop) return;
    /* Stage 34-D-HOTFIX-R2: arm wheel/touch guards here as well so a
       runtime call to window.bindTopMenuDropdowns() re-arms them after
       a hot edit. _protectMenuScroll is idempotent. */
    _protectMenuScroll(drop);
    if (drop._eeBound) return;
    drop._eeBound = true;
    drop.addEventListener('click', function (e) {
      e.stopPropagation();
      var item = e.target.closest('.tb-menu-item');
      if (!item) return;
      handleTopMenuViewClick(item.getAttribute('data-view'));
    });
  });
  /* Outside click + Escape - guarded so it doesn't bind twice and
     doesn't interfere with the profile dropdown (which has its own
     handler and uses a separate .pd-open class). */
  if (!document._eeTopMenuOutsideBound) {
    document._eeTopMenuOutsideBound = true;
    document.addEventListener('click', function (e) {
      if (e.target.closest('#tbNavActions')) return;
      closeTopMenuDropdowns();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') closeTopMenuDropdowns();
    });
  }
  _refreshTopMenuActive();
}

function updateTopBarContext(viewId, extraData) {
  var ctx = TOPBAR_CONTEXT[viewId] || { title: viewId || 'Workspace', subtitle: '', placeholder: 'Search...' };

  /* Stage 5: when on My Active Plan, dynamically replace the subtitle
     with the active pack name + day count. */
  if (viewId === 'active-plan' && typeof getActivePack === 'function') {
    var ap = getActivePack();
    if (ap) {
      var pp = (typeof _apReadProgress === 'function') ? (_apReadProgress()[ap.id] || {}) : {};
      var completed = 0;
      (ap.days || []).forEach(function (d) { if (pp['day_' + d.day]) completed++; });
      var nextDayNum = ap.totalDays;
      if (ap.days && ap.days.length) {
        for (var i = 0; i < ap.days.length; i++) {
          if (!pp['day_' + ap.days[i].day]) { nextDayNum = ap.days[i].day; break; }
        }
      }
      ctx = {
        title:       ctx.title,
        subtitle:    ap.title + ' - Day ' + nextDayNum + ' of ' + ap.totalDays,
        placeholder: 'Search active plan...'
      };
    } else {
      ctx = { title: ctx.title, subtitle: 'No active plan', placeholder: 'Search active plan...' };
    }
  }

  var titleEl    = document.getElementById('tbTitle');
  var subtitleEl = document.getElementById('tbSubtitle');
  var searchEl   = document.getElementById('tbSrchInput');
  var liveDotEl  = document.getElementById('tbLiveDot');

  if (titleEl)    titleEl.textContent    = (extraData && extraData.title)    || ctx.title;
  if (subtitleEl) subtitleEl.textContent = (extraData && extraData.subtitle) || ctx.subtitle;
  if (searchEl)   searchEl.placeholder    = (extraData && extraData.placeholder) || ctx.placeholder;
  /* Green "live" dot only makes sense in Graph View */
  if (liveDotEl)  liveDotEl.style.display = (viewId === 'graph') ? '' : 'none';

  /* Stage 34-B: workflow switcher visibility tracks viewId === 'graph'. The
     normal context block (#tbTitle / #tbSubtitle) stays mounted so other
     views keep their existing labels; the switcher just slides in beside
     it on graph view. _bindWorkflowSwitcherEvents is idempotent (guarded
     by _eeBound) so repeated calls do not stack handlers. */
  var sw = document.getElementById('tbWorkflowSwitcher');
  if (sw) {
    if (viewId === 'graph') {
      sw.hidden = false;
      _bindWorkflowSwitcherEvents();
      updateWorkflowSwitcher();
    } else {
      sw.hidden = true;
    }
  }

  /* Stage 34-C: refresh the Explore / Tools active state so the top-bar
     dropdown chips and active item highlight track switchDashboardView
     transitions (sidebar clicks, programmatic switches, etc.). Safe no-op
     when the buttons are not yet mounted. */
  if (typeof _refreshTopMenuActive === 'function') _refreshTopMenuActive(viewId);
}

function setDashboardBackgroundMode(viewId) {
  var root = document.getElementById('dashRoot');
  if (!root) return;
  var modes = ['mode-graph','mode-packs','mode-active-plan','mode-notes','mode-tasks','mode-calendar','mode-settings'];
  modes.forEach(function (m) { root.classList.remove(m); });

  if      (viewId === 'graph')        root.classList.add('mode-graph');
  else if (viewId === 'plan-packs')   root.classList.add('mode-packs');
  else if (viewId === 'active-plan')  root.classList.add('mode-active-plan');
  else if (viewId === 'notes')        root.classList.add('mode-notes');
  else if (viewId === 'daily')        root.classList.add('mode-notes');
  else if (viewId === 'tasks')        root.classList.add('mode-tasks');
  else if (viewId === 'calendar')     root.classList.add('mode-calendar');
  else if (viewId === 'settings')     root.classList.add('mode-settings');
  else                                root.classList.add('mode-graph');
}

function setGraphInteractionEnabled(enabled) {
  var root = document.getElementById('dashRoot');
  if (!root) return;
  root.classList.toggle('graph-locked', !enabled);
}

function hideGraphHudForWorkspace() {
  var root = document.getElementById('dashRoot');
  if (root) root.classList.add('hide-graph-hud');
}

function showGraphHudForGraphView() {
  var root = document.getElementById('dashRoot');
  if (root) root.classList.remove('hide-graph-hud');
}

function saveDashboardUiState() {
  try { localStorage.setItem('ethos_dashboard_view', dashboardState.currentView || 'graph'); } catch (e) {}
}

/* ── Sidebar collapse ── */
function setSidebarCollapsed(isCollapsed) {
  var root = document.getElementById('dashRoot');
  var btn  = document.getElementById('sidebarCollapseBtn');
  if (!root) return;
  root.classList.toggle('sidebar-collapsed', !!isCollapsed);
  if (btn) {
    btn.setAttribute('aria-pressed', isCollapsed ? 'true' : 'false');
    btn.setAttribute('aria-label', isCollapsed ? 'Expand sidebar' : 'Collapse sidebar');
    btn.setAttribute('title',      isCollapsed ? 'Expand sidebar' : 'Collapse sidebar');
  }
  try {
    localStorage.setItem('ethos_sidebar_collapsed', isCollapsed ? '1' : '0');
    /* Stage 6: mirror to the ui-state namespace per spec */
    localStorage.setItem('ethos_ui_sidebar_collapsed', isCollapsed ? '1' : '0');
  } catch (e) {}
}

function toggleSidebarCollapsed() {
  var root = document.getElementById('dashRoot');
  if (!root) return;
  setSidebarCollapsed(!root.classList.contains('sidebar-collapsed'));
}

function initSidebarCollapse() {
  var btn = document.getElementById('sidebarCollapseBtn');
  var stored = '0';
  try { stored = localStorage.getItem('ethos_sidebar_collapsed') || '0'; } catch (e) {}
  setSidebarCollapsed(stored === '1');
  if (btn && !btn._eeBound) {
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      toggleSidebarCollapsed();
    });
    btn._eeBound = true;
  }
}

/* ── My Active Plan empty-state renderer ── */
/* ════════════════════════════════════════════════════════════════
   STAGE 5 - My Active Plan workspace
   ════════════════════════════════════════════════════════════════ */

/* ── Active pack state helpers (module scope) ── */
function getActivePackId() {
  try { return localStorage.getItem('ethos_active_pack') || null; } catch (e) { return null; }
}
function setActivePack(packId) {
  if (!packId) return;
  try { localStorage.setItem('ethos_active_pack', String(packId)); } catch (e) {}
  /* Refresh top-bar subtitle so it picks up the new pack immediately */
  if (window.dashboardState && window.updateTopBarContext) {
    window.updateTopBarContext(window.dashboardState.currentView);
  }
  /* Stage 13: pinned reminder follows the active pack */
  if (typeof updateDailyReminderBanner === 'function') updateDailyReminderBanner();
}
function clearActivePack() {
  try { localStorage.removeItem('ethos_active_pack'); } catch (e) {}
  if (window.dashboardState && window.updateTopBarContext) {
    window.updateTopBarContext(window.dashboardState.currentView);
  }
  if (typeof updateDailyReminderBanner === 'function') updateDailyReminderBanner();
}
function getActivePack() {
  var id = getActivePackId();
  if (!id) return null;
  if (typeof PLAN_PACKS_DATA === 'undefined') return null;
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === id) return PLAN_PACKS_DATA[i];
  }
  /* Stale pointer (e.g. pack was removed) - clean up */
  clearActivePack();
  return null;
}

/* Read pack progress straight from localStorage (the closure persists
   here, so module-scope readers stay in sync). */
function _apReadProgress() {
  try { return JSON.parse(localStorage.getItem('ee_pack_progress') || '{}'); } catch (e) { return {}; }
}
function _apPackProgressFor(packId) {
  var all = _apReadProgress();
  return all[packId] || {};
}
function _apCompletion(pack) {
  var pp = _apPackProgressFor(pack.id);
  var completed = 0;
  (pack.days || []).forEach(function (d) { if (pp['day_' + d.day]) completed++; });
  var total = (pack.days || []).length;
  return { completed: completed, total: total, pct: total ? Math.round(completed/total * 100) : 0 };
}
function _apNextIncompleteDay(pack) {
  if (!pack || !pack.days || !pack.days.length) return null;
  var pp = _apPackProgressFor(pack.id);
  for (var i = 0; i < pack.days.length; i++) {
    if (!pp['day_' + pack.days[i].day]) return pack.days[i];
  }
  return null; /* all complete */
}
function _apDpEsc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function _apMetaFor(packId) {
  return (typeof PACK_META !== 'undefined') ? (PACK_META[packId] || {}) : {};
}
function _apThemeFor(meta) {
  if (typeof PACK_THEMES === 'undefined') return { primary:'#d4af37', secondary:'#f59e0b', glow:'rgba(212,175,55,0.18)' };
  return PACK_THEMES[meta.theme] || PACK_THEMES['sunrise-gold'];
}

/* ── continueActivePlan + resetActivePlan ── */
function continueActivePlan() {
  var pack = getActivePack();
  if (!pack) {
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
    return;
  }
  var nextDay = _apNextIncompleteDay(pack);
  if (nextDay == null) {
    /* All days complete - open Progress tab on the detail page */
    window._ppDetailTab = 'progress';
    if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pack.id, null);
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
    if (window.showToast) window.showToast('Plan complete. Review your progress.', 'info', 2400);
    return;
  }
  if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pack.id, nextDay.day);
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
}

function resetActivePlan(opts) {
  /* opts.alsoProgress = true wipes packProgress for the active pack too. */
  var pack = getActivePack();
  var prevId = pack ? pack.id : getActivePackId();
  if (prevId && opts && opts.alsoProgress) {
    try {
      var all = _apReadProgress();
      delete all[prevId];
      localStorage.setItem('ee_pack_progress', JSON.stringify(all));
    } catch (e) {}
  }
  clearActivePack();
  /* Refresh My Active Plan if it's the current view */
  if (window.dashboardState && window.dashboardState.currentView === 'active-plan' && window.showWorkspaceView) {
    window.showWorkspaceView('active-plan');
  }
  if (window.showToast) {
    var msg  = (opts && opts.alsoProgress) ? 'Active plan and progress cleared.' : 'Active plan cleared.';
    var undoOpts = prevId ? {
      duration: 5000,
      actionLabel: 'Undo',
      onAction: function () {
        if (prevId && window.setActivePack) window.setActivePack(prevId);
        if (window.dashboardState && window.dashboardState.currentView === 'active-plan' && window.showWorkspaceView) {
          window.showWorkspaceView('active-plan');
        }
      }
    } : { duration: 1800 };
    window.showToast(msg, 'success', undoOpts);
  }
}

/* ════════════════════════════════════════════════════════════════
   STAGE 9 - Pack Completion Ceremony
   ════════════════════════════════════════════════════════════════ */

/* Per-pack victory copy + suggested next pack. Falls back to a generic
   message if a pack is not listed. */
var PACK_COMPLETION_COPY = {
  'morning-mastery':    'You finished Morning Mastery. You built consistency, structure, and a stronger start to your day.',
  'clear-skin':         'You completed Clear Skin Pack. You built a cleaner routine, better tracking, and stronger skin habits.',
  'hair-care':          'You completed Hair Care Pack. You built a simple care system for healthier-looking hair habits.',
  'business-idea':      'You completed Business Idea Pack. You clarified your skills, audience, problem, offer, and next business move.',
  'content-plan':       'You completed Content Plan Pack. You built your pillars, hooks, posting rhythm, and content system.',
  /* Stage 10 promotions */
  'focus-builder':      'You completed Focus Builder. You audited your distractions, built protected blocks, and locked in a real focus system.',
  'style-foundations':  'You completed Style Foundations. You built fit, color, grooming, and outfit rules you can actually run.',
  'side-business':      'You completed Side Business Sprint. You picked a lane, built an offer, validated with real outreach, and made a clear next decision.',
  'youtube-launch':     'You completed YouTube Launch. You defined the channel, shipped your first video, and locked in a weekly publishing rhythm.'
};

var SUGGESTED_NEXT_PACK = {
  'morning-mastery': { id:'focus-builder',    label:'Focus Builder',         reason:'Next step after morning structure: train deep attention.' },
  'clear-skin':      { id:'hair-care',        label:'Hair Care Pack',        reason:'Stack a second appearance habit on top of clear skin.' },
  'hair-care':       { id:'style-foundations',label:'Style Foundations',     reason:'Round out the look with a wardrobe that says what you mean.' },
  'business-idea':   { id:'side-business',    label:'Side Business Sprint',  reason:'Turn the validated idea into a real first customer.' },
  'content-plan':    { id:'youtube-launch',   label:'YouTube Launch',        reason:'Run the system you just built on a flagship platform.' }
};

function isPackComplete(packId) {
  if (!packId) return false;
  if (typeof PLAN_PACKS_DATA === 'undefined') return false;
  var pack = null;
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === packId) { pack = PLAN_PACKS_DATA[i]; break; }
  }
  if (!pack || !pack.days || !pack.days.length) return false;
  var pp = _apPackProgressFor(pack.id);
  for (var d = 0; d < pack.days.length; d++) {
    if (!pp['day_' + pack.days[d].day]) return false;
  }
  return true;
}

function hasSeenPackCompletion(packId) {
  if (!packId) return false;
  try {
    var v = localStorage.getItem('ee_pack_completion_seen_' + packId);
    /* Stage 9 stored 'true'; Stage 11 stores Date.now() string. Both count as seen. */
    return v != null && v !== '' && v !== 'false';
  } catch (e) { return false; }
}
function markPackCompletionSeen(packId) {
  if (!packId) return;
  /* Stage 11: store ms timestamp so we can sort recently-completed packs */
  try { localStorage.setItem('ee_pack_completion_seen_' + packId, String(Date.now())); } catch (e) {}
}
/* Returns the completion timestamp for a pack, or 0 if seen-without-timestamp,
   or -1 if not seen. */
function getPackCompletionTimestamp(packId) {
  if (!packId) return -1;
  try {
    var v = localStorage.getItem('ee_pack_completion_seen_' + packId);
    if (v == null || v === '' || v === 'false') return -1;
    var n = parseInt(v, 10);
    if (!isNaN(n) && n > 0) return n;
    return 0; /* legacy 'true' marker */
  } catch (e) { return -1; }
}
function clearPackCompletionSeen(packId) {
  if (!packId) return;
  try { localStorage.removeItem('ee_pack_completion_seen_' + packId); } catch (e) {}
}

function maybeShowPackCompletion(packId) {
  if (!isPackComplete(packId)) return;
  if (hasSeenPackCompletion(packId)) return;
  markPackCompletionSeen(packId);
  showPackCompletionModal(packId);
  if (window.showToast) window.showToast('Pack complete. Ceremony unlocked.', 'success', 2400);
}

function getSuggestedNextPack(packId) {
  return SUGGESTED_NEXT_PACK[packId] || null;
}

/* ── Restart pack: clear progress + checklist keys for one pack only ── */
function restartPack(packId, options) {
  if (!packId) return;
  options = options || {};
  /* 1. Pack progress - delete the single pack's entry */
  try {
    var all = _apReadProgress();
    delete all[packId];
    localStorage.setItem('ee_pack_progress', JSON.stringify(all));
  } catch (e) {}
  /* 2. Checklist keys for this pack only */
  try {
    var prefix = 'ee_pack_checklist_' + packId + '_day_';
    var toDel = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf(prefix) === 0) toDel.push(k);
    }
    toDel.forEach(function (k) { localStorage.removeItem(k); });
  } catch (e) {}
  /* 3. Notes - only clear if explicitly asked */
  if (options.alsoClearNotes) {
    try {
      localStorage.removeItem('ee_pack_notes_' + packId);
      localStorage.removeItem('ee_pack_notes_' + packId + '_at');
    } catch (e) {}
  }
  /* 4. Completion-seen flag - reset so a fresh run can unlock the ceremony again */
  clearPackCompletionSeen(packId);
  /* 5. Sync the closure's in-memory packProgress cache */
  if (window.EE_PACK_NAV && typeof window.EE_PACK_NAV.reloadProgress === 'function') {
    window.EE_PACK_NAV.reloadProgress();
  }
  /* 6. Set as active and open Day 1 */
  if (window.setActivePack) window.setActivePack(packId);
  if (window.EE_PACK_NAV)   window.EE_PACK_NAV.setPackTarget(packId, 1);
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  if (window.showToast) window.showToast('Pack restarted.', 'success', 1800);
  /* Stage 13: banner reflects the fresh Day 1 state */
  if (typeof updateDailyReminderBanner === 'function') updateDailyReminderBanner();
}

/* ── Modal ── */
function _ensurePackCompletionShell() {
  var modal = document.getElementById('eePackCompleteModal');
  if (modal) return modal;
  modal = document.createElement('div');
  modal.id = 'eePackCompleteModal';
  modal.className = 'pack-complete-modal ee-plan-modal';
  modal.setAttribute('aria-hidden', 'true');
  modal.innerHTML = ''
    + '<div class="ee-plan-backdrop" data-eeclose="1"></div>'
    + '<div class="pack-complete-card ee-plan-dialog" role="dialog" aria-modal="true" aria-labelledby="eePackCompleteTitle">'
    +   '<button class="ee-plan-x" id="eePackCompleteClose" aria-label="Close">&times;</button>'
    +   '<div class="pack-complete-burst" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-1" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-2" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-3" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-4" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-5" aria-hidden="true"></div>'
    +   '<div class="pack-complete-spark pack-complete-spark-6" aria-hidden="true"></div>'
    +   '<div class="pack-complete-head">'
    +     '<div class="pack-complete-kicker">PACK COMPLETE</div>'
    +     '<div class="pack-complete-badge" aria-hidden="true">'
    +       '<span class="pack-complete-badge-icon" id="eePackCompleteIcon">★</span>'
    +     '</div>'
    +     '<h2 class="pack-complete-title" id="eePackCompleteTitle">Pack Complete</h2>'
    +     '<p class="pack-complete-message" id="eePackCompleteMsg"></p>'
    +   '</div>'
    +   '<div class="pack-complete-stats" id="eePackCompleteStats"></div>'
    +   '<div class="pack-complete-next" id="eePackCompleteNext"></div>'
    +   '<div class="pack-complete-actions">'
    +     '<button class="pack-complete-cta pack-complete-cta-primary" id="eePackCompleteReview">Review Progress</button>'
    +     '<button class="pack-complete-cta" id="eePackCompleteNextBtn">Choose Next Pack</button>'
    +     '<button class="pack-complete-cta" id="eePackCompleteRestart">Restart Pack</button>'
    +     '<button class="pack-complete-cta pack-complete-cta-ghost" id="eePackCompleteClear">Clear Active Plan</button>'
    +   '</div>'
    + '</div>';
  document.body.appendChild(modal);

  /* Backdrop + close + Esc handling */
  modal.addEventListener('click', function (e) {
    if (e.target && e.target.getAttribute && e.target.getAttribute('data-eeclose') === '1') closePackCompletionModal();
  });
  var x = modal.querySelector('#eePackCompleteClose');
  if (x) x.addEventListener('click', closePackCompletionModal);
  return modal;
}

function showPackCompletionModal(packId) {
  if (!packId) return;
  var pack = null;
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === packId) { pack = PLAN_PACKS_DATA[i]; break; }
  }
  if (!pack) return;
  var meta  = _apMetaFor(pack.id);
  var theme = _apThemeFor(meta);
  var comp  = _apCompletion(pack);

  var modal = _ensurePackCompletionShell();
  var dialog = modal.querySelector('.pack-complete-card');
  if (dialog) dialog.setAttribute('style', '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';');

  var iconEl  = modal.querySelector('#eePackCompleteIcon');
  if (iconEl) iconEl.textContent = pack.icon || '★';

  var titleEl = modal.querySelector('#eePackCompleteTitle');
  if (titleEl) titleEl.textContent = 'Pack Complete';

  var msgEl = modal.querySelector('#eePackCompleteMsg');
  if (msgEl) msgEl.textContent = PACK_COMPLETION_COPY[pack.id]
    || ('You completed ' + pack.title + '. You ran the full ' + pack.totalDays + '-day system.');

  var statsHost = modal.querySelector('#eePackCompleteStats');
  if (statsHost) {
    statsHost.innerHTML = ''
      + '<div class="pack-complete-stat"><div class="pack-complete-stat-num">100%</div><div class="pack-complete-stat-lbl">Complete</div></div>'
      + '<div class="pack-complete-stat"><div class="pack-complete-stat-num">' + comp.completed + '</div><div class="pack-complete-stat-lbl">Days done</div></div>'
      + '<div class="pack-complete-stat"><div class="pack-complete-stat-num">' + pack.totalDays + '</div><div class="pack-complete-stat-lbl">Duration</div></div>'
      + '<div class="pack-complete-stat"><div class="pack-complete-stat-num">' + _apDpEsc(pack.category) + '</div><div class="pack-complete-stat-lbl">Category</div></div>';
  }

  /* Suggested next pack */
  var nextHost = modal.querySelector('#eePackCompleteNext');
  var nextRef = getSuggestedNextPack(pack.id);
  var nextBtn = modal.querySelector('#eePackCompleteNextBtn');
  if (nextHost && nextRef) {
    var nextPack = null, nextStatus = 'coming-soon';
    if (typeof PLAN_PACKS_DATA !== 'undefined') {
      for (var j = 0; j < PLAN_PACKS_DATA.length; j++) {
        if (PLAN_PACKS_DATA[j].id === nextRef.id) { nextPack = PLAN_PACKS_DATA[j]; break; }
      }
    }
    var nextMeta = _apMetaFor(nextRef.id);
    if (nextMeta && nextMeta.status === 'active') nextStatus = 'active';
    else if (nextPack && nextPack.days && nextPack.days.length) nextStatus = 'active';
    var nextLabel = (nextStatus === 'active') ? 'Start Next Pack' : 'Preview Next Pack';
    if (nextBtn) nextBtn.textContent = nextLabel;
    var nextIcon = (nextPack && nextPack.icon) || '⚡';
    nextHost.innerHTML = ''
      + '<div class="pack-complete-next-kicker">RECOMMENDED NEXT</div>'
      + '<div class="pack-complete-next-row">'
      +   '<div class="pack-complete-next-icon">' + nextIcon + '</div>'
      +   '<div class="pack-complete-next-info">'
      +     '<div class="pack-complete-next-name">' + _apDpEsc(nextRef.label) + (nextStatus !== 'active' ? ' <span class="pack-complete-next-soon">Locked</span>' : '') + '</div>'
      +     '<div class="pack-complete-next-reason">' + _apDpEsc(nextRef.reason) + '</div>'
      +   '</div>'
      + '</div>';
  } else {
    if (nextHost) nextHost.innerHTML = '';
    if (nextBtn)  nextBtn.textContent = 'Browse Plan Packs';
  }

  /* Wire action buttons (re-bind each open so packId stays in scope) */
  function rebind(id, handler) {
    var btn = modal.querySelector('#' + id);
    if (!btn) return;
    var clone = btn.cloneNode(true);
    btn.parentNode.replaceChild(clone, btn);
    clone.addEventListener('click', handler);
  }
  rebind('eePackCompleteReview', function () {
    closePackCompletionModal();
    window._ppDetailTab = 'progress';
    if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pack.id, null);
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });
  rebind('eePackCompleteNextBtn', function () {
    closePackCompletionModal();
    if (nextRef) {
      if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(nextRef.id, null);
      window._ppDetailTab = 'overview';
      if (window.switchDashboardView) window.switchDashboardView('plan-packs');
      if (window.showToast) {
        if (nextStatus !== 'active' && window.showToast) {
          window.showToast('That pack is in development - here is the preview.', 'info', 2400);
        }
      }
    } else {
      if (window.switchDashboardView) window.switchDashboardView('plan-packs');
    }
  });
  rebind('eePackCompleteRestart', function () {
    var msg = 'Restart ' + pack.title + '?\n\nOK = Clear progress + checklists for this pack and open Day 1.\nNotes will stay.\nCancel = Keep everything.';
    if (!window.confirm(msg)) return;
    closePackCompletionModal();
    restartPack(pack.id, { alsoClearNotes: false });
  });
  rebind('eePackCompleteClear', function () {
    closePackCompletionModal();
    if (window.resetActivePlan) window.resetActivePlan({ alsoProgress: false });
  });

  /* Stage 29: stash whatever was focused so we can restore on close. */
  _eeStashFocusOpener('packComplete', modal);
  modal.classList.add('ee-plan-modal-open');
  modal.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
}

function closePackCompletionModal() {
  var modal = document.getElementById('eePackCompleteModal');
  if (!modal) return;
  modal.classList.remove('ee-plan-modal-open');
  modal.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  /* Stage 29: return focus to the element that opened the ceremony. */
  _eeRestoreFocusOpener('packComplete');
}

if (typeof window !== 'undefined') {
  window.isPackComplete            = isPackComplete;
  window.hasSeenPackCompletion     = hasSeenPackCompletion;
  window.markPackCompletionSeen    = markPackCompletionSeen;
  window.maybeShowPackCompletion   = maybeShowPackCompletion;
  window.showPackCompletionModal   = showPackCompletionModal;
  window.closePackCompletionModal  = closePackCompletionModal;
  window.getSuggestedNextPack      = getSuggestedNextPack;
  window.restartPack               = restartPack;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 11 - Today Command Center (cross-pack daily dashboard)
   ════════════════════════════════════════════════════════════════ */

function _td_ymd(d) {
  d = d || new Date();
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

/* A pack is "started" if it has any signal of activity. */
function getStartedPacks() {
  if (typeof PLAN_PACKS_DATA === 'undefined') return [];
  var activeId = null;
  try { activeId = localStorage.getItem('ethos_active_pack'); } catch (e) {}
  var progress = _apReadProgress();

  /* Collect prefixes of started ids from checklist/note keys */
  var checklistIds = {}, notesIds = {};
  try {
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (!k) continue;
      var m;
      if ((m = k.match(/^ee_pack_checklist_(.+)_day_\d+$/))) checklistIds[m[1]] = true;
      else if ((m = k.match(/^ee_pack_notes_(.+?)(?:_at)?$/))) notesIds[m[1]] = true;
    }
  } catch (e) {}

  var seen = {};
  var started = [];
  PLAN_PACKS_DATA.forEach(function (pack) {
    var hit = false;
    if (activeId && pack.id === activeId) hit = true;
    if (progress[pack.id] && Object.keys(progress[pack.id]).length) hit = true;
    if (checklistIds[pack.id]) hit = true;
    if (notesIds[pack.id])     hit = true;
    if (hit && !seen[pack.id]) {
      seen[pack.id] = true;
      started.push(pack);
    }
  });
  return started;
}

function getLastTouchedPackId() {
  /* Priority: ethos_active_pack -> ethos_last_touched_pack -> first started */
  var a = null;
  try { a = localStorage.getItem('ethos_active_pack'); } catch (e) {}
  if (a) return a;
  try { a = localStorage.getItem('ethos_last_touched_pack'); } catch (e) {}
  if (a) return a;
  var s = getStartedPacks();
  return s.length ? s[0].id : null;
}

/* Roll up today's checklist progress across every started pack's
   current next-incomplete day. */
function getTodayChecklistRollup() {
  var started = getStartedPacks();
  var packs = [];
  var totalItems = 0, checkedItems = 0;
  started.forEach(function (pack) {
    if (!pack.days || !pack.days.length) return;
    var nextDay = _apNextIncompleteDay(pack);
    if (!nextDay) return; /* pack is complete - nothing in today's bucket */
    var items = (typeof getChecklistForDay === 'function') ? getChecklistForDay(pack, nextDay) : null;
    if (!items || !items.length) return;
    var state = getDayChecklistState(pack.id, nextDay.day);
    var checked = 0;
    for (var i = 0; i < items.length; i++) { if (isChecklistItemChecked(state, i)) checked++; }
    totalItems   += items.length;
    checkedItems += checked;
    packs.push({
      packId:     pack.id,
      packTitle:  pack.title,
      icon:       pack.icon,
      themeKey:   (PACK_META[pack.id] || {}).theme,
      dayNumber:  nextDay.day,
      dayTitle:   nextDay.title,
      checked:    checked,
      total:      items.length,
      items:      items
    });
  });
  /* Stage 14: surface the real "items checked today" count from the daily log */
  var todayK = todayKey();
  var checkedTodayCount = 0;
  try {
    var log = getDailyCompletionLog();
    if (log[todayK] && typeof log[todayK].checklistItemsChecked === 'number') {
      checkedTodayCount = log[todayK].checklistItemsChecked;
    }
  } catch (e) {}
  return {
    totalItems:   totalItems,
    checkedItems: checkedItems,
    checkedToday: checkedTodayCount,
    percent:      totalItems ? Math.round(checkedItems / totalItems * 100) : 0,
    packs:        packs
  };
}

/* Stage 14 upgrade: real items checked today + completed days today both
   contribute to today's consistency. */
function getConsistencyScore() {
  var rollup       = getTodayChecklistRollup();
  var todayK       = todayKey();
  var bucket       = (typeof getDailyCompletionLog === 'function') ? (getDailyCompletionLog()[todayK] || {}) : {};
  var checkedToday = bucket.checklistItemsChecked || 0;
  var doneToday    = (bucket.completedDays || []).length;
  var score = Math.min(100,
    (checkedToday * 8) +
    (doneToday * 25) +
    Math.round((rollup.percent || 0) * 0.35)
  );
  return score;
}
function getConsistencyLabel(score) {
  if (score >= 75) return 'Locked in';
  if (score >= 50) return 'Strong execution';
  if (score >= 25) return 'Building momentum';
  return 'Start small';
}

/* Returns { packId, pack, ts } of the most-recently-completed pack, or null. */
function getRecentlyCompletedPack() {
  if (typeof PLAN_PACKS_DATA === 'undefined') return null;
  var best = null;
  PLAN_PACKS_DATA.forEach(function (pack) {
    var ts = getPackCompletionTimestamp(pack.id);
    if (ts < 0) return;
    if (!best || ts > best.ts) best = { packId: pack.id, pack: pack, ts: ts };
  });
  return best;
}

/* Snapshot yesterday's missed items when the visible date rolls over.
   Stage 11 keeps this lightweight: at any render after a date change we
   capture whichever items are still unchecked on each started pack's
   current next-incomplete day and store them under the previous date. */
function _td_rolloverYesterdayMissed() {
  var todayKey = _td_ymd();
  var lastKey = null;
  try { lastKey = localStorage.getItem('ethos_today_dashboard_date'); } catch (e) {}
  try { localStorage.setItem('ethos_today_dashboard_date', todayKey); } catch (e) {}
  if (!lastKey || lastKey === todayKey) return;
  /* The day changed - snapshot unchecked items as yesterday's missed */
  var rollup = getTodayChecklistRollup();
  var missed = [];
  rollup.packs.forEach(function (p) {
    var state = getDayChecklistState(p.packId, p.dayNumber);
    p.items.forEach(function (text, i) {
      if (!state[String(i)]) {
        missed.push({
          packId: p.packId, packTitle: p.packTitle,
          dayNumber: p.dayNumber, itemText: text
        });
      }
    });
  });
  try { localStorage.setItem('ethos_yesterday_missed', JSON.stringify(missed)); } catch (e) {}
}

function getYesterdayMissed() {
  try {
    var raw = localStorage.getItem('ethos_yesterday_missed');
    if (!raw) return [];
    var parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) { return []; }
}

/* ── Click action helpers ── */
function openPackDay(packId, dayNumber) {
  if (!packId) return;
  if (window.setActivePack) window.setActivePack(packId);
  if (window.EE_PACK_NAV)   window.EE_PACK_NAV.setPackTarget(packId, dayNumber || null);
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
}
function openPackProgress(packId) {
  if (!packId) return;
  window._ppDetailTab = 'progress';
  if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(packId, null);
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
}
function openPackFromTodayDashboard(packId) {
  if (!packId) return;
  if (typeof PLAN_PACKS_DATA === 'undefined') return;
  var pack = null;
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === packId) { pack = PLAN_PACKS_DATA[i]; break; }
  }
  if (!pack) return;
  var next = _apNextIncompleteDay(pack);
  if (next) openPackDay(packId, next.day);
  else      openPackProgress(packId);
}

/* ── Renderer ── */
function renderTodayDashboard() {
  _td_rolloverYesterdayMissed();

  var started = getStartedPacks();
  var rollup  = getTodayChecklistRollup();
  var score   = getConsistencyScore();
  var label   = getConsistencyLabel(score);
  var recent  = getRecentlyCompletedPack();
  var missed  = getYesterdayMissed();
  var lastId  = getLastTouchedPackId();

  /* Empty-state - nothing started anywhere */
  if (!started.length) {
    return '<div class="ap-today-command">'
      + '<div class="ap-empty ap-empty-compact">'
      +   '<div class="ap-empty-icon">◆</div>'
      +   '<div class="ap-empty-title">Nothing scheduled yet</div>'
      +   '<div class="ap-empty-sub">Start a Plan Pack to begin your daily dashboard.</div>'
      +   '<div class="ap-empty-actions">'
      +     '<button class="ee-active-empty-cta" id="apTdBrowse">Browse Plan Packs</button>'
      +   '</div>'
      + '</div>'
      + '</div>';
  }

  /* ─── 1. Today's Checklist card ─── */
  var checklistRowsHtml = rollup.packs.slice(0, 3).map(function (p) {
    return '<div class="ap-command-row" data-td-pack="' + _apDpEsc(p.packId) + '" data-td-day="' + p.dayNumber + '" '
      +    'role="button" tabindex="0">'
      +      '<span class="ap-command-row-icon">' + (p.icon || '◈') + '</span>'
      +      '<span class="ap-command-row-name">' + _apDpEsc(p.packTitle) + '</span>'
      +      '<span class="ap-command-row-day">Day ' + p.dayNumber + '</span>'
      +      '<span class="ap-command-row-count">' + p.checked + ' / ' + p.total + '</span>'
      +    '</div>';
  }).join('');
  if (rollup.packs.length > 3) {
    checklistRowsHtml += '<div class="ap-command-row-more">+ ' + (rollup.packs.length - 3) + ' more pack' + (rollup.packs.length - 3 > 1 ? 's' : '') + '</div>';
  }
  /* Stage 14: real items-checked-today sub-line */
  var todaySubline = (rollup.checkedToday > 0)
    ? '<div class="ap-command-subline">' + rollup.checkedToday + ' item' + (rollup.checkedToday === 1 ? '' : 's') + ' checked today</div>'
    : '';
  var checklistCard = '<div class="ap-command-card ap-command-card-progress">'
    + '<div class="ap-command-card-h">TODAY\'S CHECKLIST</div>'
    + '<div class="ap-command-progress">'
    +   '<div class="ap-command-progress-row">'
    +     '<span class="ap-command-progress-big">' + rollup.checkedItems + ' / ' + rollup.totalItems + '</span>'
    +     '<span class="ap-command-progress-pct">' + rollup.percent + '%</span>'
    +   '</div>'
    +   '<div class="ap-command-progress-bar"><div class="ap-command-progress-fill" style="width:' + rollup.percent + '%;"></div></div>'
    +   todaySubline
    + '</div>'
    + (checklistRowsHtml ? '<div class="ap-command-rows">' + checklistRowsHtml + '</div>' : '<div class="ap-command-empty">No active day across packs.</div>')
    + '</div>';

  /* ─── 2. Continue Last Pack card ─── */
  var continueCard;
  if (lastId) {
    var lastPack = null;
    for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
      if (PLAN_PACKS_DATA[i].id === lastId) { lastPack = PLAN_PACKS_DATA[i]; break; }
    }
    if (lastPack) {
      var lastComp = _apCompletion(lastPack);
      var lastNext = _apNextIncompleteDay(lastPack);
      var lastTheme = _apThemeFor(_apMetaFor(lastPack.id));
      var lastStyle = '--pp-pri:' + lastTheme.primary + ';--pp-sec:' + lastTheme.secondary + ';--pp-glow:' + lastTheme.glow + ';';
      continueCard = '<div class="ap-command-card ap-command-card-continue" style="' + lastStyle + '">'
        + '<div class="ap-command-card-h">CONTINUE LAST PACK</div>'
        + '<div class="ap-command-pack-row">'
        +   '<div class="ap-command-pack-icon">' + (lastPack.icon || '◈') + '</div>'
        +   '<div class="ap-command-pack-info">'
        +     '<div class="ap-command-pack-name">' + _apDpEsc(lastPack.title) + '</div>'
        +     '<div class="ap-command-pack-meta">' + (lastNext ? 'Day ' + lastNext.day + ' &middot; ' + lastComp.pct + '%' : 'Complete &middot; ' + lastComp.pct + '%') + '</div>'
        +   '</div>'
        + '</div>'
        + '<button class="ap-command-cta" id="apTdContinue" data-td-pack="' + _apDpEsc(lastPack.id) + '">' + (lastNext ? 'Continue' : 'Review Progress') + '</button>'
        + '</div>';
    } else {
      continueCard = '';
    }
  } else {
    continueCard = '';
  }

  /* ─── 3. Missed Yesterday card ─── */
  var missedRowsHtml = missed.slice(0, 3).map(function (m) {
    return '<div class="ap-command-missed-row" data-td-pack="' + _apDpEsc(m.packId) + '" data-td-day="' + m.dayNumber + '" '
      +    'role="button" tabindex="0">'
      +      '<span class="ap-command-missed-text">' + _apDpEsc(m.itemText) + '</span>'
      +      '<span class="ap-command-missed-pack">' + _apDpEsc(m.packTitle) + ' &middot; Day ' + m.dayNumber + '</span>'
      +    '</div>';
  }).join('');
  var missedCard = '<div class="ap-command-card ap-command-card-missed">'
    + '<div class="ap-command-card-h">MISSED YESTERDAY</div>'
    + (missed.length
        ? '<div class="ap-command-missed-count">' + missed.length + ' item' + (missed.length === 1 ? '' : 's') + ' missed</div>'
          + '<div class="ap-missed-list">' + missedRowsHtml + '</div>'
          + (missed.length > 3 ? '<button class="ap-command-cta ap-command-cta-ghost" id="apTdMissedAll">Review Missed</button>' : '')
        : '<div class="ap-command-empty">No missed items. Clean day.</div>')
    + '</div>';

  /* ─── 4. Consistency card ─── */
  /* Stage 12: today's completed day count flows into the consistency sub-label */
  var todayCompletedToday = 0;
  if (typeof getCompletedDaysForDate === 'function') {
    todayCompletedToday = getCompletedDaysForDate(todayKey()).length;
  }
  var consistencySub = todayCompletedToday > 0
    ? (todayCompletedToday + ' day' + (todayCompletedToday === 1 ? '' : 's') + ' completed today')
    : '';
  var consistencyCard = '<div class="ap-command-card ap-command-card-streak">'
    + '<div class="ap-command-card-h">TODAY\'S CONSISTENCY</div>'
    + '<div class="ap-streak-score">'
    +   '<div class="ap-streak-num">' + score + '%</div>'
    +   '<div class="ap-streak-lbl">' + _apDpEsc(label) + '</div>'
    + '</div>'
    + '<div class="ap-command-progress-bar"><div class="ap-command-progress-fill" style="width:' + score + '%;"></div></div>'
    + (consistencySub ? '<div class="ap-command-sub">' + _apDpEsc(consistencySub) + '</div>' : '')
    + '</div>';

  /* ─── Stage 12 - Real Streak card + 7-day activity strip ─── */
  var streakStats = (typeof getRealStreak === 'function') ? getRealStreak() : { currentStreak:0, longestStreak:0, lastActiveDate:null };
  var seven = (typeof getSevenDaySummary === 'function') ? getSevenDaySummary() : [];
  var sevenMax = 0;
  seven.forEach(function (s) { if (s.completedDays > sevenMax) sevenMax = s.completedDays; });
  var dayLetters = ['S','M','T','W','T','F','S'];
  var stripCells = seven.map(function (s) {
    var lvl = 0;
    if (s.completedDays > 0) lvl = (sevenMax <= 1) ? 1 : Math.min(4, Math.ceil((s.completedDays / sevenMax) * 4));
    var heightPct = (s.completedDays > 0) ? (sevenMax <= 1 ? 100 : Math.round(s.completedDays / sevenMax * 100)) : 0;
    var dt = new Date(s.date);
    var letter = dayLetters[dt.getDay()];
    return '<div class="ap-activity-day' + (s.completedDays > 0 ? ' active' : '') + '" title="' + s.date + ' - ' + s.completedDays + ' day' + (s.completedDays === 1 ? '' : 's') + '">'
      + '<div class="ap-activity-bar-track"><div class="ap-activity-bar pp-heatmap-l' + lvl + '" style="height:' + heightPct + '%;"></div></div>'
      + '<div class="ap-activity-letter">' + letter + '</div>'
      + '</div>';
  }).join('');
  var streakBody = streakStats.currentStreak > 0
    ? '<div class="ap-streak-score">'
      +   '<div class="ap-streak-num">' + streakStats.currentStreak + '</div>'
      +   '<div class="ap-streak-lbl">day' + (streakStats.currentStreak === 1 ? '' : 's') + '</div>'
      + '</div>'
      + '<div class="ap-streak-meta">Current streak &middot; Best: ' + streakStats.longestStreak + ' day' + (streakStats.longestStreak === 1 ? '' : 's') + '</div>'
    : '<div class="ap-streak-empty-title">Start today</div>'
      + '<div class="ap-streak-empty-sub">Complete one day to begin your streak.</div>';
  var streakCard = '<div class="ap-command-card ap-streak-card">'
    + '<div class="ap-command-card-h">REAL STREAK</div>'
    + streakBody
    + '<div class="ap-activity-strip">' + stripCells + '</div>'
    + '</div>';

  /* ─── 5. Recently Completed card ─── */
  var completedCard;
  if (recent) {
    var rTheme = _apThemeFor(_apMetaFor(recent.pack.id));
    var rStyle = '--pp-pri:' + rTheme.primary + ';--pp-sec:' + rTheme.secondary + ';--pp-glow:' + rTheme.glow + ';';
    completedCard = '<div class="ap-command-card ap-command-card-completed" style="' + rStyle + '">'
      + '<div class="ap-command-card-h">RECENTLY COMPLETED</div>'
      + '<div class="ap-completed-badge">'
      +   '<div class="ap-completed-icon">' + (recent.pack.icon || '★') + '</div>'
      +   '<div class="ap-completed-name">' + _apDpEsc(recent.pack.title) + '</div>'
      + '</div>'
      + '<button class="ap-command-cta" id="apTdViewCeremony" data-td-pack="' + _apDpEsc(recent.pack.id) + '">View Ceremony</button>'
      + '</div>';
  } else {
    completedCard = '<div class="ap-command-card ap-command-card-completed-empty">'
      + '<div class="ap-command-card-h">RECENTLY COMPLETED</div>'
      + '<div class="ap-command-empty">No completed packs yet.</div>'
      + '</div>';
  }

  return '<div class="ap-today-command">'
    + '<div class="ap-today-command-head">'
    +   '<div class="ap-today-command-title">Today Command Center</div>'
    +   '<div class="ap-today-command-sub">Your daily execution across active packs.</div>'
    + '</div>'
    + '<div class="ap-command-grid">'
    +   checklistCard
    +   (continueCard ? continueCard : '')
    +   streakCard
    +   consistencyCard
    +   missedCard
    +   completedCard
    + '</div>'
    + '</div>';
}

/* Missed items modal (re-uses the ee-plan-modal shell) */
function _ensureMissedModal() {
  var modal = document.getElementById('eeMissedModal');
  if (modal) return modal;
  modal = document.createElement('div');
  modal.id = 'eeMissedModal';
  modal.className = 'ee-plan-modal';
  modal.setAttribute('aria-hidden', 'true');
  modal.innerHTML = ''
    + '<div class="ee-plan-backdrop" data-eeclose="1"></div>'
    + '<div class="ee-plan-dialog" role="dialog" aria-modal="true" aria-label="Yesterday\'s missed items">'
    +   '<button class="ee-plan-x" id="eeMissedClose" aria-label="Close">&times;</button>'
    +   '<div class="ee-plan-head">'
    +     '<div class="ee-plan-kicker">YESTERDAY</div>'
    +     '<h2 class="ee-plan-title">Missed Items</h2>'
    +     '<p class="ee-plan-sub">Items left unchecked when the day rolled over.</p>'
    +   '</div>'
    +   '<div class="ap-missed-list ap-missed-list-full" id="eeMissedList"></div>'
    + '</div>';
  document.body.appendChild(modal);
  modal.addEventListener('click', function (e) {
    if (e.target && e.target.getAttribute && e.target.getAttribute('data-eeclose') === '1') closeMissedModal();
  });
  var x = modal.querySelector('#eeMissedClose');
  if (x) x.addEventListener('click', closeMissedModal);
  return modal;
}
function showMissedModal() {
  var modal = _ensureMissedModal();
  var listHost = modal.querySelector('#eeMissedList');
  var missed = getYesterdayMissed();
  if (listHost) {
    if (!missed.length) {
      listHost.innerHTML = '<div class="ap-command-empty">No missed items.</div>';
    } else {
      listHost.innerHTML = missed.map(function (m) {
        return '<div class="ap-command-missed-row" data-td-pack="' + _apDpEsc(m.packId) + '" data-td-day="' + m.dayNumber + '" role="button" tabindex="0">'
          + '<span class="ap-command-missed-text">' + _apDpEsc(m.itemText) + '</span>'
          + '<span class="ap-command-missed-pack">' + _apDpEsc(m.packTitle) + ' &middot; Day ' + m.dayNumber + '</span>'
          + '</div>';
      }).join('');
      Array.prototype.forEach.call(listHost.querySelectorAll('[data-td-pack]'), function (row) {
        row.addEventListener('click', function () {
          var pid = row.getAttribute('data-td-pack');
          var dn  = parseInt(row.getAttribute('data-td-day'), 10);
          closeMissedModal();
          openPackDay(pid, isNaN(dn) ? null : dn);
        });
      });
    }
  }
  /* Stage 29: focus restore pattern. */
  _eeStashFocusOpener('missed', modal);
  modal.classList.add('ee-plan-modal-open');
  document.body.style.overflow = 'hidden';
}
function closeMissedModal() {
  var modal = document.getElementById('eeMissedModal');
  if (!modal) return;
  modal.classList.remove('ee-plan-modal-open');
  document.body.style.overflow = '';
  _eeRestoreFocusOpener('missed');
}

function attachTodayDashboardEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  /* Empty-state browse */
  var browseEmpty = root.querySelector('#apTdBrowse');
  if (browseEmpty) browseEmpty.addEventListener('click', function () {
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });
  /* Continue */
  var contBtn = root.querySelector('#apTdContinue');
  if (contBtn) contBtn.addEventListener('click', function () {
    openPackFromTodayDashboard(contBtn.getAttribute('data-td-pack'));
  });
  /* Missed: row click + Review All */
  Array.prototype.forEach.call(root.querySelectorAll('.ap-command-card-missed [data-td-pack]'), function (row) {
    row.addEventListener('click', function () {
      var pid = row.getAttribute('data-td-pack');
      var dn  = parseInt(row.getAttribute('data-td-day'), 10);
      openPackDay(pid, isNaN(dn) ? null : dn);
    });
  });
  var reviewBtn = root.querySelector('#apTdMissedAll');
  if (reviewBtn) reviewBtn.addEventListener('click', showMissedModal);
  /* Checklist rows (in the progress card) */
  Array.prototype.forEach.call(root.querySelectorAll('.ap-command-card-progress [data-td-pack]'), function (row) {
    row.addEventListener('click', function () {
      var pid = row.getAttribute('data-td-pack');
      var dn  = parseInt(row.getAttribute('data-td-day'), 10);
      openPackDay(pid, isNaN(dn) ? null : dn);
    });
    row.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        var pid = row.getAttribute('data-td-pack');
        var dn  = parseInt(row.getAttribute('data-td-day'), 10);
        openPackDay(pid, isNaN(dn) ? null : dn);
      }
    });
  });
  /* View Ceremony from recently completed */
  var cerBtn = root.querySelector('#apTdViewCeremony');
  if (cerBtn) cerBtn.addEventListener('click', function () {
    var pid = cerBtn.getAttribute('data-td-pack');
    if (pid && window.showPackCompletionModal) window.showPackCompletionModal(pid);
  });
}

if (typeof window !== 'undefined') {
  window.getStartedPacks               = getStartedPacks;
  window.getTodayChecklistRollup       = getTodayChecklistRollup;
  window.getLastTouchedPackId          = getLastTouchedPackId;
  window.getConsistencyScore           = getConsistencyScore;
  window.getConsistencyLabel           = getConsistencyLabel;
  window.getRecentlyCompletedPack      = getRecentlyCompletedPack;
  window.getYesterdayMissed            = getYesterdayMissed;
  window.getPackCompletionTimestamp    = getPackCompletionTimestamp;
  window.openPackDay                   = openPackDay;
  window.openPackProgress              = openPackProgress;
  window.openPackFromTodayDashboard    = openPackFromTodayDashboard;
  window.renderTodayDashboard          = renderTodayDashboard;
  window.attachTodayDashboardEvents    = attachTodayDashboardEvents;
  window.showMissedModal               = showMissedModal;
  window.closeMissedModal              = closeMissedModal;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 12 - Real daily completion tracking
   ════════════════════════════════════════════════════════════════ */

function todayKey(date) {
  date = date || new Date();
  return date.getFullYear()
    + '-' + String(date.getMonth() + 1).padStart(2, '0')
    + '-' + String(date.getDate()).padStart(2, '0');
}

function getDailyCompletionLog() {
  try {
    var raw = localStorage.getItem('ethos_daily_completion_log');
    if (!raw) return {};
    var p = JSON.parse(raw);
    return (p && typeof p === 'object') ? p : {};
  } catch (e) { return {}; }
}
function saveDailyCompletionLog(log) {
  try { localStorage.setItem('ethos_daily_completion_log', JSON.stringify(log || {})); } catch (e) {}
}

function getDayCompletionTimestamp(packId, dayNumber) {
  if (!packId || dayNumber == null) return 0;
  try {
    var v = localStorage.getItem('ee_pack_day_completed_at_' + packId + '_' + dayNumber);
    if (!v) return 0;
    var n = parseInt(v, 10);
    return isNaN(n) ? 0 : n;
  } catch (e) { return 0; }
}

function _packAndDay(packId, dayNumber) {
  if (typeof PLAN_PACKS_DATA === 'undefined') return [null, null];
  var pack = null, day = null;
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === packId) { pack = PLAN_PACKS_DATA[i]; break; }
  }
  if (pack && pack.days) {
    for (var j = 0; j < pack.days.length; j++) {
      if (pack.days[j].day === dayNumber) { day = pack.days[j]; break; }
    }
  }
  return [pack, day];
}

/* Idempotent. Safe to call twice for the same packId/dayNumber. */
function recordDayCompletion(packId, dayNumber) {
  if (!packId || dayNumber == null) return;
  var now = Date.now();
  var tsKey = 'ee_pack_day_completed_at_' + packId + '_' + dayNumber;
  /* Per-day timestamp - keep the original if one already exists */
  try {
    if (!localStorage.getItem(tsKey)) {
      localStorage.setItem(tsKey, String(now));
    }
  } catch (e) {}

  /* Daily log - dedupe by packId+dayNumber within today's bucket */
  var dateKey = todayKey();
  var log = getDailyCompletionLog();
  if (!log[dateKey]) log[dateKey] = { completedDays: [], checklistItemsChecked: 0, packsTouched: [] };
  var bucket = log[dateKey];
  if (!Array.isArray(bucket.completedDays)) bucket.completedDays = [];
  if (!Array.isArray(bucket.packsTouched))  bucket.packsTouched  = [];

  var dup = false;
  for (var k = 0; k < bucket.completedDays.length; k++) {
    if (bucket.completedDays[k].packId === packId && bucket.completedDays[k].dayNumber === dayNumber) { dup = true; break; }
  }
  if (!dup) {
    var pd = _packAndDay(packId, dayNumber);
    bucket.completedDays.push({
      packId:      packId,
      packTitle:   pd[0] ? pd[0].title : '',
      dayNumber:   dayNumber,
      dayTitle:    pd[1] ? pd[1].title : '',
      completedAt: now
    });
    if (bucket.packsTouched.indexOf(packId) < 0) bucket.packsTouched.push(packId);
    saveDailyCompletionLog(log);
  }
}

function getCompletedDaysForDate(dateKey) {
  var log = getDailyCompletionLog();
  return (log[dateKey] && log[dateKey].completedDays) || [];
}

/* History helper. Returns oldest-to-newest. */
function getCompletionHistory(daysBack) {
  daysBack = (typeof daysBack === 'number' && daysBack > 0) ? daysBack : 30;
  var log = getDailyCompletionLog();
  var out = [];
  var now = new Date();
  for (var i = daysBack - 1; i >= 0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    var key = todayKey(d);
    var bucket = log[key] || {};
    out.push({
      date:           key,
      completedDays:  (bucket.completedDays || []).length,
      checklistItems: bucket.checklistItemsChecked || 0
    });
  }
  return out;
}
function getSevenDaySummary()  { return getCompletionHistory(7);  }
function getThirtyDayHeatmap() { return getCompletionHistory(30); }

/* Per-pack 30-day heatmap. */
function getPackThirtyDayHeatmap(packId) {
  var log = getDailyCompletionLog();
  var out = [];
  var now = new Date();
  for (var i = 29; i >= 0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    var key = todayKey(d);
    var bucket = log[key];
    var count = 0;
    if (bucket && bucket.completedDays) {
      for (var j = 0; j < bucket.completedDays.length; j++) {
        if (bucket.completedDays[j].packId === packId) count++;
      }
    }
    out.push({ date: key, count: count });
  }
  return out;
}

/* Streak: current = consecutive days back from today (or yesterday if today empty).
   longest = max consecutive run across all logged dates. */
function getRealStreak() {
  var log = getDailyCompletionLog();
  var activeDates = Object.keys(log).filter(function (k) {
    return log[k] && Array.isArray(log[k].completedDays) && log[k].completedDays.length > 0;
  }).sort();
  if (!activeDates.length) {
    return { currentStreak: 0, longestStreak: 0, lastActiveDate: null };
  }
  var active = {};
  activeDates.forEach(function (k) { active[k] = true; });

  /* Current streak */
  var now = new Date();
  var hasToday     = !!active[todayKey(now)];
  var yesterdayDt  = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
  var hasYesterday = !!active[todayKey(yesterdayDt)];
  var current = 0;
  if (hasToday || hasYesterday) {
    var cursor = hasToday ? new Date(now.getFullYear(), now.getMonth(), now.getDate()) : yesterdayDt;
    while (active[todayKey(cursor)]) {
      current++;
      cursor = new Date(cursor.getFullYear(), cursor.getMonth(), cursor.getDate() - 1);
    }
  }

  /* Longest streak */
  var longest = 1, run = 1;
  for (var i = 1; i < activeDates.length; i++) {
    var prev = new Date(activeDates[i-1]);
    var curr = new Date(activeDates[i]);
    var diffDays = Math.round((curr - prev) / 86400000);
    if (diffDays === 1) { run++; }
    else { if (run > longest) longest = run; run = 1; }
  }
  if (run > longest) longest = run;

  return {
    currentStreak:  current,
    longestStreak:  Math.max(longest, current),
    lastActiveDate: activeDates[activeDates.length - 1]
  };
}

function formatCompletionDate(timestamp) {
  if (!timestamp) return '';
  var d = new Date(parseInt(timestamp, 10));
  if (isNaN(d.getTime())) return '';
  var now = new Date();
  if (d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate()) {
    return 'Completed today';
  }
  var yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
  if (d.getFullYear() === yesterday.getFullYear() && d.getMonth() === yesterday.getMonth() && d.getDate() === yesterday.getDate()) {
    return 'Completed yesterday';
  }
  return 'Completed on ' + d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

/* One-shot backfill. Writes per-day timestamps for already-completed days
   that have no recorded timestamp. Does NOT touch the daily log (we do
   not know real historical dates), so the streak/heatmap remain honest
   going forward. */
function backfillCompletionDatesIfMissing() {
  try {
    if (localStorage.getItem('ethos_completion_backfill_done') === 'true') return;
    var raw = localStorage.getItem('ee_pack_progress');
    if (raw) {
      var progress = JSON.parse(raw) || {};
      var now = String(Date.now());
      Object.keys(progress).forEach(function (packId) {
        var pp = progress[packId] || {};
        Object.keys(pp).forEach(function (key) {
          var m = key.match(/^day_(\d+)$/);
          if (!m) return;
          var dayNum = parseInt(m[1], 10);
          var tsKey  = 'ee_pack_day_completed_at_' + packId + '_' + dayNum;
          if (!localStorage.getItem(tsKey)) localStorage.setItem(tsKey, now);
        });
      });
    }
    localStorage.setItem('ethos_completion_backfill_done', 'true');
  } catch (e) {}
}

/* ════════════════════════════════════════════════════════════════
   STAGE 14 - Checklist item timestamps + daily-log integration
   ════════════════════════════════════════════════════════════════ */

/* Live scan: count items currently checked whose timestamp lands on dateKey.
   Walks all ee_pack_checklist_* keys. */
function getChecklistItemsCheckedForDate(dateKey) {
  if (!dateKey) return 0;
  var count = 0;
  try {
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (!k || k.indexOf('ee_pack_checklist_') !== 0) continue;
      var raw;
      try { raw = JSON.parse(localStorage.getItem(k) || '{}'); } catch (e2) { continue; }
      if (!raw || typeof raw !== 'object') continue;
      Object.keys(raw).forEach(function (idx) {
        var item = raw[idx];
        if (item === true) return; /* legacy boolean has no date - skip for counting */
        if (item && typeof item === 'object' && item.checked && typeof item.at === 'number' && item.at > 0) {
          var d = new Date(item.at);
          if (!isNaN(d.getTime()) && todayKey(d) === dateKey) count++;
        }
      });
    }
  } catch (e) {}
  return count;
}

/* Recompute and persist the checklistItemsChecked count for a given date
   into the daily completion log. Idempotent. */
function refreshDailyChecklistCount(dateKey) {
  dateKey = dateKey || todayKey();
  var count = getChecklistItemsCheckedForDate(dateKey);
  var log = getDailyCompletionLog();
  if (!log[dateKey]) log[dateKey] = { completedDays: [], checklistItemsChecked: 0, packsTouched: [] };
  log[dateKey].checklistItemsChecked = count;
  saveDailyCompletionLog(log);
  return count;
}

function getChecklistHistory(daysBack) {
  daysBack = (typeof daysBack === 'number' && daysBack > 0) ? daysBack : 30;
  var log = getDailyCompletionLog();
  var out = [];
  var now = new Date();
  for (var i = daysBack - 1; i >= 0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    var key = todayKey(d);
    var bucket = log[key] || {};
    out.push({ date: key, checked: bucket.checklistItemsChecked || 0 });
  }
  return out;
}

/* One-shot backfill: convert legacy boolean checklist items to the new
   { checked, at } shape. Does NOT touch the daily log (avoids inflating
   any historical date). Going forward, normal toggles update the log. */
function backfillChecklistTimestampsIfMissing() {
  try {
    if (localStorage.getItem('ethos_checklist_timestamp_backfill_done') === 'true') return;
    var now = Date.now();
    var keys = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf('ee_pack_checklist_') === 0) keys.push(k);
    }
    keys.forEach(function (k) {
      var raw;
      try { raw = JSON.parse(localStorage.getItem(k) || '{}'); } catch (e) { return; }
      if (!raw || typeof raw !== 'object') return;
      var changed = false;
      Object.keys(raw).forEach(function (idx) {
        var v = raw[idx];
        if (v === true)  { raw[idx] = { checked: true,  at: now }; changed = true; }
        else if (v === false || v == null) { raw[idx] = { checked: false, at: 0 }; changed = true; }
        else if (v && typeof v === 'object' && typeof v.checked === 'boolean') {
          /* Already new shape - leave the timestamp alone. */
          if (typeof v.at !== 'number') { raw[idx] = { checked: v.checked, at: 0 }; changed = true; }
        }
      });
      if (changed) {
        try { localStorage.setItem(k, JSON.stringify(raw)); } catch (e) {}
      }
    });
    localStorage.setItem('ethos_checklist_timestamp_backfill_done', 'true');
  } catch (e) {}
}

if (typeof window !== 'undefined') {
  window.getChecklistItemsCheckedForDate = getChecklistItemsCheckedForDate;
  window.refreshDailyChecklistCount      = refreshDailyChecklistCount;
  window.getChecklistHistory             = getChecklistHistory;
  window.backfillChecklistTimestampsIfMissing = backfillChecklistTimestampsIfMissing;
}

if (typeof window !== 'undefined') {
  window.todayKey                       = todayKey;
  window.getDailyCompletionLog          = getDailyCompletionLog;
  window.saveDailyCompletionLog         = saveDailyCompletionLog;
  window.getDayCompletionTimestamp      = getDayCompletionTimestamp;
  window.recordDayCompletion            = recordDayCompletion;
  window.getCompletedDaysForDate        = getCompletedDaysForDate;
  window.getCompletionHistory           = getCompletionHistory;
  window.getSevenDaySummary             = getSevenDaySummary;
  window.getThirtyDayHeatmap            = getThirtyDayHeatmap;
  window.getPackThirtyDayHeatmap        = getPackThirtyDayHeatmap;
  window.getRealStreak                  = getRealStreak;
  window.formatCompletionDate           = formatCompletionDate;
  window.backfillCompletionDatesIfMissing = backfillCompletionDatesIfMissing;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 13 - Pinned Daily Reminder Banner
   ════════════════════════════════════════════════════════════════ */

function isDailyReminderDismissedToday() {
  try {
    var d = localStorage.getItem('ethos_daily_reminder_dismissed_date') || '';
    return d === todayKey();
  } catch (e) { return false; }
}
function dismissDailyReminderForToday() {
  try { localStorage.setItem('ethos_daily_reminder_dismissed_date', todayKey()); } catch (e) {}
  updateDailyReminderBanner();
}

function getDailyReminderData() {
  var pack = (typeof getActivePack === 'function') ? getActivePack() : null;
  if (!pack) return null;
  var meta  = _apMetaFor(pack.id);
  var theme = _apThemeFor(meta);
  var comp  = _apCompletion(pack);
  if (!pack.days || !pack.days.length) {
    return {
      packId:        pack.id,
      packTitle:     pack.title,
      packIcon:      pack.icon,
      packTheme:     theme,
      dayNumber:     null,
      dayTitle:      null,
      checklistChecked: 0,
      checklistTotal:   0,
      progressPercent:  comp.pct,
      isPackComplete:   false,
      isInDevelopment:  true
    };
  }
  var nextDay = _apNextIncompleteDay(pack);
  if (!nextDay) {
    return {
      packId:        pack.id,
      packTitle:     pack.title,
      packIcon:      pack.icon,
      packTheme:     theme,
      dayNumber:     null,
      dayTitle:      null,
      checklistChecked: 0,
      checklistTotal:   0,
      progressPercent:  100,
      isPackComplete:   true,
      isInDevelopment:  false
    };
  }
  var items = (typeof getChecklistForDay === 'function') ? getChecklistForDay(pack, nextDay) : null;
  var checked = 0, total = 0;
  if (items && items.length) {
    total = items.length;
    var state = getDayChecklistState(pack.id, nextDay.day);
    for (var i = 0; i < total; i++) if (isChecklistItemChecked(state, i)) checked++;
  }
  return {
    packId:           pack.id,
    packTitle:        pack.title,
    packIcon:         pack.icon,
    packTheme:        theme,
    dayNumber:        nextDay.day,
    dayTitle:         nextDay.title,
    checklistChecked: checked,
    checklistTotal:   total,
    progressPercent:  comp.pct,
    isPackComplete:   false,
    isInDevelopment:  false
  };
}

function shouldShowDailyReminderBanner() {
  if (isDailyReminderDismissedToday()) return false;
  var data = getDailyReminderData();
  return !!data;
}

function _ensureDailyReminderContainer() {
  var el = document.getElementById('dailyReminderBanner');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'dailyReminderBanner';
  el.className = 'daily-reminder-banner';
  el.setAttribute('aria-live', 'polite');
  /* Attach inside #dashRoot so the CSS positioning vars resolve. */
  var root = document.getElementById('dashRoot');
  (root || document.body).appendChild(el);
  return el;
}

function renderDailyReminderBanner() {
  var data = getDailyReminderData();
  if (!data) return '';
  var theme = data.packTheme || { primary:'#d4af37', secondary:'#f59e0b', glow:'rgba(212,175,55,0.18)' };
  var styleVars = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';

  /* ── Complete state ── */
  if (data.isPackComplete) {
    return '<div class="daily-reminder-inner daily-reminder-complete" style="' + styleVars + '">'
      + '<div class="daily-reminder-icon" aria-hidden="true">' + _apDpEsc(data.packIcon || '★') + '</div>'
      + '<div class="daily-reminder-main">'
      +   '<div class="daily-reminder-title">' + _apDpEsc(data.packTitle) + ' complete</div>'
      +   '<div class="daily-reminder-sub">Review your progress or choose the next pack.</div>'
      + '</div>'
      + '<div class="daily-reminder-actions">'
      +   '<button class="daily-reminder-btn" data-dr-act="view-completion">View Completion</button>'
      +   '<button class="daily-reminder-btn" data-dr-act="choose-next">Choose Next</button>'
      +   '<button class="daily-reminder-btn daily-reminder-btn-ghost" data-dr-act="clear-active">Clear Active</button>'
      +   '<button class="daily-reminder-dismiss" data-dr-act="dismiss" aria-label="Dismiss for today" title="Dismiss for today">&times;</button>'
      + '</div>'
      + '</div>';
  }

  /* ── In-development state (no days yet) ── */
  if (data.isInDevelopment) {
    return '<div class="daily-reminder-inner daily-reminder-soon" style="' + styleVars + '">'
      + '<div class="daily-reminder-icon" aria-hidden="true">' + _apDpEsc(data.packIcon || '⚡') + '</div>'
      + '<div class="daily-reminder-main">'
      +   '<div class="daily-reminder-title">' + _apDpEsc(data.packTitle) + ' &middot; in development</div>'
      +   '<div class="daily-reminder-sub">Workflow days are still being built.</div>'
      + '</div>'
      + '<div class="daily-reminder-actions">'
      +   '<button class="daily-reminder-btn" data-dr-act="view-active">View Active Plan</button>'
      +   '<button class="daily-reminder-dismiss" data-dr-act="dismiss" aria-label="Dismiss for today" title="Dismiss for today">&times;</button>'
      + '</div>'
      + '</div>';
  }

  /* ── Default - continue state ── */
  var checklistLabel = (data.checklistTotal > 0)
    ? (data.checklistChecked + '/' + data.checklistTotal + ' checklist complete')
    : 'Continue today\'s action';
  /* Stage 14: surface real items checked today if we have a log entry */
  var itemsToday = 0;
  try {
    if (typeof getDailyCompletionLog === 'function') {
      var _logBucket = getDailyCompletionLog()[todayKey()] || {};
      itemsToday = _logBucket.checklistItemsChecked || 0;
    }
  } catch (e) {}
  if (itemsToday > 0) {
    checklistLabel += ' - ' + itemsToday + ' item' + (itemsToday === 1 ? '' : 's') + ' today';
  }
  var progPct = data.checklistTotal > 0
    ? Math.round(data.checklistChecked / data.checklistTotal * 100)
    : data.progressPercent;

  return '<div class="daily-reminder-inner" style="' + styleVars + '">'
    + '<div class="daily-reminder-icon" aria-hidden="true">' + _apDpEsc(data.packIcon || '◈') + '</div>'
    + '<div class="daily-reminder-main">'
    +   '<div class="daily-reminder-title">Today: Day ' + data.dayNumber + ' of ' + _apDpEsc(data.packTitle) + '</div>'
    +   '<div class="daily-reminder-sub">' + _apDpEsc(data.dayTitle || '') + ' &middot; ' + _apDpEsc(checklistLabel) + '</div>'
    +   '<div class="daily-reminder-progress"><div class="daily-reminder-progress-fill" style="width:' + progPct + '%;"></div></div>'
    + '</div>'
    + '<div class="daily-reminder-actions">'
    +   '<button class="daily-reminder-btn daily-reminder-btn-primary" data-dr-act="continue">Continue</button>'
    +   '<button class="daily-reminder-btn" data-dr-act="view-active">View Active Plan</button>'
    /* Stage 32-B: daily-loop shortcut on the pinned banner. Reuses the
       existing daily-reminder-btn class and event delegation through
       data-dr-act - no new wiring, no new CSS. Hidden states (complete /
       in-development) keep their original action rows; only the default
       continue state surfaces Log Today. */
    +   '<button class="daily-reminder-btn" data-dr-act="log-today" id="dailyReminderLogTodayBtn">Log Today</button>'
    +   '<button class="daily-reminder-dismiss" data-dr-act="dismiss" aria-label="Dismiss for today" title="Dismiss for today">&times;</button>'
    + '</div>'
    + '</div>';
}

function attachDailyReminderBannerEvents() {
  var el = document.getElementById('dailyReminderBanner');
  if (!el) return;
  Array.prototype.forEach.call(el.querySelectorAll('[data-dr-act]'), function (btn) {
    btn.addEventListener('click', function () {
      var act = btn.getAttribute('data-dr-act');
      if (act === 'continue') {
        if (window.continueActivePlan) window.continueActivePlan();
      } else if (act === 'view-active') {
        if (window.switchDashboardView) window.switchDashboardView('active-plan');
      } else if (act === 'view-completion') {
        var p = (window.getActivePack ? window.getActivePack() : null);
        if (p && window.showPackCompletionModal) window.showPackCompletionModal(p.id);
      } else if (act === 'choose-next') {
        var pack = (window.getActivePack ? window.getActivePack() : null);
        var nextRef = (pack && window.getSuggestedNextPack) ? window.getSuggestedNextPack(pack.id) : null;
        if (nextRef) {
          if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(nextRef.id, null);
          window._ppDetailTab = 'overview';
        }
        if (window.switchDashboardView) window.switchDashboardView('plan-packs');
      } else if (act === 'clear-active') {
        if (window.resetActivePlan) window.resetActivePlan({ alsoProgress: false });
      } else if (act === 'log-today') {
        /* Stage 32-B: daily-loop shortcut. Routes to the Daily Log
           workspace. Same delegation path as the other banner actions. */
        if (window.switchDashboardView) {
          window.switchDashboardView('daily');
        } else if (window.showToast) {
          window.showToast('Daily Log is unavailable right now.', 'info', 1800);
        }
      } else if (act === 'dismiss') {
        dismissDailyReminderForToday();
      }
    });
  });
}

function updateDailyReminderBanner() {
  var root = document.getElementById('dashRoot');
  var el   = _ensureDailyReminderContainer();
  if (!shouldShowDailyReminderBanner()) {
    el.classList.remove('is-visible');
    el.innerHTML = '';
    if (root) root.classList.remove('banner-visible');
    return;
  }
  el.innerHTML = renderDailyReminderBanner();
  el.classList.add('is-visible');
  if (root) root.classList.add('banner-visible');
  attachDailyReminderBannerEvents();
}

if (typeof window !== 'undefined') {
  window.renderDailyReminderBanner       = renderDailyReminderBanner;
  window.attachDailyReminderBannerEvents = attachDailyReminderBannerEvents;
  window.updateDailyReminderBanner       = updateDailyReminderBanner;
  window.shouldShowDailyReminderBanner   = shouldShowDailyReminderBanner;
  window.getDailyReminderData            = getDailyReminderData;
  window.dismissDailyReminderForToday    = dismissDailyReminderForToday;
  window.isDailyReminderDismissedToday   = isDailyReminderDismissedToday;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 15 - Cross-pack Notes Hub
   ════════════════════════════════════════════════════════════════ */

/* ── Pack notes index ── */
function getPackNotesIndex() {
  if (typeof PLAN_PACKS_DATA === 'undefined') return [];
  var out = [];
  PLAN_PACKS_DATA.forEach(function (pack) {
    if (!pack || !pack.id) return;
    var body = '';
    var at   = 0;
    try { body = localStorage.getItem('ee_pack_notes_' + pack.id) || ''; } catch (e) {}
    try { at   = parseInt(localStorage.getItem('ee_pack_notes_' + pack.id + '_at') || '0', 10) || 0; } catch (e) {}
    if (!body.trim()) return;
    out.push({
      id:         'pack-note-' + pack.id,
      sourceType: 'pack',
      packId:     pack.id,
      title:      pack.title + ' Notes',
      body:       body,
      category:   pack.category || '',
      updatedAt:  at,
      packTitle:  pack.title,
      packIcon:   pack.icon || '◈'
    });
  });
  return out;
}

/* ── General notes ── */
function getGeneralNotes() {
  try {
    var raw = localStorage.getItem('ee_general_notes');
    if (!raw) return [];
    var p = JSON.parse(raw);
    return Array.isArray(p) ? p : [];
  } catch (e) { return []; }
}
function saveGeneralNotes(notes) {
  try { localStorage.setItem('ee_general_notes', JSON.stringify(notes || [])); } catch (e) {}
}
function createGeneralNote(initial) {
  initial = initial || {};
  var now = Date.now();
  var id  = 'note_' + now + '_' + Math.floor(Math.random() * 100000);
  var note = {
    id:            id,
    title:         initial.title || 'Untitled Note',
    body:          initial.body  || '',
    tags:          Array.isArray(initial.tags) ? initial.tags : [],
    linkedPackId:  initial.linkedPackId  || null,
    linkedWorldId: initial.linkedWorldId || null,
    createdAt:     now,
    updatedAt:     now
  };
  var notes = getGeneralNotes();
  notes.unshift(note);
  saveGeneralNotes(notes);
  return id;
}
function updateGeneralNote(noteId, patch) {
  if (!noteId || !patch || typeof patch !== 'object') return false;
  var notes = getGeneralNotes();
  var found = false;
  for (var i = 0; i < notes.length; i++) {
    if (notes[i].id === noteId) {
      if (typeof patch.title === 'string') notes[i].title = patch.title;
      if (typeof patch.body  === 'string') notes[i].body  = patch.body;
      if (Array.isArray(patch.tags))       notes[i].tags  = patch.tags;
      if (patch.linkedPackId !== undefined)  notes[i].linkedPackId  = patch.linkedPackId;
      if (patch.linkedWorldId !== undefined) notes[i].linkedWorldId = patch.linkedWorldId;
      notes[i].updatedAt = Date.now();
      found = true;
      break;
    }
  }
  if (found) saveGeneralNotes(notes);
  return found;
}
function deleteGeneralNote(noteId) {
  if (!noteId) return false;
  var notes = getGeneralNotes();
  var next  = notes.filter(function (n) { return n.id !== noteId; });
  if (next.length === notes.length) return false;
  saveGeneralNotes(next);
  return true;
}

function _generalNoteForHub(note) {
  return {
    id:            note.id,
    sourceType:    'general',
    packId:        note.linkedPackId || null,
    title:         note.title || 'Untitled Note',
    body:          note.body  || '',
    category:      '',
    updatedAt:     note.updatedAt || note.createdAt || 0,
    packTitle:     '',
    packIcon:      '✎',
    tags:          Array.isArray(note.tags) ? note.tags : [],
    linkedPackId:  note.linkedPackId  || null,
    linkedWorldId: note.linkedWorldId || null
  };
}

function getAllNotesForHub() {
  var packNotes = getPackNotesIndex();
  var gen       = getGeneralNotes().map(_generalNoteForHub);
  var all = packNotes.concat(gen);
  all.sort(function (a, b) { return (b.updatedAt || 0) - (a.updatedAt || 0); });
  return all;
}

/* ── UI state ── */
function _nhState() {
  return {
    query:           (typeof window !== 'undefined' && window._notesHubQuery)     || '',
    filter:          (typeof window !== 'undefined' && window._notesHubFilter)    || 'all',
    selectedNoteId:  (typeof window !== 'undefined' && window._notesHubSelectedId) || null
  };
}
function _nhSetState(patch) {
  if (!patch) return;
  if (typeof patch.query  === 'string') window._notesHubQuery    = patch.query;
  if (typeof patch.filter === 'string') window._notesHubFilter   = patch.filter;
  if ('selectedNoteId' in patch)        window._notesHubSelectedId = patch.selectedNoteId;
  try {
    if (typeof patch.query  === 'string') localStorage.setItem('ethos_notes_query',  patch.query);
    if (typeof patch.filter === 'string') localStorage.setItem('ethos_notes_filter', patch.filter);
  } catch (e) {}
}
function _nhRestoreState() {
  try {
    var q = localStorage.getItem('ethos_notes_query')  || '';
    var f = localStorage.getItem('ethos_notes_filter') || 'all';
    if (!window._notesHubQuery)  window._notesHubQuery  = q;
    if (!window._notesHubFilter) window._notesHubFilter = f;
  } catch (e) {}
}

/* ── Filter + match ── */
function _nhMatchSearch(note, q) {
  if (!q) return true;
  var lc = q.toLowerCase();
  function has(v) { return (v || '').toString().toLowerCase().indexOf(lc) >= 0; }
  if (has(note.title))    return true;
  if (has(note.body))     return true;
  if (has(note.packTitle))return true;
  if (has(note.category)) return true;
  if (Array.isArray(note.tags)) {
    for (var i = 0; i < note.tags.length; i++) if (has(note.tags[i])) return true;
  }
  return false;
}
function _nhMatchFilter(note, filter, activePackId) {
  if (filter === 'pack')    return note.sourceType === 'pack';
  if (filter === 'general') return note.sourceType === 'general';
  if (filter === 'active')  {
    if (!activePackId) return false;
    return note.packId === activePackId || note.linkedPackId === activePackId;
  }
  if (filter === 'recent')  {
    return (Date.now() - (note.updatedAt || 0)) < 7 * 86400000;
  }
  return true; /* all */
}

/* ── Navigation ── */
function openPackNotesTab(packId) {
  if (!packId) return;
  window._ppDetailTab = 'notes';
  if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(packId, null);
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
}
function openNoteInHub(noteId) {
  _nhSetState({ selectedNoteId: noteId || null });
  if (window.showWorkspaceView) window.showWorkspaceView('notes');
}

/* ── Renderer ── */
function _nhFormatRel(ts) {
  if (!ts) return 'Never edited';
  var diff = Date.now() - ts;
  if (diff < 60 * 1000) return 'Just now';
  if (diff < 60 * 60 * 1000) return Math.floor(diff / 60000) + 'm ago';
  if (diff < 24 * 60 * 60 * 1000) return Math.floor(diff / 3600000) + 'h ago';
  var d = new Date(ts);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
function _nhSnippet(body, max) {
  body = String(body || '').replace(/\s+/g, ' ').trim();
  max = max || 120;
  return (body.length > max) ? body.slice(0, max) + '...' : body;
}

function _nhRenderEmptyHub() {
  var suggested = (typeof PLAN_PACKS_DATA !== 'undefined') ? PLAN_PACKS_DATA.filter(function (p) {
    return ['morning-mastery','clear-skin','focus-builder'].indexOf(p.id) >= 0;
  }) : [];
  var suggestionsHtml = suggested.map(function (p) {
    var meta  = _apMetaFor(p.id);
    var theme = _apThemeFor(meta);
    return '<button class="notes-empty-suggest" data-nh-act="open-pack" data-nh-pack="' + _apDpEsc(p.id) + '" '
      + 'style="--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';">'
      + '<span class="notes-empty-suggest-icon">' + (p.icon || '◈') + '</span>'
      + '<span class="notes-empty-suggest-title">' + _apDpEsc(p.title) + '</span>'
      + '</button>';
  }).join('');
  return '<div class="notes-hub">'
    + '<div class="notes-hub-head">'
    +   '<h1 class="notes-hub-title">Notes Hub</h1>'
    +   '<p class="notes-hub-sub">All your pack notes, reflections, and ideas in one place.</p>'
    + '</div>'
    + '<div class="notes-empty">'
    +   '<div class="notes-empty-icon">✎</div>'
    +   '<div class="notes-empty-title">No Notes Yet</div>'
    +   '<div class="notes-empty-sub">Your pack reflections and general notes will appear here. Start a pack or create your first note.</div>'
    +   '<div class="notes-empty-actions">'
    +     '<button class="notes-empty-cta notes-empty-cta-primary" data-nh-act="create-note">Create Note</button>'
    +     '<button class="notes-empty-cta" data-nh-act="open-packs">Open Plan Packs</button>'
    +   '</div>'
    +   (suggestionsHtml ? '<div class="notes-empty-suggest-row">' + suggestionsHtml + '</div>' : '')
    + '</div>'
    + '</div>';
}

function _nhRenderListItem(note, isSelected) {
  var badgeClass = (note.sourceType === 'pack') ? 'notes-source-pack' : 'notes-source-general';
  var badgeLabel = (note.sourceType === 'pack') ? 'Pack' : 'General';
  var packLine = '';
  if (note.sourceType === 'pack' && note.packTitle) {
    packLine = '<div class="notes-pack-badge"><span class="notes-pack-icon">' + (note.packIcon || '◈') + '</span><span>' + _apDpEsc(note.packTitle) + '</span></div>';
  }
  return '<button class="notes-list-item' + (isSelected ? ' active' : '') + '" data-nh-act="open-note" data-nh-id="' + _apDpEsc(note.id) + '">'
    + '<div class="notes-list-item-row">'
    +   '<span class="notes-list-item-title">' + _apDpEsc(note.title || 'Untitled Note') + '</span>'
    +   '<span class="notes-source-badge ' + badgeClass + '">' + badgeLabel + '</span>'
    + '</div>'
    + (packLine || '')
    + (note.body ? '<div class="notes-list-item-snippet">' + _apDpEsc(_nhSnippet(note.body, 110)) + '</div>' : '<div class="notes-list-item-snippet notes-list-item-empty">No content yet</div>')
    + '<div class="notes-list-item-meta">' + _apDpEsc(_nhFormatRel(note.updatedAt)) + '</div>'
    + '</button>';
}

function _nhRenderPreview(note) {
  if (note.sourceType === 'pack') {
    return '<div class="notes-preview">'
      + '<div class="notes-preview-head">'
      +   '<div class="notes-preview-title">' + _apDpEsc(note.title) + '</div>'
      +   '<div class="notes-preview-meta">' + _apDpEsc(note.packTitle) + ' &middot; ' + _apDpEsc(_nhFormatRel(note.updatedAt)) + '</div>'
      + '</div>'
      + '<div class="notes-preview-body">' + _apDpEsc(note.body || '').replace(/\n/g, '<br>') + '</div>'
      + '<div class="notes-actions">'
      +   '<button class="notes-action notes-action-primary" data-nh-act="open-pack-notes" data-nh-pack="' + _apDpEsc(note.packId) + '">Open Pack Notes Tab</button>'
      +   '<button class="notes-action" data-nh-act="copy-note" data-nh-id="' + _apDpEsc(note.id) + '">Copy Note</button>'
      + '</div>'
      + '</div>';
  }
  /* General note - editor */
  var tagsStr = (note.tags || []).join(', ');
  return '<div class="notes-editor">'
    + '<input class="notes-editor-title" id="nhEditorTitle" type="text" placeholder="Untitled Note" value="' + _apDpEsc(note.title || '') + '">'
    + '<div class="notes-editor-meta">' + _apDpEsc('General Note · ' + _nhFormatRel(note.updatedAt)) + '</div>'
    + '<textarea class="notes-editor-body" id="nhEditorBody" placeholder="Start writing your note...">' + _apDpEsc(note.body || '') + '</textarea>'
    + '<input class="notes-editor-tags" id="nhEditorTags" type="text" placeholder="Tags (comma-separated)" value="' + _apDpEsc(tagsStr) + '">'
    + '<div class="notes-actions">'
    +   '<button class="notes-action notes-action-primary" data-nh-act="save-general" data-nh-id="' + _apDpEsc(note.id) + '">Save</button>'
    +   '<button class="notes-action notes-action-danger" data-nh-act="delete-general" data-nh-id="' + _apDpEsc(note.id) + '">Delete</button>'
    + '</div>'
    + '</div>';
}

function _nhRenderPreviewEmpty() {
  return '<div class="notes-preview-empty">'
    + '<div class="notes-preview-empty-icon">✎</div>'
    + '<div class="notes-preview-empty-title">Pick a note to read</div>'
    + '<div class="notes-preview-empty-sub">Select a note from the list, or create a new one.</div>'
    + '<button class="notes-empty-cta notes-empty-cta-primary" data-nh-act="create-note">Create Note</button>'
    + '</div>';
}

function renderNotesHub() {
  _nhRestoreState();
  var all = getAllNotesForHub();
  if (!all.length) return _nhRenderEmptyHub();

  var state    = _nhState();
  var activeId = (typeof getActivePackId === 'function') ? getActivePackId() : null;

  /* Stats */
  var packCount    = all.filter(function (n) { return n.sourceType === 'pack'; }).length;
  var generalCount = all.filter(function (n) { return n.sourceType === 'general'; }).length;
  var lastEditedTs = all.length ? all[0].updatedAt : 0;

  /* Filter + search */
  var filtered = all.filter(function (n) {
    return _nhMatchFilter(n, state.filter, activeId) && _nhMatchSearch(n, state.query);
  });

  /* Default selection - first filtered item if nothing chosen or chosen disappeared */
  var selectedId = state.selectedNoteId;
  var selected   = null;
  for (var i = 0; i < filtered.length; i++) {
    if (filtered[i].id === selectedId) { selected = filtered[i]; break; }
  }
  if (!selected && filtered.length) selected = filtered[0];

  var chips = [
    ['all',     'All'],
    ['pack',    'Pack Notes'],
    ['general', 'General'],
    ['active',  'Active Pack'],
    ['recent',  'Recently Edited']
  ];
  var chipsHtml = chips.map(function (c) {
    return '<button class="notes-chip' + (state.filter === c[0] ? ' notes-chip-on' : '') + '" data-nh-filter="' + c[0] + '">' + c[1] + '</button>';
  }).join('');

  var listHtml = filtered.length
    ? filtered.map(function (n) { return _nhRenderListItem(n, selected && n.id === selected.id); }).join('')
    : '<div class="notes-empty-result">No notes match your search.</div>';

  return '<div class="notes-hub">'
    + '<div class="notes-hub-head">'
    +   '<h1 class="notes-hub-title">Notes Hub</h1>'
    +   '<p class="notes-hub-sub">All your pack notes, reflections, and ideas in one place.</p>'
    + '</div>'
    + '<div class="notes-stats">'
    +   '<div class="notes-stat"><div class="notes-stat-num">' + all.length + '</div><div class="notes-stat-lbl">Total Notes</div></div>'
    +   '<div class="notes-stat"><div class="notes-stat-num">' + packCount + '</div><div class="notes-stat-lbl">Pack Notes</div></div>'
    +   '<div class="notes-stat"><div class="notes-stat-num">' + generalCount + '</div><div class="notes-stat-lbl">General Notes</div></div>'
    +   '<div class="notes-stat"><div class="notes-stat-num">' + _apDpEsc(_nhFormatRel(lastEditedTs)) + '</div><div class="notes-stat-lbl">Last Edited</div></div>'
    + '</div>'
    + '<div class="notes-toolbar">'
    +   '<div class="notes-search-wrap">'
    +     '<span class="notes-search-icon">⌕</span>'
    +     '<input class="notes-search" id="nhSearchInput" type="text" placeholder="Search notes..." value="' + _apDpEsc(state.query) + '" autocomplete="off" spellcheck="false">'
    +   '</div>'
    +   '<button class="notes-create-btn" data-nh-act="create-note">Create Note</button>'
    + '</div>'
    + '<div class="notes-filter-chips">' + chipsHtml + '</div>'
    + '<div class="notes-layout">'
    +   '<div class="notes-list">' + listHtml + '</div>'
    +   '<div class="notes-pane">' + (selected ? _nhRenderPreview(selected) : _nhRenderPreviewEmpty()) + '</div>'
    + '</div>'
    + '</div>';
}

function attachNotesHubEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Search (debounced) */
  var search = root.querySelector('#nhSearchInput');
  if (search) {
    var t = null;
    search.addEventListener('input', function () {
      clearTimeout(t);
      var v = search.value;
      t = setTimeout(function () {
        _nhSetState({ query: v });
        if (window.showWorkspaceView) window.showWorkspaceView('notes');
        var again = document.getElementById('nhSearchInput');
        if (again) { again.focus(); try { again.setSelectionRange(again.value.length, again.value.length); } catch (e) {} }
      }, 200);
    });
  }

  /* Filter chips */
  Array.prototype.forEach.call(root.querySelectorAll('[data-nh-filter]'), function (chip) {
    chip.addEventListener('click', function () {
      _nhSetState({ filter: chip.getAttribute('data-nh-filter') || 'all', selectedNoteId: null });
      if (window.showWorkspaceView) window.showWorkspaceView('notes');
    });
  });

  /* Action buttons - delegated */
  function bindActions(scope) {
    Array.prototype.forEach.call(scope.querySelectorAll('[data-nh-act]'), function (btn) {
      btn.addEventListener('click', function (ev) {
        var act = btn.getAttribute('data-nh-act');
        if (act === 'open-note') {
          var nid = btn.getAttribute('data-nh-id');
          _nhSetState({ selectedNoteId: nid });
          if (window.showWorkspaceView) window.showWorkspaceView('notes');
        } else if (act === 'create-note') {
          var newId = createGeneralNote();
          _nhSetState({ selectedNoteId: newId, filter: 'all' });
          if (window.showWorkspaceView) window.showWorkspaceView('notes');
          setTimeout(function () {
            var titleEl = document.getElementById('nhEditorTitle');
            if (titleEl) { titleEl.focus(); titleEl.select(); }
          }, 30);
        } else if (act === 'open-pack-notes') {
          openPackNotesTab(btn.getAttribute('data-nh-pack'));
        } else if (act === 'open-pack') {
          var pid = btn.getAttribute('data-nh-pack');
          if (pid && window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pid, null);
          if (window.switchDashboardView) window.switchDashboardView('plan-packs');
        } else if (act === 'open-packs') {
          if (window.switchDashboardView) window.switchDashboardView('plan-packs');
        } else if (act === 'copy-note') {
          var nid2 = btn.getAttribute('data-nh-id');
          var all  = getAllNotesForHub();
          var note = null;
          for (var i = 0; i < all.length; i++) if (all[i].id === nid2) { note = all[i]; break; }
          if (!note) return;
          var body = (note.title ? note.title + '\n\n' : '') + (note.body || '');
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(body).then(function () {
              if (window.showToast) window.showToast('Note copied to clipboard.', 'success', 1800);
            }, function () {
              if (window.showToast) window.showToast('Could not copy note.', 'error', 1800);
            });
          } else {
            if (window.showToast) window.showToast('Clipboard not available.', 'warning', 1800);
          }
        } else if (act === 'save-general') {
          var sid    = btn.getAttribute('data-nh-id');
          var titleI = document.getElementById('nhEditorTitle');
          var bodyI  = document.getElementById('nhEditorBody');
          var tagsI  = document.getElementById('nhEditorTags');
          var tags   = tagsI ? tagsI.value.split(',').map(function (s) { return s.trim(); }).filter(Boolean) : [];
          updateGeneralNote(sid, {
            title: titleI ? titleI.value : 'Untitled Note',
            body:  bodyI  ? bodyI.value  : '',
            tags:  tags
          });
          if (window.showToast) window.showToast('Note saved.', 'success', 1500);
          if (window.showWorkspaceView) window.showWorkspaceView('notes');
        } else if (act === 'delete-general') {
          var did = btn.getAttribute('data-nh-id');
          if (!window.confirm('Delete this note? This only affects the general note, not pack notes.')) return;
          deleteGeneralNote(did);
          _nhSetState({ selectedNoteId: null });
          if (window.showToast) window.showToast('Note deleted.', 'success', 1500);
          if (window.showWorkspaceView) window.showWorkspaceView('notes');
        }
      });
    });
  }
  bindActions(root);
}

function installStage15NotesHub() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  /* Replace Stage 6 wrapper + closure renderer entirely */
  window.EE_WORKSPACE_RENDER['notes'] = renderNotesHub;
  window.EE_WORKSPACE_EVENTS['notes'] = attachNotesHubEvents;
}

if (typeof window !== 'undefined') {
  window.getPackNotesIndex     = getPackNotesIndex;
  window.getGeneralNotes       = getGeneralNotes;
  window.saveGeneralNotes      = saveGeneralNotes;
  window.createGeneralNote     = createGeneralNote;
  window.updateGeneralNote     = updateGeneralNote;
  window.deleteGeneralNote     = deleteGeneralNote;
  window.getAllNotesForHub     = getAllNotesForHub;
  window.renderNotesHub        = renderNotesHub;
  window.attachNotesHubEvents  = attachNotesHubEvents;
  window.openPackNotesTab      = openPackNotesTab;
  window.openNoteInHub         = openNoteInHub;
  window.installStage15NotesHub = installStage15NotesHub;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 16 - Calendar workspace
   ════════════════════════════════════════════════════════════════ */

/* ── Month state ── */
function getCalendarMonthState() {
  /* Returns { year, month } where month is 0-11 (JS standard). */
  if (window._calMonth && typeof window._calMonth.year === 'number') return window._calMonth;
  var now = new Date();
  var year  = now.getFullYear();
  var month = now.getMonth();
  try {
    var saved = localStorage.getItem('ethos_calendar_month');
    if (saved && /^\d{4}-\d{2}$/.test(saved)) {
      var parts = saved.split('-');
      year  = parseInt(parts[0], 10);
      month = parseInt(parts[1], 10) - 1;
    }
  } catch (e) {}
  window._calMonth = { year: year, month: month };
  return window._calMonth;
}
function setCalendarMonth(year, month) {
  /* month is 0-11. Persist as YYYY-MM (1-indexed). */
  window._calMonth = { year: year, month: month };
  try {
    localStorage.setItem('ethos_calendar_month', String(year) + '-' + String(month + 1).padStart(2, '0'));
  } catch (e) {}
}

function getCalendarActivityForDate(dateKey) {
  var log = getDailyCompletionLog();
  var bucket = log[dateKey] || {};
  var days = Array.isArray(bucket.completedDays) ? bucket.completedDays : [];
  /* Live scan of checklist items lets us count items not yet promoted into the log */
  var checklistItems = (typeof getChecklistItemsCheckedForDate === 'function')
    ? getChecklistItemsCheckedForDate(dateKey) : (bucket.checklistItemsChecked || 0);
  var packsTouched = {};
  days.forEach(function (d) { if (d.packId) packsTouched[d.packId] = true; });
  return {
    completedDays:  days,
    checklistItems: checklistItems,
    packsTouched:   Object.keys(packsTouched)
  };
}

function _cal_intensityFor(completedDays, checklistItems) {
  var raw = completedDays * 2 + Math.floor(checklistItems / 4);
  if (raw < 0) raw = 0;
  if (raw > 4) raw = 4;
  return raw;
}

/* Build a 6x7 grid (always 42 cells, padded with prev/next month days). */
function getCalendarDays(year, month) {
  var first   = new Date(year, month, 1);
  var leading = first.getDay(); /* 0 (Sun) - 6 (Sat) */
  var daysInMonth = new Date(year, month + 1, 0).getDate();
  var start = new Date(year, month, 1 - leading);
  var todayK = todayKey();
  var out = [];
  for (var i = 0; i < 42; i++) {
    var d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    var key = todayKey(d);
    var act = getCalendarActivityForDate(key);
    out.push({
      date:           key,
      year:           d.getFullYear(),
      month:          d.getMonth(),
      day:            d.getDate(),
      isCurrentMonth: (d.getMonth() === month),
      isToday:        (key === todayK),
      completedDays:  act.completedDays.length,
      checklistItems: act.checklistItems,
      packs:          act.packsTouched,
      intensity:      _cal_intensityFor(act.completedDays.length, act.checklistItems)
    });
  }
  return out;
}

function getCalendarMonthSummary(year, month) {
  var totalDays   = new Date(year, month + 1, 0).getDate();
  var completed   = 0;
  var checklist   = 0;
  var activeDates = 0;
  var bestDate    = null;
  var bestScore   = 0;
  for (var i = 1; i <= totalDays; i++) {
    var key  = todayKey(new Date(year, month, i));
    var act  = getCalendarActivityForDate(key);
    completed += act.completedDays.length;
    checklist += act.checklistItems;
    if (act.completedDays.length > 0 || act.checklistItems > 0) activeDates++;
    var score = act.completedDays.length * 4 + act.checklistItems;
    if (score > bestScore) { bestScore = score; bestDate = key; }
  }
  var bestLabel = '-';
  if (bestDate) {
    var d = new Date(bestDate);
    bestLabel = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  }
  return {
    completedDays: completed,
    checklistItems: checklist,
    activeDays:    activeDates,
    bestDate:      bestDate,
    bestLabel:     bestLabel
  };
}

/* ── Selection + navigation ── */
function openCalendarDay(dateKey) {
  window._calSelectedDate = dateKey || null;
  if (window.showWorkspaceView) window.showWorkspaceView('calendar');
}
function goCalendarPrevMonth() {
  var s = getCalendarMonthState();
  var d = new Date(s.year, s.month - 1, 1);
  setCalendarMonth(d.getFullYear(), d.getMonth());
  window._calSelectedDate = null;
  if (window.showWorkspaceView) window.showWorkspaceView('calendar');
}
function goCalendarNextMonth() {
  var s = getCalendarMonthState();
  var d = new Date(s.year, s.month + 1, 1);
  setCalendarMonth(d.getFullYear(), d.getMonth());
  window._calSelectedDate = null;
  if (window.showWorkspaceView) window.showWorkspaceView('calendar');
}
function goCalendarToday() {
  var now = new Date();
  setCalendarMonth(now.getFullYear(), now.getMonth());
  window._calSelectedDate = todayKey();
  if (window.showWorkspaceView) window.showWorkspaceView('calendar');
}

/* ── Day-detail panel ── */
function renderCalendarDayPanel(dateKey) {
  if (!dateKey) {
    return '<div class="calendar-detail-empty">'
      + '<div class="calendar-detail-empty-icon">◻</div>'
      + '<div class="calendar-detail-empty-title">Pick a day</div>'
      + '<div class="calendar-detail-empty-sub">Click any cell to see what you did that day.</div>'
      + '</div>';
  }
  var d = new Date(dateKey);
  var pretty = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
  var act = getCalendarActivityForDate(dateKey);

  if (act.completedDays.length === 0 && act.checklistItems === 0) {
    return '<div class="calendar-detail">'
      + '<div class="calendar-detail-head">'
      +   '<div class="calendar-detail-date">' + _apDpEsc(pretty) + '</div>'
      +   '<div class="calendar-detail-meta">No activity recorded for this day.</div>'
      + '</div>'
      + '<div class="calendar-detail-actions">'
      +   '<button class="calendar-detail-btn" data-cal-act="open-active">Open My Active Plan</button>'
      +   '<button class="calendar-detail-btn" data-cal-act="open-packs">Browse Plan Packs</button>'
      + '</div>'
      + '</div>';
  }

  var daysHtml = act.completedDays.map(function (entry) {
    var packMeta  = _apMetaFor(entry.packId);
    var packTheme = _apThemeFor(packMeta);
    var pStyle = '--pp-pri:' + packTheme.primary + ';--pp-sec:' + packTheme.secondary + ';--pp-glow:' + packTheme.glow + ';';
    return '<div class="calendar-day-entry" style="' + pStyle + '">'
      + '<div class="calendar-day-entry-top">'
      +   '<div class="calendar-day-entry-name">' + _apDpEsc(entry.packTitle || entry.packId) + '</div>'
      +   '<div class="calendar-day-entry-badge">DAY ' + entry.dayNumber + '</div>'
      + '</div>'
      + (entry.dayTitle ? '<div class="calendar-day-entry-title">' + _apDpEsc(entry.dayTitle) + '</div>' : '')
      + '<div class="calendar-day-entry-actions">'
      +   '<button class="calendar-detail-btn" data-cal-act="open-day" data-cal-pack="' + _apDpEsc(entry.packId) + '" data-cal-day="' + entry.dayNumber + '">Open Day</button>'
      +   '<button class="calendar-detail-btn" data-cal-act="open-progress" data-cal-pack="' + _apDpEsc(entry.packId) + '">Open Progress</button>'
      + '</div>'
      + '</div>';
  }).join('');

  /* Pack chips for "Packs Touched" */
  var packChipsHtml = '';
  if (act.packsTouched && act.packsTouched.length) {
    packChipsHtml = act.packsTouched.map(function (pid) {
      var p = null;
      if (typeof PLAN_PACKS_DATA !== 'undefined') {
        for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
          if (PLAN_PACKS_DATA[i].id === pid) { p = PLAN_PACKS_DATA[i]; break; }
        }
      }
      var meta  = _apMetaFor(pid);
      var theme = _apThemeFor(meta);
      var st = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';
      return '<button class="calendar-pack-chip" data-cal-act="open-progress" data-cal-pack="' + _apDpEsc(pid) + '" style="' + st + '">'
        + '<span class="calendar-pack-chip-icon">' + (p && p.icon ? p.icon : '◈') + '</span>'
        + '<span class="calendar-pack-chip-name">' + _apDpEsc(p ? p.title : pid) + '</span>'
        + '</button>';
    }).join('');
  }

  /* Stage 24: daily log snippet for this date */
  var dailyLogHtml = '';
  if (typeof getDailyLog === 'function') {
    var dl = getDailyLog(dateKey);
    if (dl) {
      var snippet = (dl.focus || dl.wins || dl.lesson || '').slice(0, 140);
      dailyLogHtml = '<div class="calendar-detail-section"><div class="calendar-detail-h">DAILY LOG</div>'
        + '<div class="calendar-dailylog-row">'
        +   '<div class="calendar-dailylog-snippet">' + _apDpEsc(snippet || '(empty)') + '</div>'
        +   '<button class="calendar-detail-btn" data-cal-act="open-daily-log" data-cal-date="' + _apDpEsc(dateKey) + '">Open Daily Log</button>'
        + '</div></div>';
    } else {
      dailyLogHtml = '<div class="calendar-detail-section"><div class="calendar-detail-h">DAILY LOG</div>'
        + '<div class="calendar-dailylog-row">'
        +   '<div class="calendar-dailylog-empty">No log yet for this date.</div>'
        +   '<button class="calendar-detail-btn" data-cal-act="open-daily-log" data-cal-date="' + _apDpEsc(dateKey) + '">Create Daily Log</button>'
        + '</div></div>';
    }
  }

  /* Stage 21: tasks due on this date */
  var tasksDueHtml = '';
  if (typeof getTasks === 'function') {
    var dueTasks = getTasks().filter(function (tk) {
      return tk.dueDate === dateKey;
    });
    if (dueTasks.length) {
      tasksDueHtml = '<div class="calendar-detail-section"><div class="calendar-detail-h">TASKS DUE</div>'
        + '<div class="calendar-tasks-list">'
        + dueTasks.map(function (tk) {
            var isDone = tk.status === 'done';
            return '<div class="calendar-task-row' + (isDone ? ' done' : '') + '">'
              + '<button class="calendar-task-check" data-cal-act="' + (isDone ? 'reopen-task' : 'complete-task') + '" data-cal-task="' + _apDpEsc(tk.id) + '" aria-pressed="' + (isDone ? 'true' : 'false') + '">' + (isDone ? '&#10003;' : '') + '</button>'
              + '<span class="calendar-task-title">' + _apDpEsc(tk.title) + '</span>'
              + '<button class="calendar-detail-btn" data-cal-act="open-task" data-cal-task="' + _apDpEsc(tk.id) + '">Open</button>'
              + '</div>';
          }).join('')
        + '</div></div>';
    }
  }
  return '<div class="calendar-detail">'
    + '<div class="calendar-detail-head">'
    +   '<div class="calendar-detail-date">' + _apDpEsc(pretty) + '</div>'
    +   '<div class="calendar-detail-meta">'
    +     act.completedDays.length + ' day' + (act.completedDays.length === 1 ? '' : 's') + ' completed'
    +     ' &middot; '
    +     act.checklistItems + ' checklist item' + (act.checklistItems === 1 ? '' : 's') + ' checked'
    +   '</div>'
    + '</div>'
    + (daysHtml
        ? '<div class="calendar-detail-section"><div class="calendar-detail-h">COMPLETED PACK DAYS</div>'
          + '<div class="calendar-day-entries">' + daysHtml + '</div></div>'
        : '')
    + dailyLogHtml
    + tasksDueHtml
    + (packChipsHtml
        ? '<div class="calendar-detail-section"><div class="calendar-detail-h">PACKS TOUCHED</div>'
          + '<div class="calendar-pack-chips">' + packChipsHtml + '</div></div>'
        : '')
    + '<div class="calendar-detail-actions">'
    +   '<button class="calendar-detail-btn" data-cal-act="open-active">Open My Active Plan</button>'
    +   '<button class="calendar-detail-btn" data-cal-act="open-packs">Browse Plan Packs</button>'
    + '</div>'
    + '</div>';
}

/* ── Active plan strip ── */
function _cal_renderActivePlanCard() {
  var pack = (typeof getActivePack === 'function') ? getActivePack() : null;
  if (!pack) return '';
  if (!pack.days || !pack.days.length) return '';
  var nextDay = _apNextIncompleteDay(pack);
  if (!nextDay) return '';
  var meta  = _apMetaFor(pack.id);
  var theme = _apThemeFor(meta);
  var styleVars = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';
  var items = (typeof getChecklistForDay === 'function') ? getChecklistForDay(pack, nextDay) : null;
  var checked = 0, total = 0;
  if (items && items.length) {
    total = items.length;
    var state = getDayChecklistState(pack.id, nextDay.day);
    for (var i = 0; i < total; i++) if (isChecklistItemChecked(state, i)) checked++;
  }
  var checklistLabel = (total > 0) ? (checked + '/' + total + ' checklist complete') : 'No checklist for this day';
  return '<div class="calendar-active-plan-card" style="' + styleVars + '">'
    + '<div class="calendar-active-plan-head">'
    +   '<div class="calendar-active-plan-kicker">TODAY\'S ACTIVE PLAN</div>'
    +   '<div class="calendar-active-plan-name">' + _apDpEsc(pack.title) + ' &middot; Day ' + nextDay.day + '</div>'
    +   '<div class="calendar-active-plan-sub">' + _apDpEsc(nextDay.title || '') + ' &middot; ' + _apDpEsc(checklistLabel) + '</div>'
    + '</div>'
    + '<button class="calendar-active-plan-cta" data-cal-act="continue">Continue</button>'
    + '</div>';
}

/* ── Empty state (no activity anywhere) ── */
function _cal_hasAnyActivity() {
  var log = getDailyCompletionLog();
  for (var k in log) {
    if (Object.prototype.hasOwnProperty.call(log, k)) {
      var b = log[k] || {};
      if ((b.completedDays && b.completedDays.length) || (b.checklistItemsChecked && b.checklistItemsChecked > 0)) return true;
    }
  }
  return false;
}
function _cal_renderEmptyHub() {
  return '<div class="calendar-hub">'
    + '<div class="calendar-head">'
    +   '<h1 class="calendar-title">Calendar</h1>'
    +   '<p class="calendar-sub">See your plan progress, completed days, and execution history.</p>'
    + '</div>'
    + '<div class="ws-empty calendar-empty">'
    +   '<div class="ws-empty-icon">◻</div>'
    +   '<div class="ws-empty-title">No activity yet</div>'
    +   '<div class="ws-empty-sub">Complete a Plan Pack day or checklist item to start filling your calendar.</div>'
    +   '<div class="ws-empty-actions">'
    +     '<button class="ws-empty-cta ws-empty-cta-primary" data-cal-act="open-active">Open My Active Plan</button>'
    +     '<button class="ws-empty-cta" data-cal-act="open-packs">Browse Plan Packs</button>'
    +   '</div>'
    + '</div>'
    + '</div>';
}

/* ── Main renderer ── */
function renderCalendarWorkspace() {
  if (!_cal_hasAnyActivity()) return _cal_renderEmptyHub();

  var state = getCalendarMonthState();
  var year  = state.year;
  var month = state.month;
  var days  = getCalendarDays(year, month);
  var sum   = getCalendarMonthSummary(year, month);
  var selectedDate = window._calSelectedDate || todayKey();
  /* If selected date isn't in the current month, default to first day of the current month with activity */
  var selDt = new Date(selectedDate);
  if (selDt.getFullYear() !== year || selDt.getMonth() !== month) selectedDate = null;

  var weekLabels = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var weekHeadHtml = weekLabels.map(function (l) {
    return '<div class="cal-week-label">' + l + '</div>';
  }).join('');

  var cellsHtml = days.map(function (c) {
    var cls = 'cal-day cal-day-intensity-' + c.intensity;
    if (!c.isCurrentMonth) cls += ' cal-day-other-month';
    if (c.isToday)         cls += ' cal-day-today';
    if (selectedDate && c.date === selectedDate) cls += ' cal-day-selected';
    var dotsHtml = '';
    if (c.packs.length) {
      dotsHtml = '<div class="cal-day-dots">' + c.packs.slice(0, 3).map(function (pid) {
        var theme = _apThemeFor(_apMetaFor(pid));
        return '<span class="cal-pack-dot" style="background:' + theme.primary + ';box-shadow:0 0 6px ' + theme.glow + ';" title="' + _apDpEsc(pid) + '"></span>';
      }).join('') + '</div>';
    }
    return '<button class="' + cls + '" data-cal-day-cell="' + c.date + '" '
      + 'title="' + c.date + ' - ' + c.completedDays + ' day(s), ' + c.checklistItems + ' item(s)">'
      +   '<span class="cal-day-num">' + c.day + '</span>'
      +   dotsHtml
      + '</button>';
  }).join('');

  var monthLabel = new Date(year, month, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

  return '<div class="calendar-hub">'
    + '<div class="calendar-head">'
    +   '<h1 class="calendar-title">Calendar</h1>'
    +   '<p class="calendar-sub">See your plan progress, completed days, and execution history.</p>'
    + '</div>'
    + _cal_renderActivePlanCard()
    + '<div class="calendar-controls">'
    +   '<div class="calendar-month-row">'
    +     '<button class="calendar-nav-btn" data-cal-act="prev" aria-label="Previous month">&larr;</button>'
    +     '<div class="calendar-month-label">' + _apDpEsc(monthLabel) + '</div>'
    +     '<button class="calendar-nav-btn" data-cal-act="next" aria-label="Next month">&rarr;</button>'
    +     '<button class="calendar-today-btn" data-cal-act="today">Today</button>'
    +   '</div>'
    + '</div>'
    + '<div class="calendar-summary">'
    +   '<div class="calendar-summary-stat"><div class="calendar-summary-num">' + sum.completedDays + '</div><div class="calendar-summary-lbl">Completed Days</div></div>'
    +   '<div class="calendar-summary-stat"><div class="calendar-summary-num">' + sum.checklistItems + '</div><div class="calendar-summary-lbl">Checklist Items</div></div>'
    +   '<div class="calendar-summary-stat"><div class="calendar-summary-num">' + sum.activeDays + '</div><div class="calendar-summary-lbl">Active Days</div></div>'
    +   '<div class="calendar-summary-stat"><div class="calendar-summary-num">' + _apDpEsc(sum.bestLabel) + '</div><div class="calendar-summary-lbl">Best Day</div></div>'
    + '</div>'
    + '<div class="calendar-layout">'
    +   '<div class="calendar-grid-wrap">'
    +     '<div class="calendar-week-head">' + weekHeadHtml + '</div>'
    +     '<div class="calendar-grid">' + cellsHtml + '</div>'
    +   '</div>'
    +   '<div class="calendar-detail-wrap">' + renderCalendarDayPanel(selectedDate || todayKey()) + '</div>'
    + '</div>'
    + '</div>';
}

/* ── Events ── */
function attachCalendarEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  /* Action buttons (delegate by data-cal-act) */
  Array.prototype.forEach.call(root.querySelectorAll('[data-cal-act]'), function (btn) {
    btn.addEventListener('click', function () {
      var act = btn.getAttribute('data-cal-act');
      if (act === 'prev')      return goCalendarPrevMonth();
      if (act === 'next')      return goCalendarNextMonth();
      if (act === 'today')     return goCalendarToday();
      if (act === 'continue')  { if (window.continueActivePlan) window.continueActivePlan(); return; }
      if (act === 'open-active'){ if (window.switchDashboardView) window.switchDashboardView('active-plan'); return; }
      if (act === 'open-packs') { if (window.switchDashboardView) window.switchDashboardView('plan-packs'); return; }
      if (act === 'open-day') {
        var pid = btn.getAttribute('data-cal-pack');
        var dn  = parseInt(btn.getAttribute('data-cal-day'), 10);
        if (pid && !isNaN(dn) && window.openPackDay) window.openPackDay(pid, dn);
        return;
      }
      if (act === 'open-progress') {
        var pid2 = btn.getAttribute('data-cal-pack');
        if (pid2 && window.openPackProgress) window.openPackProgress(pid2);
        return;
      }
      /* Stage 21: tasks-due section actions */
      if (act === 'open-task') {
        var tid = btn.getAttribute('data-cal-task');
        if (tid && window.openTaskInWorkspace) window.openTaskInWorkspace(tid);
        return;
      }
      if (act === 'complete-task') {
        var tid2 = btn.getAttribute('data-cal-task');
        if (tid2 && window.completeTask) {
          window.completeTask(tid2);
          if (window.showToast) window.showToast('Task completed.', 'success', 1200);
          if (window.showWorkspaceView) window.showWorkspaceView('calendar');
        }
        return;
      }
      if (act === 'reopen-task') {
        var tid3 = btn.getAttribute('data-cal-task');
        if (tid3 && window.reopenTask) {
          window.reopenTask(tid3);
          if (window.showWorkspaceView) window.showWorkspaceView('calendar');
        }
        return;
      }
      /* Stage 24: jump to Daily Log workspace for the panel date */
      if (act === 'open-daily-log') {
        var dk = btn.getAttribute('data-cal-date');
        if (dk && window.openDailyLogDate) window.openDailyLogDate(dk);
        return;
      }
    });
  });
  /* Day cell click */
  Array.prototype.forEach.call(root.querySelectorAll('[data-cal-day-cell]'), function (cell) {
    cell.addEventListener('click', function () {
      var dk = cell.getAttribute('data-cal-day-cell');
      if (dk) openCalendarDay(dk);
    });
  });
}

function installStage16Calendar() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  window.EE_WORKSPACE_RENDER['calendar'] = renderCalendarWorkspace;
  window.EE_WORKSPACE_EVENTS['calendar'] = attachCalendarEvents;
}

if (typeof window !== 'undefined') {
  window.renderCalendarWorkspace    = renderCalendarWorkspace;
  window.attachCalendarEvents       = attachCalendarEvents;
  window.installStage16Calendar     = installStage16Calendar;
  window.getCalendarMonthState      = getCalendarMonthState;
  window.setCalendarMonth           = setCalendarMonth;
  window.getCalendarDays            = getCalendarDays;
  window.getCalendarActivityForDate = getCalendarActivityForDate;
  window.getCalendarMonthSummary    = getCalendarMonthSummary;
  window.openCalendarDay            = openCalendarDay;
  window.renderCalendarDayPanel     = renderCalendarDayPanel;
  window.goCalendarPrevMonth        = goCalendarPrevMonth;
  window.goCalendarNextMonth        = goCalendarNextMonth;
  window.goCalendarToday            = goCalendarToday;
}

