/* ── Usage tracking ── */
function getTemplateUsage() {
  try {
    var raw = localStorage.getItem('ethos_templates_used');
    if (!raw) return [];
    var p = JSON.parse(raw);
    return Array.isArray(p) ? p : [];
  } catch (e) { return []; }
}
function _saveTemplateUsage(usage) {
  try { localStorage.setItem('ethos_templates_used', JSON.stringify(usage || [])); } catch (e) {}
}
function recordTemplateUsed(templateId, createdNoteId) {
  if (!templateId) return;
  var usage = getTemplateUsage();
  usage.unshift({
    templateId:    templateId,
    usedAt:        Date.now(),
    createdNoteId: createdNoteId || null
  });
  /* Keep the log bounded - last 200 entries is plenty */
  if (usage.length > 200) usage = usage.slice(0, 200);
  _saveTemplateUsage(usage);
}
function getTemplateById(id) {
  for (var i = 0; i < DASHBOARD_TEMPLATES.length; i++) {
    if (DASHBOARD_TEMPLATES[i].id === id) return DASHBOARD_TEMPLATES[i];
  }
  return null;
}

/* ── UI state ── */
function _tplState() {
  return {
    query:              (typeof window !== 'undefined' && window._templatesQuery)      || '',
    filter:             (typeof window !== 'undefined' && window._templatesFilter)     || 'all',
    selectedTemplateId: (typeof window !== 'undefined' && window._templatesSelectedId) || null
  };
}
function _tplSetState(patch) {
  if (!patch) return;
  if (typeof patch.query  === 'string') window._templatesQuery    = patch.query;
  if (typeof patch.filter === 'string') window._templatesFilter   = patch.filter;
  if ('selectedTemplateId' in patch)    window._templatesSelectedId = patch.selectedTemplateId;
  try {
    if (typeof patch.query  === 'string') localStorage.setItem('ethos_templates_query',  patch.query);
    if (typeof patch.filter === 'string') localStorage.setItem('ethos_templates_filter', patch.filter);
  } catch (e) {}
}
function _tplRestoreState() {
  try {
    var q = localStorage.getItem('ethos_templates_query')  || '';
    var f = localStorage.getItem('ethos_templates_filter') || 'all';
    if (!window._templatesQuery)  window._templatesQuery  = q;
    if (!window._templatesFilter) window._templatesFilter = f;
  } catch (e) {}
}

function _tplMatchSearch(tpl, q) {
  if (!q) return true;
  var lc = q.toLowerCase();
  function has(v) { return (v || '').toString().toLowerCase().indexOf(lc) >= 0; }
  if (has(tpl.title) || has(tpl.category) || has(tpl.description) || has(tpl.body)) return true;
  if (Array.isArray(tpl.tags)) {
    for (var i = 0; i < tpl.tags.length; i++) if (has(tpl.tags[i])) return true;
  }
  return false;
}
function _tplMatchFilter(tpl, filter) {
  if (filter === 'all') return true;
  if (filter === 'daily')      return tpl.category === 'Daily'   || (tpl.tags || []).indexOf('daily') >= 0;
  if (filter === 'reflection') return tpl.category === 'Reflection' || (tpl.tags || []).indexOf('reflection') >= 0;
  if (filter === 'packs')      return tpl.category === 'Packs';
  if (filter === 'content')    return tpl.category === 'Content';
  if (filter === 'business')   return tpl.category === 'Business';
  if (filter === 'knowledge')  return tpl.category === 'Knowledge';
  return true;
}
function getFilteredTemplates(query, filter) {
  return DASHBOARD_TEMPLATES.filter(function (t) {
    return _tplMatchFilter(t, filter || 'all') && _tplMatchSearch(t, query || '');
  });
}

/* ── Actions ── */
function _tplUseTemplate(templateId) {
  var tpl = getTemplateById(templateId);
  if (!tpl) return;
  if (typeof createGeneralNote !== 'function') return;
  var noteId = createGeneralNote({
    title:         tpl.title,
    body:          tpl.body || '',
    tags:          (tpl.tags || []).slice(),
    linkedPackId:  tpl.linkedPackId  || null,
    linkedWorldId: tpl.linkedWorldId || null
  });
  recordTemplateUsed(tpl.id, noteId);
  /* Hand off to Notes Hub with the new note pre-selected */
  window._notesHubSelectedId = noteId;
  window._notesHubFilter     = 'all';
  window._notesHubQuery      = '';
  if (window.switchDashboardView) window.switchDashboardView('notes');
  if (window.showToast) window.showToast('Template applied. New note ready.', 'success', 1800);
}
function _tplCopyTemplate(templateId) {
  var tpl = getTemplateById(templateId);
  if (!tpl) return;
  var body = tpl.body || '';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(body).then(function () {
      if (window.showToast) window.showToast('Template copied to clipboard.', 'success', 1800);
    }, function () {
      if (window.showToast) window.showToast('Could not copy template.', 'error', 1800);
    });
  } else {
    if (window.showToast) window.showToast('Clipboard not available.', 'warning', 1800);
  }
}

/* ── Renderer ── */
function _tplCard(tpl, isSelected) {
  var tagsHtml = (tpl.tags || []).slice(0, 3).map(function (t) {
    return '<span class="template-tag">' + _apDpEsc(t) + '</span>';
  }).join('');
  return '<div class="template-card' + (isSelected ? ' active' : '') + '" data-tpl-id="' + _apDpEsc(tpl.id) + '">'
    + '<div class="template-card-head">'
    +   '<span class="template-card-icon">' + (tpl.icon || '◈') + '</span>'
    +   '<span class="template-card-category">' + _apDpEsc(tpl.category) + '</span>'
    + '</div>'
    + '<div class="template-card-title">' + _apDpEsc(tpl.title) + '</div>'
    + '<div class="template-card-desc">' + _apDpEsc(tpl.description) + '</div>'
    + (tagsHtml ? '<div class="template-tags">' + tagsHtml + '</div>' : '')
    + '<div class="template-card-actions">'
    +   '<button class="template-card-btn" data-tpl-act="preview" data-tpl-id="' + _apDpEsc(tpl.id) + '">Preview</button>'
    +   '<button class="template-card-btn template-card-btn-primary" data-tpl-act="use" data-tpl-id="' + _apDpEsc(tpl.id) + '">Use Template</button>'
    + '</div>'
    + '</div>';
}
function _tplPreviewPane(tpl) {
  if (!tpl) {
    return '<div class="template-preview-empty">'
      + '<div class="template-preview-empty-icon">📄</div>'
      + '<div class="template-preview-empty-title">Pick a template</div>'
      + '<div class="template-preview-empty-sub">Select a card to preview the full structure before using it.</div>'
      + '</div>';
  }
  var tagsHtml = (tpl.tags || []).map(function (t) {
    return '<span class="template-tag">' + _apDpEsc(t) + '</span>';
  }).join('');
  var linkedHtml = '';
  if (tpl.linkedPackId && typeof PLAN_PACKS_DATA !== 'undefined') {
    var lp = null;
    for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
      if (PLAN_PACKS_DATA[i].id === tpl.linkedPackId) { lp = PLAN_PACKS_DATA[i]; break; }
    }
    if (lp) {
      linkedHtml = '<div class="template-preview-linked"><span class="template-preview-linked-lbl">LINKED PACK</span><span class="template-preview-linked-name">' + (lp.icon || '◈') + ' ' + _apDpEsc(lp.title) + '</span></div>';
    }
  }
  return '<div class="template-preview">'
    + '<div class="template-preview-head">'
    +   '<div class="template-preview-icon">' + (tpl.icon || '◈') + '</div>'
    +   '<div class="template-preview-meta">'
    +     '<div class="template-preview-category">' + _apDpEsc(tpl.category) + '</div>'
    +     '<h2 class="template-preview-title">' + _apDpEsc(tpl.title) + '</h2>'
    +     '<p class="template-preview-desc">' + _apDpEsc(tpl.description) + '</p>'
    +   '</div>'
    + '</div>'
    + (tagsHtml ? '<div class="template-tags template-preview-tags">' + tagsHtml + '</div>' : '')
    + linkedHtml
    + '<pre class="template-preview-body">' + _apDpEsc(tpl.body || '') + '</pre>'
    + '<div class="template-actions">'
    +   '<button class="template-action template-action-primary" data-tpl-act="use" data-tpl-id="' + _apDpEsc(tpl.id) + '">Use Template</button>'
    +   '<button class="template-action" data-tpl-act="copy" data-tpl-id="' + _apDpEsc(tpl.id) + '">Copy Template</button>'
    +   '<button class="template-action template-action-ghost" data-tpl-act="close-preview">Close Preview</button>'
    + '</div>'
    + '</div>';
}

function renderTemplatesHub() {
  _tplRestoreState();
  var state = _tplState();
  var usage = getTemplateUsage();

  /* Stats */
  var totalTemplates = DASHBOARD_TEMPLATES.length;
  var categories = {};
  DASHBOARD_TEMPLATES.forEach(function (t) { if (t.category) categories[t.category] = true; });
  var notesCreated = usage.filter(function (u) { return !!u.createdNoteId; }).length;
  var recentlyUsed = (function () {
    var cutoff = Date.now() - 30 * 86400000;
    return usage.filter(function (u) { return (u.usedAt || 0) >= cutoff; }).length;
  })();

  /* Filtered list */
  var filtered = getFilteredTemplates(state.query, state.filter);

  /* Default selection */
  var selectedId = state.selectedTemplateId;
  var selected   = selectedId ? getTemplateById(selectedId) : null;
  if (!selected && filtered.length) selected = filtered[0];

  var chips = [
    ['all',        'All'],
    ['daily',      'Daily'],
    ['packs',      'Packs'],
    ['content',    'Content'],
    ['business',   'Business'],
    ['knowledge',  'Knowledge'],
    ['reflection', 'Reflection']
  ];
  var chipsHtml = chips.map(function (c) {
    return '<button class="templates-chip' + (state.filter === c[0] ? ' templates-chip-on' : '') + '" data-tpl-filter="' + c[0] + '">' + c[1] + '</button>';
  }).join('');

  var gridHtml = filtered.length
    ? filtered.map(function (t) { return _tplCard(t, selected && t.id === selected.id); }).join('')
    : '<div class="templates-empty-result">No templates match your search.</div>';

  return '<div class="templates-hub">'
    + '<div class="templates-head">'
    +   '<h1 class="templates-title">Templates</h1>'
    +   '<p class="templates-sub">Use proven structures for reflection, planning, content, business, and growth.</p>'
    + '</div>'
    + '<div class="templates-stats">'
    +   '<div class="templates-stat"><div class="templates-stat-num">' + totalTemplates + '</div><div class="templates-stat-lbl">Total Templates</div></div>'
    +   '<div class="templates-stat"><div class="templates-stat-num">' + Object.keys(categories).length + '</div><div class="templates-stat-lbl">Categories</div></div>'
    +   '<div class="templates-stat"><div class="templates-stat-num">' + recentlyUsed + '</div><div class="templates-stat-lbl">Recently Used</div></div>'
    +   '<div class="templates-stat"><div class="templates-stat-num">' + notesCreated + '</div><div class="templates-stat-lbl">Notes Created</div></div>'
    + '</div>'
    + '<div class="templates-toolbar">'
    +   '<div class="templates-search-wrap">'
    +     '<span class="templates-search-icon">⌕</span>'
    +     '<input class="templates-search" id="tplSearchInput" type="text" placeholder="Search templates..." value="' + _apDpEsc(state.query) + '" autocomplete="off" spellcheck="false">'
    +   '</div>'
    + '</div>'
    + '<div class="templates-filter-chips">' + chipsHtml + '</div>'
    + '<div class="templates-layout">'
    +   '<div class="templates-grid">' + gridHtml + '</div>'
    +   '<div class="templates-pane">' + _tplPreviewPane(selected) + '</div>'
    + '</div>'
    + '</div>';
}

function attachTemplatesHubEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Search (debounced) */
  var search = root.querySelector('#tplSearchInput');
  if (search) {
    var t = null;
    search.addEventListener('input', function () {
      clearTimeout(t);
      var v = search.value;
      t = setTimeout(function () {
        _tplSetState({ query: v });
        if (window.showWorkspaceView) window.showWorkspaceView('templates');
        var again = document.getElementById('tplSearchInput');
        if (again) { again.focus(); try { again.setSelectionRange(again.value.length, again.value.length); } catch (e) {} }
      }, 200);
    });
  }

  /* Filter chips */
  Array.prototype.forEach.call(root.querySelectorAll('[data-tpl-filter]'), function (chip) {
    chip.addEventListener('click', function () {
      _tplSetState({ filter: chip.getAttribute('data-tpl-filter') || 'all', selectedTemplateId: null });
      if (window.showWorkspaceView) window.showWorkspaceView('templates');
    });
  });

  /* Card body click selects (for preview) */
  Array.prototype.forEach.call(root.querySelectorAll('.template-card'), function (card) {
    card.addEventListener('click', function (ev) {
      /* Skip if the click was on a button - buttons handle their own actions */
      var btn = ev.target.closest ? ev.target.closest('[data-tpl-act]') : null;
      if (btn) return;
      var tid = card.getAttribute('data-tpl-id');
      _tplSetState({ selectedTemplateId: tid });
      if (window.showWorkspaceView) window.showWorkspaceView('templates');
    });
  });

  /* Action buttons (delegated) */
  Array.prototype.forEach.call(root.querySelectorAll('[data-tpl-act]'), function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.stopPropagation();
      var act = btn.getAttribute('data-tpl-act');
      var tid = btn.getAttribute('data-tpl-id');
      if (act === 'preview') {
        _tplSetState({ selectedTemplateId: tid });
        if (window.showWorkspaceView) window.showWorkspaceView('templates');
      } else if (act === 'use') {
        _tplUseTemplate(tid);
      } else if (act === 'copy') {
        _tplCopyTemplate(tid);
      } else if (act === 'close-preview') {
        _tplSetState({ selectedTemplateId: null });
        if (window.showWorkspaceView) window.showWorkspaceView('templates');
      }
    });
  });
}

function installStage17TemplatesHub() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  window.EE_WORKSPACE_RENDER['templates'] = renderTemplatesHub;
  window.EE_WORKSPACE_EVENTS['templates'] = attachTemplatesHubEvents;
}

if (typeof window !== 'undefined') {
  window.DASHBOARD_TEMPLATES        = DASHBOARD_TEMPLATES;
  window.getTemplateById            = getTemplateById;
  window.getFilteredTemplates       = getFilteredTemplates;
  window.getTemplateUsage           = getTemplateUsage;
  window.recordTemplateUsed         = recordTemplateUsed;
  window.renderTemplatesHub         = renderTemplatesHub;
  window.attachTemplatesHubEvents   = attachTemplatesHubEvents;
  window.installStage17TemplatesHub = installStage17TemplatesHub;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 18 - Tags workspace (cross-system tag index)
   ════════════════════════════════════════════════════════════════ */

function _tagSlug(text) {
  return String(text == null ? '' : text)
    .toLowerCase()
    .trim()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
function _tagLabel(slug) {
  return String(slug || '').split('-').filter(Boolean).map(function (w) {
    if (w === 'ai') return 'AI';
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(' ');
}

function _tagAddSource(index, rawTag, source) {
  if (!rawTag) return;
  var slug = _tagSlug(rawTag);
  if (!slug) return;
  if (!index[slug]) {
    index[slug] = {
      slug:       slug,
      label:      String(rawTag).trim(),
      total:      0,
      sources:    { packs: [], templates: [], notes: [], packNotes: [] },
      counts:     { packs: 0, templates: 0, notes: 0, packNotes: 0 },
      categories: {}
    };
  }
  /* Prefer the longer / capitalized label so "Content" wins over "content" */
  var existing = index[slug].label;
  if (String(rawTag).length > existing.length || /[A-Z]/.test(String(rawTag))) {
    index[slug].label = String(rawTag).trim();
  }
  var bucket = null;
  if      (source.type === 'pack')      bucket = 'packs';
  else if (source.type === 'template')  bucket = 'templates';
  else if (source.type === 'note')      bucket = 'notes';
  else if (source.type === 'pack-note') bucket = 'packNotes';
  if (!bucket) return;
  /* Dedupe by id within bucket */
  var arr = index[slug].sources[bucket];
  for (var i = 0; i < arr.length; i++) if (arr[i].id === source.id) return;
  arr.push(source);
  index[slug].counts[bucket]++;
  index[slug].total++;
  if (source.category) index[slug].categories[source.category] = true;
}

function getTagsIndex() {
  var index = {};

  /* ── 1. Packs (PLAN_PACKS_DATA + teasers via buildMarketplaceEntries) ── */
  if (typeof buildMarketplaceEntries === 'function') {
    var entries = buildMarketplaceEntries();
    entries.forEach(function (e) {
      var src = {
        id: e.id, title: e.title, type: 'pack',
        category: e.category || '', status: e.status || 'active',
        icon: e.icon || '◈', updatedAt: 0
      };
      /* Category itself counts as a tag */
      if (e.category) _tagAddSource(index, e.category, src);
      /* PACK_META tags */
      if (e.tags && e.tags.length) {
        e.tags.forEach(function (t) { _tagAddSource(index, t, src); });
      }
    });
  }

  /* ── 2. Templates ── */
  if (typeof DASHBOARD_TEMPLATES !== 'undefined' && DASHBOARD_TEMPLATES.length) {
    var tplUsage = (typeof getTemplateUsage === 'function') ? getTemplateUsage() : [];
    var lastUsedMap = {};
    tplUsage.forEach(function (u) {
      if (!u || !u.templateId) return;
      if (!lastUsedMap[u.templateId] || (u.usedAt || 0) > lastUsedMap[u.templateId]) {
        lastUsedMap[u.templateId] = u.usedAt || 0;
      }
    });
    DASHBOARD_TEMPLATES.forEach(function (tpl) {
      var src = {
        id: tpl.id, title: tpl.title, type: 'template',
        category: tpl.category || '', icon: tpl.icon || '◈',
        updatedAt: lastUsedMap[tpl.id] || 0
      };
      if (tpl.category) _tagAddSource(index, tpl.category, src);
      if (tpl.tags && tpl.tags.length) {
        tpl.tags.forEach(function (t) { _tagAddSource(index, t, src); });
      }
    });
  }

  /* ── 3. General notes ── */
  if (typeof getGeneralNotes === 'function') {
    getGeneralNotes().forEach(function (n) {
      var src = {
        id: n.id, title: n.title || 'Untitled Note', type: 'note',
        category: '', updatedAt: n.updatedAt || n.createdAt || 0,
        body: n.body || ''
      };
      if (Array.isArray(n.tags)) {
        n.tags.forEach(function (t) { _tagAddSource(index, t, src); });
      }
    });
  }

  /* ── 4. Pack notes - derive tags from the pack's PACK_META + category ── */
  if (typeof getPackNotesIndex === 'function') {
    getPackNotesIndex().forEach(function (pn) {
      var meta = (typeof PACK_META !== 'undefined') ? (PACK_META[pn.packId] || {}) : {};
      var src = {
        id: pn.id, title: pn.title, type: 'pack-note',
        category: pn.category || '', icon: pn.packIcon || '◈',
        packId: pn.packId, packTitle: pn.packTitle, updatedAt: pn.updatedAt || 0
      };
      if (pn.category) _tagAddSource(index, pn.category, src);
      if (meta.tags && meta.tags.length) {
        meta.tags.forEach(function (t) { _tagAddSource(index, t, src); });
      }
    });
  }

  /* Flatten categories object to array + sort by total descending */
  var out = Object.keys(index).map(function (k) {
    var t = index[k];
    t.categories = Object.keys(t.categories || {});
    return t;
  });
  out.sort(function (a, b) {
    if (b.total !== a.total) return b.total - a.total;
    return a.label.localeCompare(b.label);
  });
  return out;
}

function getTagBySlug(slug) {
  if (!slug) return null;
  var all = getTagsIndex();
  for (var i = 0; i < all.length; i++) {
    if (all[i].slug === slug) return all[i];
  }
  return null;
}

/* ── State helpers ── */
function _tagsState() {
  return {
    query:           (typeof window !== 'undefined' && window._tagsQuery)        || '',
    filter:          (typeof window !== 'undefined' && window._tagsFilter)       || 'all',
    selectedTagSlug: (typeof window !== 'undefined' && window._tagsSelectedSlug) || null
  };
}
function _tagsSetState(patch) {
  if (!patch) return;
  if (typeof patch.query  === 'string') window._tagsQuery    = patch.query;
  if (typeof patch.filter === 'string') window._tagsFilter   = patch.filter;
  if ('selectedTagSlug' in patch)       window._tagsSelectedSlug = patch.selectedTagSlug;
  try {
    if (typeof patch.query  === 'string') localStorage.setItem('ethos_tags_query',  patch.query);
    if (typeof patch.filter === 'string') localStorage.setItem('ethos_tags_filter', patch.filter);
    if ('selectedTagSlug' in patch) {
      if (patch.selectedTagSlug) localStorage.setItem('ethos_tags_selected', String(patch.selectedTagSlug));
      else                       localStorage.removeItem('ethos_tags_selected');
    }
  } catch (e) {}
}
function _tagsRestoreState() {
  try {
    var q = localStorage.getItem('ethos_tags_query')    || '';
    var f = localStorage.getItem('ethos_tags_filter')   || 'all';
    var s = localStorage.getItem('ethos_tags_selected') || null;
    if (!window._tagsQuery)        window._tagsQuery        = q;
    if (!window._tagsFilter)       window._tagsFilter       = f;
    if (!window._tagsSelectedSlug) window._tagsSelectedSlug = s;
  } catch (e) {}
}

function _tagsMatchSearch(tag, q) {
  if (!q) return true;
  var lc = q.toLowerCase();
  if (tag.label.toLowerCase().indexOf(lc) >= 0) return true;
  if (tag.slug.toLowerCase().indexOf(lc) >= 0)  return true;
  if (Array.isArray(tag.categories)) {
    for (var i = 0; i < tag.categories.length; i++) {
      if ((tag.categories[i] || '').toLowerCase().indexOf(lc) >= 0) return true;
    }
  }
  /* Match source item titles */
  function arrHas(arr) {
    for (var j = 0; j < arr.length; j++) if ((arr[j].title || '').toLowerCase().indexOf(lc) >= 0) return true;
    return false;
  }
  if (arrHas(tag.sources.packs))     return true;
  if (arrHas(tag.sources.templates)) return true;
  if (arrHas(tag.sources.notes))     return true;
  if (arrHas(tag.sources.packNotes)) return true;
  return false;
}
function _tagsMatchFilter(tag, filter) {
  if (filter === 'all')        return true;
  if (filter === 'packs')      return tag.counts.packs > 0;
  if (filter === 'templates')  return tag.counts.templates > 0;
  if (filter === 'notes')      return tag.counts.notes > 0;
  if (filter === 'pack-notes') return tag.counts.packNotes > 0;
  if (filter === 'recent') {
    var cutoff = Date.now() - 7 * 86400000;
    /* Check sources for any recent updatedAt */
    function scan(arr) {
      for (var i = 0; i < arr.length; i++) if ((arr[i].updatedAt || 0) >= cutoff) return true;
      return false;
    }
    if (scan(tag.sources.templates)) return true;
    if (scan(tag.sources.notes))     return true;
    if (scan(tag.sources.packNotes)) return true;
    /* Active pack boost: if a tag is on the active pack, treat it as recent */
    if (typeof getActivePackId === 'function') {
      var aid = getActivePackId();
      if (aid && typeof PACK_META !== 'undefined' && PACK_META[aid] && PACK_META[aid].tags) {
        for (var k = 0; k < PACK_META[aid].tags.length; k++) {
          if (_tagSlug(PACK_META[aid].tags[k]) === tag.slug) return true;
        }
      }
    }
    return false;
  }
  return true;
}
function getFilteredTags(query, filter) {
  return getTagsIndex().filter(function (t) {
    return _tagsMatchFilter(t, filter || 'all') && _tagsMatchSearch(t, query || '');
  });
}

/* ── Navigation actions ── */
function openTagDetail(tagSlug) {
  _tagsSetState({ selectedTagSlug: tagSlug || null });
  if (window.showWorkspaceView) window.showWorkspaceView('tags');
}
function openNotesForTag(tagSlug) {
  var tag = getTagBySlug(tagSlug);
  if (!tag) return;
  try { localStorage.setItem('ethos_notes_query',  tag.label); } catch (e) {}
  try { localStorage.setItem('ethos_notes_filter', 'all'); } catch (e) {}
  window._notesHubQuery  = tag.label;
  window._notesHubFilter = 'all';
  window._notesHubSelectedId = null;
  if (window.switchDashboardView) window.switchDashboardView('notes');
}
function openTemplatesForTag(tagSlug) {
  var tag = getTagBySlug(tagSlug);
  if (!tag) return;
  try { localStorage.setItem('ethos_templates_query',  tag.label); } catch (e) {}
  try { localStorage.setItem('ethos_templates_filter', 'all'); } catch (e) {}
  window._templatesQuery  = tag.label;
  window._templatesFilter = 'all';
  window._templatesSelectedId = null;
  if (window.switchDashboardView) window.switchDashboardView('templates');
}
function openPlanPacksForTag(tagSlug) {
  var tag = getTagBySlug(tagSlug);
  if (!tag) return;
  window._ppMarketSearch = tag.label;
  window._ppMarketFilter = 'All';
  if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  if (window.showToast) window.showToast('Searching Plan Packs for: ' + tag.label, 'info', 2200);
}

/* ── Renderer helpers ── */
function _tagFormatRel(ts) {
  if (!ts) return '';
  var diff = Date.now() - ts;
  if (diff < 60 * 1000) return 'Just now';
  if (diff < 60 * 60 * 1000) return Math.floor(diff / 60000) + 'm ago';
  if (diff < 24 * 60 * 60 * 1000) return Math.floor(diff / 3600000) + 'h ago';
  var d = new Date(ts);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
function _tagIntensityLevel(total) {
  if (total <= 0) return 0;
  if (total <= 2) return 1;
  if (total <= 5) return 2;
  if (total <= 9) return 3;
  return 4;
}

function _tagCard(tag, isSelected) {
  var lvl = _tagIntensityLevel(tag.total);
  return '<button class="tag-card tag-intensity-' + lvl + (isSelected ? ' active' : '') + '" data-tag-slug="' + _apDpEsc(tag.slug) + '">'
    + '<div class="tag-card-row">'
    +   '<span class="tag-label">#' + _apDpEsc(tag.label) + '</span>'
    +   '<span class="tag-count">' + tag.total + '</span>'
    + '</div>'
    + '<div class="tag-breakdown">'
    +   '<span class="tag-bk tag-bk-packs">Packs ' + tag.counts.packs + '</span>'
    +   '<span class="tag-bk tag-bk-templates">Templates ' + tag.counts.templates + '</span>'
    +   '<span class="tag-bk tag-bk-notes">Notes ' + tag.counts.notes + '</span>'
    +   (tag.counts.packNotes ? '<span class="tag-bk tag-bk-packnotes">Pack Notes ' + tag.counts.packNotes + '</span>' : '')
    + '</div>'
    + '</button>';
}

function _tagDetailPanel(tag) {
  if (!tag) {
    return '<div class="tag-detail-empty">'
      + '<div class="tag-detail-empty-icon">#</div>'
      + '<div class="tag-detail-empty-title">Pick a tag</div>'
      + '<div class="tag-detail-empty-sub">Click any tag to see the packs, templates, and notes it connects.</div>'
      + '</div>';
  }

  var packsHtml = tag.sources.packs.map(function (p) {
    var meta  = _apMetaFor(p.id);
    var theme = _apThemeFor(meta);
    var style = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';
    var status = (p.status === 'active') ? '<span class="tag-status tag-status-active">ACTIVE</span>'
               : (p.status === 'coming-soon' ? '<span class="tag-status tag-status-soon">Locked</span>' : '');
    return '<div class="tag-source-item" style="' + style + '">'
      + '<div class="tag-source-icon">' + (p.icon || '◈') + '</div>'
      + '<div class="tag-source-info">'
      +   '<div class="tag-source-title">' + _apDpEsc(p.title) + status + '</div>'
      +   '<div class="tag-source-meta">' + _apDpEsc(p.category || '') + '</div>'
      + '</div>'
      + '<button class="tag-source-btn" data-tag-act="open-pack" data-tag-pack="' + _apDpEsc(p.id) + '">Open Pack</button>'
      + '</div>';
  }).join('');

  var templatesHtml = tag.sources.templates.map(function (t) {
    return '<div class="tag-source-item">'
      + '<div class="tag-source-icon">' + (t.icon || '◈') + '</div>'
      + '<div class="tag-source-info">'
      +   '<div class="tag-source-title">' + _apDpEsc(t.title) + '</div>'
      +   '<div class="tag-source-meta">' + _apDpEsc(t.category || '') + '</div>'
      + '</div>'
      + '<div class="tag-source-btns">'
      +   '<button class="tag-source-btn" data-tag-act="open-template" data-tag-tpl="' + _apDpEsc(t.id) + '">Open</button>'
      +   '<button class="tag-source-btn tag-source-btn-primary" data-tag-act="use-template" data-tag-tpl="' + _apDpEsc(t.id) + '">Use</button>'
      + '</div>'
      + '</div>';
  }).join('');

  var notesHtml = tag.sources.notes.map(function (n) {
    return '<div class="tag-source-item">'
      + '<div class="tag-source-icon">✎</div>'
      + '<div class="tag-source-info">'
      +   '<div class="tag-source-title">' + _apDpEsc(n.title) + ' <span class="tag-source-pill tag-source-pill-general">General</span></div>'
      +   '<div class="tag-source-meta">' + _apDpEsc(_tagFormatRel(n.updatedAt)) + '</div>'
      + '</div>'
      + '<button class="tag-source-btn" data-tag-act="open-note" data-tag-note="' + _apDpEsc(n.id) + '">Open Note</button>'
      + '</div>';
  }).join('');

  var packNotesHtml = tag.sources.packNotes.map(function (pn) {
    return '<div class="tag-source-item">'
      + '<div class="tag-source-icon">' + (pn.icon || '◈') + '</div>'
      + '<div class="tag-source-info">'
      +   '<div class="tag-source-title">' + _apDpEsc(pn.title) + ' <span class="tag-source-pill tag-source-pill-pack">Pack</span></div>'
      +   '<div class="tag-source-meta">' + _apDpEsc(pn.packTitle || '') + ' &middot; ' + _apDpEsc(_tagFormatRel(pn.updatedAt)) + '</div>'
      + '</div>'
      + '<button class="tag-source-btn" data-tag-act="open-pack-notes" data-tag-pack="' + _apDpEsc(pn.packId) + '">Open Pack Notes</button>'
      + '</div>';
  }).join('');

  function section(title, html) {
    if (!html) return '';
    return '<div class="tag-detail-section">'
      + '<div class="tag-detail-h">' + title + '</div>'
      + '<div class="tag-detail-list">' + html + '</div>'
      + '</div>';
  }

  return '<div class="tag-detail">'
    + '<div class="tag-detail-head">'
    +   '<div class="tag-detail-title">#' + _apDpEsc(tag.label) + '</div>'
    +   '<div class="tag-detail-meta">' + tag.total + ' connected item' + (tag.total === 1 ? '' : 's') + ' across packs, templates, and notes.</div>'
    + '</div>'
    + section('RELATED PACKS',     packsHtml)
    + section('RELATED TEMPLATES', templatesHtml)
    + section('RELATED NOTES',     notesHtml)
    + section('RELATED PACK NOTES', packNotesHtml)
    + '<div class="tag-action-row">'
    +   '<button class="tag-action" data-tag-act="filter-notes"     data-tag-slug="' + _apDpEsc(tag.slug) + '">Filter Notes</button>'
    +   '<button class="tag-action" data-tag-act="filter-templates" data-tag-slug="' + _apDpEsc(tag.slug) + '">Filter Templates</button>'
    +   '<button class="tag-action" data-tag-act="search-packs"     data-tag-slug="' + _apDpEsc(tag.slug) + '">Search Plan Packs</button>'
    +   '<button class="tag-action tag-action-ghost" data-tag-act="copy-tag" data-tag-slug="' + _apDpEsc(tag.slug) + '">Copy Tag Name</button>'
    + '</div>'
    + '</div>';
}

function _tagsEmptyHub() {
  return '<div class="tags-hub">'
    + '<div class="tags-head">'
    +   '<h1 class="tags-title">Tags</h1>'
    +   '<p class="tags-sub">Explore the topics connecting your notes, templates, packs, and worlds.</p>'
    + '</div>'
    + '<div class="ws-empty">'
    +   '<div class="ws-empty-icon">#</div>'
    +   '<div class="ws-empty-title">No Tags Yet</div>'
    +   '<div class="ws-empty-sub">Tags from notes, templates, and packs will appear here as your system grows.</div>'
    +   '<div class="ws-empty-actions">'
    +     '<button class="ws-empty-cta ws-empty-cta-primary" data-tag-act="open-notes-ws">Open Notes</button>'
    +     '<button class="ws-empty-cta" data-tag-act="open-templates-ws">Open Templates</button>'
    +     '<button class="ws-empty-cta" data-tag-act="open-packs-ws">Browse Plan Packs</button>'
    +   '</div>'
    + '</div>'
    + '</div>';
}

function renderTagsWorkspace() {
  _tagsRestoreState();
  var state = _tagsState();
  var all   = getTagsIndex();
  if (!all.length) return _tagsEmptyHub();

  /* Stats */
  var totalTags     = all.length;
  var packTagCount  = all.filter(function (t) { return t.counts.packs > 0; }).length;
  var noteTagCount  = all.filter(function (t) { return t.counts.notes > 0; }).length;
  var tplTagCount   = all.filter(function (t) { return t.counts.templates > 0; }).length;
  var mostUsed      = all[0] ? all[0].label : '-';

  /* Filtered list */
  var filtered = all.filter(function (t) {
    return _tagsMatchFilter(t, state.filter) && _tagsMatchSearch(t, state.query);
  });

  /* Default selection */
  var selectedSlug = state.selectedTagSlug;
  var selected     = selectedSlug ? all.filter(function (t) { return t.slug === selectedSlug; })[0] : null;
  if (!selected && filtered.length) selected = filtered[0];

  var chips = [
    ['all',        'All'],
    ['packs',      'Packs'],
    ['notes',      'Notes'],
    ['templates',  'Templates'],
    ['pack-notes', 'Pack Notes'],
    ['recent',     'Recently Used']
  ];
  var chipsHtml = chips.map(function (c) {
    return '<button class="tags-chip' + (state.filter === c[0] ? ' tags-chip-on' : '') + '" data-tag-filter="' + c[0] + '">' + c[1] + '</button>';
  }).join('');

  var gridHtml = filtered.length
    ? filtered.map(function (t) { return _tagCard(t, selected && t.slug === selected.slug); }).join('')
    : '<div class="tags-empty-result">No tags match your search.</div>';

  return '<div class="tags-hub">'
    + '<div class="tags-head">'
    +   '<h1 class="tags-title">Tags</h1>'
    +   '<p class="tags-sub">Explore the topics connecting your notes, templates, packs, and worlds.</p>'
    + '</div>'
    + '<div class="tags-stats">'
    +   '<div class="tags-stat"><div class="tags-stat-num">' + totalTags + '</div><div class="tags-stat-lbl">Total Tags</div></div>'
    +   '<div class="tags-stat"><div class="tags-stat-num">' + packTagCount + '</div><div class="tags-stat-lbl">Pack Tags</div></div>'
    +   '<div class="tags-stat"><div class="tags-stat-num">' + noteTagCount + '</div><div class="tags-stat-lbl">Note Tags</div></div>'
    +   '<div class="tags-stat"><div class="tags-stat-num">' + tplTagCount  + '</div><div class="tags-stat-lbl">Template Tags</div></div>'
    +   '<div class="tags-stat"><div class="tags-stat-num">' + _apDpEsc(mostUsed) + '</div><div class="tags-stat-lbl">Most Used</div></div>'
    + '</div>'
    + '<div class="tags-toolbar">'
    +   '<div class="tags-search-wrap">'
    +     '<span class="tags-search-icon">⌕</span>'
    +     '<input class="tags-search" id="tagSearchInput" type="text" placeholder="Search tags..." value="' + _apDpEsc(state.query) + '" autocomplete="off" spellcheck="false">'
    +   '</div>'
    + '</div>'
    + '<div class="tags-filter-chips">' + chipsHtml + '</div>'
    + '<div class="tags-layout">'
    +   '<div class="tags-grid">' + gridHtml + '</div>'
    +   '<div class="tags-pane">' + _tagDetailPanel(selected) + '</div>'
    + '</div>'
    + '</div>';
}

function attachTagsEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Search (debounced) */
  var search = root.querySelector('#tagSearchInput');
  if (search) {
    var st = null;
    search.addEventListener('input', function () {
      clearTimeout(st);
      var v = search.value;
      st = setTimeout(function () {
        _tagsSetState({ query: v });
        if (window.showWorkspaceView) window.showWorkspaceView('tags');
        var again = document.getElementById('tagSearchInput');
        if (again) { again.focus(); try { again.setSelectionRange(again.value.length, again.value.length); } catch (e) {} }
      }, 200);
    });
  }

  /* Filter chips */
  Array.prototype.forEach.call(root.querySelectorAll('[data-tag-filter]'), function (chip) {
    chip.addEventListener('click', function () {
      _tagsSetState({ filter: chip.getAttribute('data-tag-filter') || 'all', selectedTagSlug: null });
      if (window.showWorkspaceView) window.showWorkspaceView('tags');
    });
  });

  /* Tag card click (selects) - but skip if click was on an inner button */
  Array.prototype.forEach.call(root.querySelectorAll('.tag-card'), function (card) {
    card.addEventListener('click', function (ev) {
      var btn = ev.target.closest ? ev.target.closest('[data-tag-act]') : null;
      if (btn && btn !== card) return; /* let action handler take it */
      var slug = card.getAttribute('data-tag-slug');
      _tagsSetState({ selectedTagSlug: slug });
      if (window.showWorkspaceView) window.showWorkspaceView('tags');
    });
  });

  /* Detail-panel action buttons */
  Array.prototype.forEach.call(root.querySelectorAll('[data-tag-act]'), function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.stopPropagation();
      var act = btn.getAttribute('data-tag-act');
      if (act === 'open-pack') {
        var pid = btn.getAttribute('data-tag-pack');
        if (pid && window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pid, null);
        window._ppDetailTab = 'overview';
        if (window.switchDashboardView) window.switchDashboardView('plan-packs');
      } else if (act === 'open-pack-notes') {
        var pidn = btn.getAttribute('data-tag-pack');
        if (pidn && window.openPackNotesTab) window.openPackNotesTab(pidn);
      } else if (act === 'open-template') {
        var tid = btn.getAttribute('data-tag-tpl');
        window._templatesSelectedId = tid;
        if (window.switchDashboardView) window.switchDashboardView('templates');
      } else if (act === 'use-template') {
        var tid2 = btn.getAttribute('data-tag-tpl');
        if (tid2 && typeof _tplUseTemplate === 'function') _tplUseTemplate(tid2);
      } else if (act === 'open-note') {
        var nid = btn.getAttribute('data-tag-note');
        window._notesHubSelectedId = nid;
        window._notesHubFilter = 'all';
        if (window.switchDashboardView) window.switchDashboardView('notes');
      } else if (act === 'filter-notes')     { openNotesForTag(btn.getAttribute('data-tag-slug')); }
      else   if (act === 'filter-templates') { openTemplatesForTag(btn.getAttribute('data-tag-slug')); }
      else   if (act === 'search-packs')     { openPlanPacksForTag(btn.getAttribute('data-tag-slug')); }
      else   if (act === 'copy-tag') {
        var slug = btn.getAttribute('data-tag-slug');
        var t    = getTagBySlug(slug);
        var txt  = t ? t.label : (slug || '');
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt).then(function () {
            if (window.showToast) window.showToast('Tag copied: ' + txt, 'success', 1500);
          }, function () {
            if (window.showToast) window.showToast('Could not copy tag.', 'error', 1500);
          });
        }
      }
      else if (act === 'open-notes-ws')     { if (window.switchDashboardView) window.switchDashboardView('notes'); }
      else if (act === 'open-templates-ws') { if (window.switchDashboardView) window.switchDashboardView('templates'); }
      else if (act === 'open-packs-ws')     { if (window.switchDashboardView) window.switchDashboardView('plan-packs'); }
    });
  });
}

function installStage18TagsHub() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  window.EE_WORKSPACE_RENDER['tags'] = renderTagsWorkspace;
  window.EE_WORKSPACE_EVENTS['tags'] = attachTagsEvents;
}

if (typeof window !== 'undefined') {
  window.getTagsIndex            = getTagsIndex;
  window.getTagBySlug            = getTagBySlug;
  window.getFilteredTags         = getFilteredTags;
  window.renderTagsWorkspace     = renderTagsWorkspace;
  window.attachTagsEvents        = attachTagsEvents;
  window.openTagDetail           = openTagDetail;
  window.openNotesForTag         = openNotesForTag;
  window.openTemplatesForTag     = openTemplatesForTag;
  window.openPlanPacksForTag     = openPlanPacksForTag;
  window.installStage18TagsHub   = installStage18TagsHub;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 19 - Global Cmd-K Search Palette
   ════════════════════════════════════════════════════════════════ */

var GS_GROUP_ORDER = [
  ['workspace',     'Workspaces'],
  ['command',       'Commands'],
  ['task',          'Tasks'],
  ['pack',          'Plan Packs'],
  ['pack-day',      'Days'],
  ['note',          'Notes'],
  ['pack-note',     'Pack Notes'],
  ['template',      'Templates'],
  ['tag',           'Tags'],
  ['daily-log',     'Daily Logs'],
  ['calendar-date', 'Calendar']
];

var GS_TYPE_LABEL = {
  workspace:       'WORKSPACE',
  command:         'COMMAND',
  task:            'TASK',
  pack:            'PACK',
  'pack-day':      'DAY',
  note:            'NOTE',
  'pack-note':     'PACK NOTE',
  template:        'TEMPLATE',
  tag:             'TAG',
  'daily-log':     'DAILY LOG',
  'calendar-date': 'CALENDAR'
};

function _gsEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function _gsSnippet(s, max) {
  s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  max = max || 110;
  return s.length > max ? s.slice(0, max) + '...' : s;
}

/* ── Index sources ── */
function buildGlobalSearchIndex() {
  var out = [];

  /* A. Workspaces */
  [
    ['graph',       'Graph View',     '◈', 'Knowledge map'],
    ['plan-packs',  'Plan Packs',     '⚡', 'Browse the marketplace'],
    ['active-plan', 'My Active Plan', '★', 'Today and active pack'],
    ['notes',       'Notes Hub',      '✎', 'All pack + general notes'],
    ['daily',       'Daily Log',      '📅', 'Today\'s reflection'],
    ['tasks',       'Tasks',          '✓', 'Daily execution'],
    ['templates',   'Templates',      '⊞', 'Proven note structures'],
    ['dataview',    'Dataview',       '⋮⋮','Cross-system stats'],
    ['calendar',    'Calendar',       '◻', 'Monthly activity'],
    ['tags',        'Tags',           '#', 'Cross-system tag hub'],
    ['settings',    'Settings',       '⚙', 'Account, billing, controls']
  ].forEach(function (w) {
    var viewId = w[0];
    out.push({
      id:        'workspace:' + viewId,
      type:      'workspace',
      title:     w[1],
      subtitle:  w[3],
      body:      '',
      icon:      w[2],
      keywords:  [w[1], w[3], viewId],
      action:    (function (vid) { return function () { if (window.switchDashboardView) window.switchDashboardView(vid); }; })(viewId)
    });
  });

  /* B. Plan Packs */
  if (typeof buildMarketplaceEntries === 'function') {
    buildMarketplaceEntries().forEach(function (e) {
      var statusLabel = (e.status === 'active') ? 'Active' : (e.status === 'coming-soon' ? 'Included in Pro' : (e.status || ''));
      var subtitle = (e.category || '') + ' - ' + (e.totalDays || '?') + ' days - ' + statusLabel;
      var keywords = [e.title, e.category, statusLabel].concat(e.tags || []);
      var openable = (e.status === 'active');
      out.push({
        id:        'pack:' + e.id,
        type:      'pack',
        title:     e.title,
        subtitle:  subtitle,
        body:      e.promise || e.desc || '',
        icon:      e.icon || '⚡',
        keywords:  keywords,
        action:    (function (pid, isOpenable) {
          return function () {
            if (isOpenable) {
              if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pid, null);
              window._ppDetailTab = 'overview';
              if (window.switchDashboardView) window.switchDashboardView('plan-packs');
            } else {
              /* Coming soon: search the marketplace for that pack title */
              window._ppMarketSearch = e.title;
              window._ppMarketFilter = 'All';
              if (window.switchDashboardView) window.switchDashboardView('plan-packs');
              if (window.showToast) window.showToast('That pack is in development.', 'info', 2200);
            }
          };
        })(e.id, openable)
      });
    });
  }

  /* C. Pack Days (only for active packs that have content) */
  if (typeof PLAN_PACKS_DATA !== 'undefined') {
    PLAN_PACKS_DATA.forEach(function (pack) {
      var meta = (typeof PACK_META !== 'undefined') ? PACK_META[pack.id] : null;
      var isActive = meta && meta.status === 'active';
      if (!isActive) return;
      if (!pack.days || !pack.days.length) return;
      pack.days.forEach(function (day) {
        var keywords = [pack.title, day.title, 'day ' + day.day]
          .concat((day.checklist || []).slice(0, 6));
        out.push({
          id:        'pack-day:' + pack.id + ':' + day.day,
          type:      'pack-day',
          title:     'Day ' + day.day + ' - ' + day.title,
          subtitle:  pack.title,
          body:      day.task || day.action || '',
          icon:      pack.icon || '◈',
          keywords:  keywords,
          action:    (function (pid, dn) {
            return function () { if (window.openPackDay) window.openPackDay(pid, dn); };
          })(pack.id, day.day)
        });
      });
    });
  }

  /* D. General notes */
  if (typeof getGeneralNotes === 'function') {
    getGeneralNotes().forEach(function (n) {
      out.push({
        id:        'note:' + n.id,
        type:      'note',
        title:     n.title || 'Untitled Note',
        subtitle:  'General Note',
        body:      n.body || '',
        icon:      '✎',
        keywords:  [n.title || '', n.body || ''].concat(n.tags || []),
        action:    (function (nid) {
          return function () {
            window._notesHubSelectedId = nid;
            window._notesHubFilter = 'all';
            if (window.switchDashboardView) window.switchDashboardView('notes');
          };
        })(n.id)
      });
    });
  }

  /* E. Pack notes */
  if (typeof getPackNotesIndex === 'function') {
    getPackNotesIndex().forEach(function (pn) {
      out.push({
        id:        'pack-note:' + pn.packId,
        type:      'pack-note',
        title:     pn.title,
        subtitle:  pn.packTitle + ' - Pack Note',
        body:      pn.body || '',
        icon:      pn.packIcon || '◈',
        keywords:  [pn.title, pn.packTitle, pn.category || ''],
        action:    (function (pid) {
          return function () { if (window.openPackNotesTab) window.openPackNotesTab(pid); };
        })(pn.packId)
      });
    });
  }

  /* F. Templates */
  if (typeof DASHBOARD_TEMPLATES !== 'undefined') {
    DASHBOARD_TEMPLATES.forEach(function (tpl) {
      out.push({
        id:        'template:' + tpl.id,
        type:      'template',
        title:     tpl.title,
        subtitle:  tpl.category + ' Template',
        body:      tpl.description || '',
        icon:      tpl.icon || '⊞',
        keywords:  [tpl.title, tpl.category].concat(tpl.tags || []),
        action:    (function (tid) {
          return function () {
            window._templatesSelectedId = tid;
            if (window.switchDashboardView) window.switchDashboardView('templates');
          };
        })(tpl.id)
      });
    });
  }

  /* G. Tags */
  if (typeof getTagsIndex === 'function') {
    getTagsIndex().forEach(function (t) {
      var labels = []
        .concat(t.sources.packs.map(function (s) { return s.title; }))
        .concat(t.sources.templates.map(function (s) { return s.title; }))
        .concat(t.sources.notes.map(function (s) { return s.title; }))
        .concat(t.sources.packNotes.map(function (s) { return s.title; }));
      out.push({
        id:        'tag:' + t.slug,
        type:      'tag',
        title:     '#' + t.label,
        subtitle:  t.total + ' connected item' + (t.total === 1 ? '' : 's'),
        body:      labels.join(', '),
        icon:      '#',
        keywords:  [t.label, t.slug].concat(t.categories || []),
        action:    (function (slug) {
          return function () {
            window._tagsSelectedSlug = slug;
            if (window.switchDashboardView) window.switchDashboardView('tags');
          };
        })(t.slug)
      });
    });
  }

  /* H. Calendar dates - last 30 days with activity */
  if (typeof getCompletionHistory === 'function') {
    var hist = getCompletionHistory(30);
    var log  = (typeof getDailyCompletionLog === 'function') ? getDailyCompletionLog() : {};
    hist.forEach(function (h) {
      if ((h.completedDays || 0) === 0 && (h.checklistItems || 0) === 0) return;
      var bucket = log[h.date] || {};
      var packs  = ((bucket.completedDays || []).map(function (d) { return d.packTitle || d.packId; })).filter(Boolean);
      var d = new Date(h.date);
      var pretty = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
      out.push({
        id:        'calendar-date:' + h.date,
        type:      'calendar-date',
        title:     pretty,
        subtitle:  h.completedDays + ' day' + (h.completedDays === 1 ? '' : 's') + ' completed - ' + h.checklistItems + ' items',
        body:      packs.join(', '),
        icon:      '◻',
        keywords:  [h.date, pretty].concat(packs),
        action:    (function (dk) {
          return function () {
            window._calSelectedDate = dk;
            var dt = new Date(dk);
            if (typeof setCalendarMonth === 'function') setCalendarMonth(dt.getFullYear(), dt.getMonth());
            if (window.switchDashboardView) window.switchDashboardView('calendar');
          };
        })(h.date)
      });
    });
  }

  /* H2. Daily Logs (Stage 24) */
  if (typeof getDailyLogs === 'function') {
    var logsIndex = getDailyLogs();
    Object.keys(logsIndex).forEach(function (dk) {
      var l = logsIndex[dk];
      var d = new Date(dk);
      var pretty = isNaN(d.getTime()) ? dk : d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
      var bodyParts = [l.focus, l.wins, l.lesson, l.nextStep].filter(Boolean);
      out.push({
        id:        'daily-log:' + dk,
        type:      'daily-log',
        title:     pretty + ' Daily Log',
        subtitle:  (l.focus || l.wins || l.lesson || '(empty)').slice(0, 80),
        body:      bodyParts.join(' - '),
        icon:      '📔',
        keywords:  [dk, l.focus || '', l.wins || '', l.lesson || '', l.nextStep || '', l.mood || ''],
        action:    (function (k) {
          return function () { if (window.openDailyLogDate) window.openDailyLogDate(k); };
        })(dk)
      });
    });
  }

  /* I. Tasks (Stage 21) - skip completed to keep palette focused */
  if (typeof getTasks === 'function') {
    getTasks().forEach(function (tk) {
      if (tk.status === 'done') return;
      var packTitle = (tk.linkedPackId && typeof PLAN_PACKS_DATA !== 'undefined')
        ? (function () {
            for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
              if (PLAN_PACKS_DATA[i].id === tk.linkedPackId) return PLAN_PACKS_DATA[i].title;
            }
            return '';
          })()
        : '';
      var subParts = [];
      subParts.push(tk.priority.toUpperCase());
      if (tk.dueDate) subParts.push('Due ' + tk.dueDate);
      if (packTitle) subParts.push(packTitle + (tk.linkedDayNumber != null ? ' - Day ' + tk.linkedDayNumber : ''));
      out.push({
        id:        'task:' + tk.id,
        type:      'task',
        title:     tk.title,
        subtitle:  subParts.join(' - '),
        body:      tk.notes || '',
        icon:      '✓',
        keywords:  [tk.title, tk.notes || '', packTitle].concat(tk.tags || []),
        action:    (function (tid) {
          return function () {
            if (window.openTaskInWorkspace) window.openTaskInWorkspace(tid);
          };
        })(tk.id)
      });
    });
  }

  /* J. Commands */
  var commands = [
    { id:'cmd:open-billing',  title:'Open Billing',          subtitle:'Settings - Billing tab',         icon:'$',  keywords:['billing','plan','subscription'],
      run: function () {
        if (window.switchDashboardView) window.switchDashboardView('settings');
        window._eeSettingsTab = 'billing';
        if (window.refreshCurrentView) window.refreshCurrentView();
      }},
    { id:'cmd:compare-plans', title:'Compare Plans',         subtitle:'Plan comparison modal',          icon:'⇄',  keywords:['compare','plans','upgrade','pro','core'],
      run: function () { if (window.showPlanComparisonModal) window.showPlanComparisonModal(); }},
    { id:'cmd:manage-billing',title:'Manage Billing',        subtitle:'Open Stripe portal if configured', icon:'⊞', keywords:['stripe','portal','billing','manage'],
      run: function () { if (window.openBillingPortal) window.openBillingPortal(); }},
    { id:'cmd:toggle-sidebar',title:'Toggle Sidebar',        subtitle:'Collapse or expand the sidebar', icon:'≡',  keywords:['sidebar','collapse','expand'],
      run: function () { if (window.toggleSidebarCollapsed) window.toggleSidebarCollapsed(); }},
    { id:'cmd:reset-view',    title:'Reset Graph View',      subtitle:'Recenter the planet map',        icon:'⊙',  keywords:['reset','center','zoom','graph'],
      run: function () {
        if (window.switchDashboardView) window.switchDashboardView('graph');
        if (window.EE_GRAPH_API && window.EE_GRAPH_API.resetView) window.EE_GRAPH_API.resetView();
      }},
    { id:'cmd:shortcuts',     title:'Keyboard Shortcuts',    subtitle:'Show all keyboard shortcuts',    icon:'⌘',  keywords:['shortcuts','help','keyboard','cmd','ctrl'],
      run: function () { if (window.eeShowShortcutHelp) window.eeShowShortcutHelp(); }},
    { id:'cmd:continue-plan', title:'Continue Active Plan',  subtitle:'Jump into today\'s next day',    icon:'▶',  keywords:['continue','today','active','day'],
      run: function () { if (window.continueActivePlan) window.continueActivePlan(); }}
  ];
  commands.forEach(function (c) {
    out.push({
      id:       c.id,
      type:     'command',
      title:    c.title,
      subtitle: c.subtitle,
      body:     '',
      icon:     c.icon,
      keywords: c.keywords,
      action:   c.run
    });
  });

  return out;
}

/* ── Ranking ── */
function _gsScore(item, q) {
  if (!q) return 0;
  var lc = q.toLowerCase();
  var t  = String(item.title || '').toLowerCase();
  if (t === lc)                    return 100;
  if (t.indexOf(lc) === 0)         return 80;
  if (t.indexOf(lc) >= 0)          return 60;
  var s = String(item.subtitle || '').toLowerCase();
  if (s.indexOf(lc) >= 0)          return 40;
  if (item.keywords) {
    for (var i = 0; i < item.keywords.length; i++) {
      if (String(item.keywords[i] || '').toLowerCase().indexOf(lc) >= 0) return 30;
    }
  }
  var b = String(item.body || '').toLowerCase();
  if (b.indexOf(lc) >= 0)          return 20;
  return 0;
}

function searchGlobalIndex(query) {
  var index = window._globalSearchIndex || [];
  if (!query) return [];
  var q = String(query).trim();
  if (!q) return [];
  var scored = [];
  for (var i = 0; i < index.length; i++) {
    var s = _gsScore(index[i], q);
    if (s > 0) scored.push({ score: s, item: index[i] });
  }
  scored.sort(function (a, b) {
    if (b.score !== a.score) return b.score - a.score;
    return (a.item.title || '').localeCompare(b.item.title || '');
  });
  return scored.slice(0, 12).map(function (x) { return x.item; });
}

/* ── Recent opens ── */
function _gsGetRecent() {
  try {
    var raw = localStorage.getItem('ethos_global_search_recent');
    if (!raw) return [];
    var p = JSON.parse(raw);
    return Array.isArray(p) ? p : [];
  } catch (e) { return []; }
}
function _gsPushRecent(item) {
  if (!item) return;
  try {
    var recent = _gsGetRecent().filter(function (r) { return r.id !== item.id; });
    recent.unshift({ id: item.id, title: item.title, type: item.type, openedAt: Date.now() });
    if (recent.length > 20) recent = recent.slice(0, 20);
    localStorage.setItem('ethos_global_search_recent', JSON.stringify(recent));
  } catch (e) {}
}

/* ── Quick actions ── */
function getQuickActions() {
  var acts = [];
  var ap = (typeof getActivePack === 'function') ? getActivePack() : null;
  if (ap) {
    acts.push({
      id: 'qa:continue-active-plan',
      type: 'command',
      title: 'Continue Today',
      subtitle: ap.title,
      icon: '▶',
      action: function () { if (window.continueActivePlan) window.continueActivePlan(); }
    });
  }
  acts.push({ id:'qa:plan-packs', type:'workspace', title:'Open Plan Packs', subtitle:'Marketplace', icon:'⚡',
    action: function () { if (window.switchDashboardView) window.switchDashboardView('plan-packs'); } });
  acts.push({ id:'qa:notes', type:'workspace', title:'Open Notes', subtitle:'Notes Hub', icon:'✎',
    action: function () { if (window.switchDashboardView) window.switchDashboardView('notes'); } });
  acts.push({ id:'qa:calendar', type:'workspace', title:'Open Calendar', subtitle:'Monthly activity', icon:'◻',
    action: function () { if (window.switchDashboardView) window.switchDashboardView('calendar'); } });
  acts.push({ id:'qa:templates', type:'workspace', title:'Open Templates', subtitle:'Note structures', icon:'⊞',
    action: function () { if (window.switchDashboardView) window.switchDashboardView('templates'); } });
  acts.push({ id:'qa:tags', type:'workspace', title:'Open Tags', subtitle:'Cross-system tag hub', icon:'#',
    action: function () { if (window.switchDashboardView) window.switchDashboardView('tags'); } });
  acts.push({ id:'qa:billing', type:'command', title:'Open Billing', subtitle:'Settings - Billing tab', icon:'$',
    action: function () {
      if (window.switchDashboardView) window.switchDashboardView('settings');
      window._eeSettingsTab = 'billing';
      if (window.refreshCurrentView) window.refreshCurrentView();
    }});
  acts.push({ id:'qa:shortcuts', type:'command', title:'Keyboard Shortcuts', subtitle:'Show all shortcuts', icon:'⌘',
    action: function () { if (window.eeShowShortcutHelp) window.eeShowShortcutHelp(); }});
  return acts;
}

/* ── DOM + lifecycle ── */
function _ensureGlobalSearchPalette() {
  var modal = document.getElementById('eeGlobalSearchModal');
  if (modal) return modal;
  modal = document.createElement('div');
  modal.id = 'eeGlobalSearchModal';
  modal.className = 'global-search-modal';
  modal.setAttribute('aria-hidden', 'true');
  modal.innerHTML = ''
    + '<div class="global-search-backdrop" data-gsclose="1"></div>'
    + '<div class="global-search-panel" role="dialog" aria-modal="true" aria-label="Global search">'
    +   '<div class="global-search-input-wrap">'
    +     '<span class="global-search-icon" aria-hidden="true">⌕</span>'
    +     '<input class="global-search-input" id="globalSearchInput" type="text" placeholder="Search packs, days, notes, templates, tags, calendar..." autocomplete="off" spellcheck="false" aria-label="Search dashboard" aria-controls="globalSearchResults" aria-autocomplete="list" role="combobox" aria-expanded="true">'
    +     '<button class="global-search-close" id="globalSearchClose" aria-label="Close search">&times;</button>'
    +   '</div>'
    +   '<div class="global-search-results" id="globalSearchResults" role="listbox" aria-label="Search results"></div>'
    +   '<div class="global-search-footer">'
    +     '<span><kbd>&uarr;</kbd><kbd>&darr;</kbd> Navigate</span>'
    +     '<span><kbd>Enter</kbd> Open</span>'
    +     '<span><kbd>Esc</kbd> Close</span>'
    +   '</div>'
    + '</div>';
  document.body.appendChild(modal);
  return modal;
}

function _gsResultsHtml(items, query, selectedIdx) {
  if (!items.length) {
    return '<div class="global-search-empty">No matches for "' + _gsEsc(query) + '".</div>';
  }
  /* Group by type, render in declared order */
  var groups = {};
  items.forEach(function (it, i) {
    if (!groups[it.type]) groups[it.type] = [];
    groups[it.type].push({ item: it, originalIndex: i });
  });
  var html = '';
  GS_GROUP_ORDER.forEach(function (g) {
    var key = g[0], label = g[1];
    if (!groups[key]) return;
    html += '<div class="global-search-group"><div class="global-search-group-label">' + label + '</div>';
    groups[key].forEach(function (entry) {
      var it       = entry.item;
      var isActive = (entry.originalIndex === selectedIdx);
      var typeLbl  = GS_TYPE_LABEL[it.type] || (it.type || '').toUpperCase();
      html += '<div class="global-search-result' + (isActive ? ' active' : '') + '" role="option" aria-selected="' + (isActive ? 'true' : 'false') + '" data-gs-result-idx="' + entry.originalIndex + '" data-gs-result-id="' + _gsEsc(it.id) + '">'
        + '<div class="global-search-result-icon">' + _gsEsc(it.icon || '◈') + '</div>'
        + '<div class="global-search-result-main">'
        +   '<div class="global-search-result-title">' + _gsEsc(it.title) + '</div>'
        +   (it.subtitle ? '<div class="global-search-result-sub">' + _gsEsc(it.subtitle) + '</div>' : '')
        +   (it.body ? '<div class="global-search-result-body">' + _gsEsc(_gsSnippet(it.body, 90)) + '</div>' : '')
        + '</div>'
        + '<div class="global-search-result-type">' + typeLbl + '</div>'
        + '</div>';
    });
    html += '</div>';
  });
  return html;
}

function _gsEmptyStateHtml() {
  /* Quick actions + recent opens */
  var quick = getQuickActions();
  var recentIds = _gsGetRecent();
  var index = window._globalSearchIndex || [];
  var recent = [];
  recentIds.forEach(function (r) {
    for (var i = 0; i < index.length; i++) {
      if (index[i].id === r.id) { recent.push(index[i]); break; }
    }
  });
  recent = recent.slice(0, 6);

  var quickHtml = quick.map(function (qa, i) {
    return '<div class="global-search-result' + (i === 0 ? ' active' : '') + '" role="option" aria-selected="' + (i === 0 ? 'true' : 'false') + '" data-gs-quick-id="' + _gsEsc(qa.id) + '">'
      + '<div class="global-search-result-icon">' + _gsEsc(qa.icon || '◈') + '</div>'
      + '<div class="global-search-result-main">'
      +   '<div class="global-search-result-title">' + _gsEsc(qa.title) + '</div>'
      +   '<div class="global-search-result-sub">' + _gsEsc(qa.subtitle || '') + '</div>'
      + '</div>'
      + '<div class="global-search-result-type">' + _gsEsc(GS_TYPE_LABEL[qa.type] || 'ACTION') + '</div>'
      + '</div>';
  }).join('');

  var recentHtml = recent.length
    ? '<div class="global-search-group"><div class="global-search-group-label">Recent</div>'
      + recent.map(function (r) {
          return '<div class="global-search-result" role="option" aria-selected="false" data-gs-result-id="' + _gsEsc(r.id) + '">'
            + '<div class="global-search-result-icon">' + _gsEsc(r.icon || '◈') + '</div>'
            + '<div class="global-search-result-main">'
            +   '<div class="global-search-result-title">' + _gsEsc(r.title) + '</div>'
            +   (r.subtitle ? '<div class="global-search-result-sub">' + _gsEsc(r.subtitle) + '</div>' : '')
            + '</div>'
            + '<div class="global-search-result-type">' + _gsEsc(GS_TYPE_LABEL[r.type] || (r.type || '').toUpperCase()) + '</div>'
            + '</div>';
        }).join('')
      + '</div>'
    : '';

  return '<div class="global-search-group"><div class="global-search-group-label">Quick Actions</div>'
    + quickHtml
    + '</div>'
    + recentHtml;
}

function renderGlobalSearchPalette(query) {
  query = String(query == null ? '' : query);
  var resultsHost = document.getElementById('globalSearchResults');
  if (!resultsHost) return;
  if (!query.trim()) {
    window._gsCurrentResults = [];
    window._gsQuickActions   = getQuickActions();
    window._gsSelectedIndex  = 0;
    resultsHost.innerHTML = _gsEmptyStateHtml();
    return;
  }
  var items = searchGlobalIndex(query);
  window._gsCurrentResults = items;
  window._gsSelectedIndex  = items.length ? 0 : -1;
  resultsHost.innerHTML = _gsResultsHtml(items, query, window._gsSelectedIndex);
}

function setGlobalSearchQuery(query) {
  var inp = document.getElementById('globalSearchInput');
  if (inp) {
    inp.value = String(query == null ? '' : query);
    renderGlobalSearchPalette(inp.value);
  }
}

function openGlobalSearchPalette(initialQuery) {
  var modal = _ensureGlobalSearchPalette();
  /* Build fresh index each open */
  window._globalSearchIndex = buildGlobalSearchIndex();
  var inp = document.getElementById('globalSearchInput');
  if (inp) {
    inp.value = String(initialQuery || '');
  }
  renderGlobalSearchPalette(initialQuery || '');
  /* Stage 28: remember the element that opened the palette so we can return
     focus there on close (a11y - keyboard users shouldn't lose their place). */
  try {
    var opener = document.activeElement;
    /* If the palette itself or any of its children is somehow already focused,
       don't store that as the opener. Same for body/html (no real focus). */
    if (opener && opener !== document.body && opener !== document.documentElement
        && !modal.contains(opener)) {
      window._gsOpener = opener;
    }
  } catch (e) {}
  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  document.body.classList.add('global-search-open');
  /* Focus AFTER the open transition starts so iOS doesn't lose focus */
  setTimeout(function () {
    var i2 = document.getElementById('globalSearchInput');
    if (i2) { i2.focus(); try { i2.setSelectionRange(i2.value.length, i2.value.length); } catch (e) {} }
  }, 30);
  /* Make sure the top-bar input doesn't steal focus back */
  var tbInp = document.getElementById('tbSrchInput');
  if (tbInp) tbInp.blur();
}

function closeGlobalSearchPalette() {
  var modal = document.getElementById('eeGlobalSearchModal');
  if (!modal) return;
  modal.classList.remove('is-open');
  modal.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('global-search-open');
  var tbInp = document.getElementById('tbSrchInput');
  if (tbInp) tbInp.blur();
  /* Guard so a stray refocus on the top-bar input does not re-open instantly */
  window._gsJustClosed = Date.now();
  /* Stage 28: return focus to the element that opened the palette, if it's
     still in the DOM and focusable. Skip the readonly top-bar input because
     re-focusing it would just open the palette again. */
  try {
    var opener = window._gsOpener;
    window._gsOpener = null;
    if (opener && document.body.contains(opener) && typeof opener.focus === 'function'
        && opener.id !== 'tbSrchInput') {
      opener.focus();
    }
  } catch (e) {}
}

function openGlobalSearchResult(resultId) {
  if (!resultId) return;
  /* First check quick actions for matching id */
  var qa = (window._gsQuickActions || []);
  for (var i = 0; i < qa.length; i++) {
    if (qa[i].id === resultId && typeof qa[i].action === 'function') {
      _gsPushRecent({ id: qa[i].id, title: qa[i].title, type: qa[i].type, icon: qa[i].icon, subtitle: qa[i].subtitle });
      closeGlobalSearchPalette();
      qa[i].action();
      return;
    }
  }
  /* Then search current results */
  var items = window._gsCurrentResults || [];
  for (var j = 0; j < items.length; j++) {
    if (items[j].id === resultId && typeof items[j].action === 'function') {
      _gsPushRecent({ id: items[j].id, title: items[j].title, type: items[j].type, icon: items[j].icon, subtitle: items[j].subtitle });
      closeGlobalSearchPalette();
      items[j].action();
      return;
    }
  }
  /* Fallback: search whole index */
  var idx = window._globalSearchIndex || [];
  for (var k = 0; k < idx.length; k++) {
    if (idx[k].id === resultId && typeof idx[k].action === 'function') {
      _gsPushRecent({ id: idx[k].id, title: idx[k].title, type: idx[k].type, icon: idx[k].icon, subtitle: idx[k].subtitle });
      closeGlobalSearchPalette();
      idx[k].action();
      return;
    }
  }
}

function _gsOpenAtSelectedIndex() {
  var idx = (typeof window._gsSelectedIndex === 'number') ? window._gsSelectedIndex : -1;
  if (idx < 0) {
    /* If empty-state quick actions, pick first quick action */
    var qa = window._gsQuickActions || [];
    if (qa.length) openGlobalSearchResult(qa[0].id);
    return;
  }
  var items = window._gsCurrentResults || [];
  if (idx < items.length) openGlobalSearchResult(items[idx].id);
}

function _gsMoveSelection(delta) {
  var resultsHost = document.getElementById('globalSearchResults');
  if (!resultsHost) return;
  var items = window._gsCurrentResults || [];
  if (!items.length) {
    /* Move within quick actions */
    var qa = window._gsQuickActions || [];
    if (!qa.length) return;
    var idxQ = (typeof window._gsSelectedIndex === 'number') ? window._gsSelectedIndex : 0;
    idxQ = (idxQ + delta + qa.length) % qa.length;
    window._gsSelectedIndex = idxQ;
    var rows = resultsHost.querySelectorAll('[data-gs-quick-id]');
    Array.prototype.forEach.call(rows, function (r, i) {
      var on = (i === idxQ);
      r.classList.toggle('active', on);
      r.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    var sel = rows[idxQ];
    if (sel && sel.scrollIntoView) sel.scrollIntoView({ block: 'nearest' });
    return;
  }
  var idx = (typeof window._gsSelectedIndex === 'number') ? window._gsSelectedIndex : 0;
  idx = (idx + delta + items.length) % items.length;
  window._gsSelectedIndex = idx;
  /* Stage 20: toggle .active on existing rows instead of full re-render
     (faster + avoids the brief flicker we'd see on every arrow press). */
  var rows = resultsHost.querySelectorAll('[data-gs-result-idx]');
  Array.prototype.forEach.call(rows, function (r) {
    var ri = parseInt(r.getAttribute('data-gs-result-idx'), 10);
    var on = (ri === idx);
    r.classList.toggle('active', on);
    r.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  var act = resultsHost.querySelector('.global-search-result.active');
  if (act && act.scrollIntoView) act.scrollIntoView({ block: 'nearest' });
}

function attachGlobalSearchEvents() {
  var modal = _ensureGlobalSearchPalette();

  /* Backdrop + X close */
  modal.addEventListener('click', function (e) {
    if (e.target && e.target.getAttribute && e.target.getAttribute('data-gsclose') === '1') {
      closeGlobalSearchPalette();
    }
  });
  var x = modal.querySelector('#globalSearchClose');
  if (x) x.addEventListener('click', closeGlobalSearchPalette);

  /* Input - search */
  var inp = modal.querySelector('#globalSearchInput');
  if (inp) {
    var st = null;
    inp.addEventListener('input', function () {
      clearTimeout(st);
      var v = inp.value;
      st = setTimeout(function () { renderGlobalSearchPalette(v); }, 80);
    });
    /* Keyboard navigation inside the input */
    inp.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { e.preventDefault(); closeGlobalSearchPalette(); return; }
      if (e.key === 'ArrowDown') { e.preventDefault(); _gsMoveSelection(1); return; }
      if (e.key === 'ArrowUp')   { e.preventDefault(); _gsMoveSelection(-1); return; }
      if (e.key === 'Enter')     { e.preventDefault(); _gsOpenAtSelectedIndex(); return; }
      /* Stage 28: focus trap. Tab moves to the Close button; Shift+Tab from
         the input goes to Close (cycle backward). The palette only has two
         tab stops in practice (input + close button), so this is enough. */
      if (e.key === 'Tab') {
        var closeBtn = document.getElementById('globalSearchClose');
        if (closeBtn) { e.preventDefault(); closeBtn.focus(); }
      }
    });
  }
  /* Stage 28: complete the focus trap on the close button side. */
  var closeBtnTrap = modal.querySelector('#globalSearchClose');
  if (closeBtnTrap) {
    closeBtnTrap.addEventListener('keydown', function (e) {
      if (e.key === 'Tab') {
        var inp2 = document.getElementById('globalSearchInput');
        if (inp2) { e.preventDefault(); inp2.focus(); }
      }
    });
  }

  /* Result clicks (delegated) */
  var resultsHost = modal.querySelector('#globalSearchResults');
  if (resultsHost) {
    resultsHost.addEventListener('click', function (e) {
      var row = e.target.closest ? e.target.closest('[data-gs-result-id], [data-gs-quick-id]') : null;
      if (!row) return;
      var rid = row.getAttribute('data-gs-result-id') || row.getAttribute('data-gs-quick-id');
      if (rid) openGlobalSearchResult(rid);
    });
    resultsHost.addEventListener('mouseover', function (e) {
      var row = e.target.closest ? e.target.closest('[data-gs-result-idx], [data-gs-quick-id]') : null;
      if (!row) return;
      var idxAttr = row.getAttribute('data-gs-result-idx');
      if (idxAttr != null) {
        var i = parseInt(idxAttr, 10);
        if (!isNaN(i)) {
          window._gsSelectedIndex = i;
          /* update visuals */
          var rows = resultsHost.querySelectorAll('.global-search-result');
          Array.prototype.forEach.call(rows, function (r) {
            var on = (r === row);
            r.classList.toggle('active', on);
            r.setAttribute('aria-selected', on ? 'true' : 'false');
          });
        }
      } else if (row.hasAttribute('data-gs-quick-id')) {
        var qrows = resultsHost.querySelectorAll('[data-gs-quick-id]');
        Array.prototype.forEach.call(qrows, function (r, idx) {
          var match = (r === row);
          r.classList.toggle('active', match);
          r.setAttribute('aria-selected', match ? 'true' : 'false');
          if (match) window._gsSelectedIndex = idx;
        });
      }
    });
  }
}

function installStage19GlobalSearch() {
  /* Stage 20: focus/mousedown/keydown listeners would stack on every call.
     Guard so installation is one-and-done. */
  if (window.__eeStage19SearchInstalled) return;
  window.__eeStage19SearchInstalled = true;
  /* Build palette + wire its events */
  _ensureGlobalSearchPalette();
  attachGlobalSearchEvents();

  /* Top-bar input integration: focusing or clicking opens palette */
  var tbInp = document.getElementById('tbSrchInput');
  if (tbInp) {
    tbInp.addEventListener('focus', function () {
      /* Ignore if palette already open, or if a refocus is firing right after close */
      if (document.body.classList.contains('global-search-open')) return;
      if (window._gsJustClosed && (Date.now() - window._gsJustClosed) < 250) return;
      openGlobalSearchPalette('');
    });
    tbInp.addEventListener('mousedown', function (e) {
      /* Avoid the brief focus blink before palette opens */
      e.preventDefault();
      openGlobalSearchPalette('');
    });
    /* Make it visually feel like a button */
    tbInp.setAttribute('readonly', 'readonly');
    tbInp.setAttribute('aria-label', 'Open global search');
  }

  /* Global keydown for Cmd/Ctrl+K - opens palette directly even if Stage 6
     already focuses the top-bar input. We use capture so we run first. */
  document.addEventListener('keydown', function (e) {
    if ((e.metaKey || e.ctrlKey) && (e.key === 'k' || e.key === 'K')) {
      e.preventDefault();
      /* Stage 27: stopImmediatePropagation so the Stage 6 bubble-phase Cmd-K
         listener on document cannot also fire (which used to trigger the old
         srch dropdown's focus path). Stage 19 owns Cmd-K. */
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      /* Stage 20: if palette is already open, just refocus the input -
         don't wipe whatever the user has already typed. */
      if (document.body.classList.contains('global-search-open')) {
        var inp = document.getElementById('globalSearchInput');
        if (inp) { inp.focus(); try { inp.setSelectionRange(0, inp.value.length); } catch (err) {} }
        return;
      }
      openGlobalSearchPalette('');
    }
  }, true);
}

if (typeof window !== 'undefined') {
  window.openGlobalSearchPalette   = openGlobalSearchPalette;
  window.closeGlobalSearchPalette  = closeGlobalSearchPalette;
  window.renderGlobalSearchPalette = renderGlobalSearchPalette;
  window.attachGlobalSearchEvents  = attachGlobalSearchEvents;
  window.buildGlobalSearchIndex    = buildGlobalSearchIndex;
  window.searchGlobalIndex         = searchGlobalIndex;
  window.openGlobalSearchResult    = openGlobalSearchResult;
  window.getQuickActions           = getQuickActions;
  window.setGlobalSearchQuery      = setGlobalSearchQuery;
  window.installStage19GlobalSearch = installStage19GlobalSearch;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 21 - Tasks workspace
   ════════════════════════════════════════════════════════════════ */

/* Storage shape: see spec. Legacy ee_tasks was [{text, done}] - we
   migrate at read time without rewriting until the user takes action. */
function _taskMigrateLegacy(raw) {
  if (!raw || typeof raw !== 'object') return null;
  if (typeof raw.id === 'string') return raw; /* already new shape */
  if (typeof raw.text !== 'string') return null;
  var now = Date.now();
  return {
    id:             'task_legacy_' + now + '_' + Math.floor(Math.random() * 100000),
    title:          raw.text,
    notes:          '',
    status:         raw.done ? 'done' : 'open',
    priority:       'medium',
    dueDate:        null,
    linkedPackId:   null,
    linkedDayNumber:null,
    linkedWorldId:  null,
    tags:           [],
    createdAt:      now,
    updatedAt:      now,
    completedAt:    raw.done ? now : null
  };
}

function getTasks() {
  var raw = (typeof safeJsonParse === 'function')
    ? safeJsonParse(localStorage.getItem('ee_tasks'), [])
    : (function () { try { return JSON.parse(localStorage.getItem('ee_tasks') || '[]'); } catch (e) { return []; } })();
  if (!Array.isArray(raw)) return [];
  var out = [];
  for (var i = 0; i < raw.length; i++) {
    var migrated = _taskMigrateLegacy(raw[i]);
    if (migrated) out.push(migrated);
  }
  return out;
}
function saveTasks(tasks) {
  try { localStorage.setItem('ee_tasks', JSON.stringify(tasks || [])); } catch (e) {}
}

function _taskTodayKey() {
  return (typeof todayKey === 'function') ? todayKey() : new Date().toISOString().slice(0, 10);
}

function createTask(initial) {
  initial = initial || {};
  var now = Date.now();
  var id  = 'task_' + now + '_' + Math.floor(Math.random() * 100000);
  var task = {
    id:              id,
    title:           initial.title || 'New task',
    notes:           initial.notes || '',
    status:          'open',
    priority:        (['low','medium','high'].indexOf(initial.priority) >= 0) ? initial.priority : 'medium',
    dueDate:         initial.dueDate || _taskTodayKey(),
    linkedPackId:    initial.linkedPackId    || null,
    linkedDayNumber: (typeof initial.linkedDayNumber === 'number') ? initial.linkedDayNumber : null,
    linkedWorldId:   initial.linkedWorldId   || null,
    tags:            Array.isArray(initial.tags) ? initial.tags : [],
    createdAt:       now,
    updatedAt:       now,
    completedAt:     null
  };
  var tasks = getTasks();
  tasks.unshift(task);
  saveTasks(tasks);
  return id;
}
function updateTask(taskId, patch) {
  if (!taskId || !patch || typeof patch !== 'object') return false;
  var tasks = getTasks();
  for (var i = 0; i < tasks.length; i++) {
    if (tasks[i].id === taskId) {
      if (typeof patch.title    === 'string') tasks[i].title    = patch.title;
      if (typeof patch.notes    === 'string') tasks[i].notes    = patch.notes;
      if (typeof patch.priority === 'string' && ['low','medium','high'].indexOf(patch.priority) >= 0) tasks[i].priority = patch.priority;
      if (typeof patch.dueDate  === 'string' || patch.dueDate === null) tasks[i].dueDate = patch.dueDate;
      if (typeof patch.status   === 'string' && ['open','done','archived'].indexOf(patch.status) >= 0) tasks[i].status = patch.status;
      if (Array.isArray(patch.tags))         tasks[i].tags = patch.tags;
      if (patch.linkedPackId !== undefined)  tasks[i].linkedPackId = patch.linkedPackId;
      if (patch.linkedDayNumber !== undefined) tasks[i].linkedDayNumber = patch.linkedDayNumber;
      if (patch.linkedWorldId !== undefined)   tasks[i].linkedWorldId = patch.linkedWorldId;
      tasks[i].updatedAt = Date.now();
      saveTasks(tasks);
      return true;
    }
  }
  return false;
}
function completeTask(taskId, options) {
  options = options || {};
  var tasks = getTasks();
  var done  = false;
  var task  = null;
  for (var i = 0; i < tasks.length; i++) {
    if (tasks[i].id === taskId) {
      tasks[i].status      = 'done';
      tasks[i].completedAt = Date.now();
      tasks[i].updatedAt   = Date.now();
      task = tasks[i];
      done = true;
      break;
    }
  }
  if (done) saveTasks(tasks);

  /* Stage 23: if the task is linked to a pack day that's not yet complete,
     offer to mark the day complete too. Skipped via silentLinkedPrompt so
     the pack -> task auto-sync path doesn't trigger a reverse prompt. */
  if (done && !options.silentLinkedPrompt
        && task && task.linkedPackId && task.linkedDayNumber != null
        && typeof isPackDayComplete === 'function'
        && !isPackDayComplete(task.linkedPackId, task.linkedDayNumber)
        && window.showToast) {
    var packTitle = (typeof _taskPackTitle === 'function') ? _taskPackTitle(task.linkedPackId) : task.linkedPackId;
    var msg = 'Task completed. Mark ' + packTitle + ' - Day ' + task.linkedDayNumber + ' complete too?';
    window.showToast(msg, 'success', {
      duration: 6000,
      actionLabel: 'Mark Day Complete',
      onAction: function () { completeLinkedPackDayFromTask(taskId); }
    });
  }
  return done;
}

/* Stage 23: alias that completes a task without offering the linked-day
   prompt. Used by the pack-day -> task auto-sync path to avoid loops. */
function completeTaskFromPackSync(taskId) {
  return completeTask(taskId, { silentLinkedPrompt: true });
}
function reopenTask(taskId) {
  var tasks = getTasks();
  for (var i = 0; i < tasks.length; i++) {
    if (tasks[i].id === taskId) {
      tasks[i].status      = 'open';
      tasks[i].completedAt = null;
      tasks[i].updatedAt   = Date.now();
      saveTasks(tasks);
      return true;
    }
  }
  return false;
}
function deleteTask(taskId) {
  var tasks = getTasks();
  var next  = tasks.filter(function (t) { return t.id !== taskId; });
  if (next.length === tasks.length) return false;
  saveTasks(next);
  return true;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 23 - Task <-> Pack Day auto-sync helpers
   ════════════════════════════════════════════════════════════════ */

/* Returns tasks linked to a specific pack day, optionally filtered by status. */
function getLinkedTasksForPackDay(packId, dayNumber, options) {
  if (!packId || dayNumber == null) return [];
  options = options || {};
  var wantStatus = options.status || 'open';
  return getTasks().filter(function (t) {
    if (t.linkedPackId !== packId) return false;
    if (Number(t.linkedDayNumber) !== Number(dayNumber)) return false;
    if (wantStatus === 'all') return true;
    return t.status === wantStatus;
  });
}

/* Safe pack-day completion check straight from localStorage. */
function isPackDayComplete(packId, dayNumber) {
  if (!packId || dayNumber == null) return false;
  try {
    var all = (typeof safeJsonParse === 'function')
      ? safeJsonParse(localStorage.getItem('ee_pack_progress'), {})
      : JSON.parse(localStorage.getItem('ee_pack_progress') || '{}');
    if (!all || typeof all !== 'object') return false;
    var pack = all[packId];
    if (!pack || typeof pack !== 'object') return false;
    return !!pack['day_' + dayNumber];
  } catch (e) { return false; }
}

/* Marks the linked pack day complete from a task callback. Routes through
   the closure helper which handles the side effects (progress save, daily
   log, ceremony, banner refresh) and skips re-firing the task auto-sync. */
function completeLinkedPackDayFromTask(taskId) {
  if (!taskId) return false;
  var task = null;
  var tasks = getTasks();
  for (var i = 0; i < tasks.length; i++) {
    if (tasks[i].id === taskId) { task = tasks[i]; break; }
  }
  if (!task) return false;
  if (!task.linkedPackId || task.linkedDayNumber == null) {
    if (window.showToast) window.showToast('This task is not linked to a pack day.', 'warning', 1800);
    return false;
  }
  if (isPackDayComplete(task.linkedPackId, task.linkedDayNumber)) {
    if (window.showToast) window.showToast('That day is already complete.', 'info', 1500);
    return false;
  }
  if (!window.EE_PACK_NAV || typeof window.EE_PACK_NAV.completePackDay !== 'function') {
    if (window.showToast) window.showToast('Pack progress is not ready yet.', 'warning', 1800);
    return false;
  }
  /* silentLinkedTaskSync prevents the closure path from re-completing the
     same task we just completed and re-toasting. */
  var res = window.EE_PACK_NAV.completePackDay(task.linkedPackId, task.linkedDayNumber, { silentLinkedTaskSync: true });
  if (res === 'completed') {
    if (window.showToast) window.showToast('Pack day marked complete.', 'success', 1500);
    /* Re-render the visible workspace so progress numbers update */
    if (window.dashboardState && window.showWorkspaceView) {
      window.showWorkspaceView(window.dashboardState.currentView);
    }
    return true;
  }
  return false;
}

function _taskMatchFilter(task, filter) {
  var today = _taskTodayKey();
  if (filter === 'completed') return task.status === 'done';
  if (task.status === 'done') return filter === 'completed' || filter === 'all';
  if (filter === 'all')      return true;
  if (filter === 'today')    return task.dueDate === today;
  if (filter === 'upcoming') return task.dueDate && task.dueDate > today;
  if (filter === 'overdue')  return task.dueDate && task.dueDate < today;
  if (filter === 'high')     return task.priority === 'high';
  if (filter === 'linked')   return !!task.linkedPackId;
  return true;
}
function _taskMatchSearch(task, q) {
  if (!q) return true;
  var lc = q.toLowerCase();
  function has(v) { return (v || '').toString().toLowerCase().indexOf(lc) >= 0; }
  if (has(task.title) || has(task.notes) || has(task.priority)) return true;
  if (Array.isArray(task.tags)) {
    for (var i = 0; i < task.tags.length; i++) if (has(task.tags[i])) return true;
  }
  if (task.linkedPackId && typeof PLAN_PACKS_DATA !== 'undefined') {
    for (var j = 0; j < PLAN_PACKS_DATA.length; j++) {
      if (PLAN_PACKS_DATA[j].id === task.linkedPackId && has(PLAN_PACKS_DATA[j].title)) return true;
    }
  }
  return false;
}
function getFilteredTasks(query, filter) {
  return getTasks().filter(function (t) {
    return _taskMatchFilter(t, filter || 'today') && _taskMatchSearch(t, query || '');
  });
}

/* ── UI state ── */
function _tasksState() {
  return {
    query:          (typeof window !== 'undefined' && window._tasksQuery)      || '',
    filter:         (typeof window !== 'undefined' && window._tasksFilter)     || 'today',
    selectedTaskId: (typeof window !== 'undefined' && window._tasksSelectedId) || null
  };
}
function _tasksSetState(patch) {
  if (!patch) return;
  if (typeof patch.query  === 'string') window._tasksQuery    = patch.query;
  if (typeof patch.filter === 'string') window._tasksFilter   = patch.filter;
  if ('selectedTaskId' in patch)        window._tasksSelectedId = patch.selectedTaskId;
  try {
    if (typeof patch.query  === 'string') localStorage.setItem('ethos_tasks_query',  patch.query);
    if (typeof patch.filter === 'string') localStorage.setItem('ethos_tasks_filter', patch.filter);
    if ('selectedTaskId' in patch) {
      if (patch.selectedTaskId) localStorage.setItem('ethos_tasks_selected', String(patch.selectedTaskId));
      else                      localStorage.removeItem('ethos_tasks_selected');
    }
  } catch (e) {}
}
function _tasksRestoreState() {
  try {
    var q = localStorage.getItem('ethos_tasks_query')    || '';
    var f = localStorage.getItem('ethos_tasks_filter')   || 'today';
    var s = localStorage.getItem('ethos_tasks_selected') || null;
    if (!window._tasksQuery)      window._tasksQuery      = q;
    if (!window._tasksFilter)     window._tasksFilter     = f;
    if (!window._tasksSelectedId) window._tasksSelectedId = s;
  } catch (e) {}
}

function openTaskInWorkspace(taskId) {
  _tasksSetState({ selectedTaskId: taskId || null });
  if (window.switchDashboardView) window.switchDashboardView('tasks');
}

/* ── Helpers ── */
function _taskPackTitle(packId) {
  if (!packId || typeof PLAN_PACKS_DATA === 'undefined') return '';
  for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
    if (PLAN_PACKS_DATA[i].id === packId) return PLAN_PACKS_DATA[i].title;
  }
  return packId;
}
function _taskFormatDue(dateKey) {
  if (!dateKey) return '';
  var today = _taskTodayKey();
  if (dateKey === today) return 'Today';
  var t = new Date();
  var tomorrowKey = todayKey(new Date(t.getFullYear(), t.getMonth(), t.getDate() + 1));
  if (dateKey === tomorrowKey) return 'Tomorrow';
  var d = new Date(dateKey);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
function _taskSuggestedFromActivePlan() {
  if (typeof getActivePack !== 'function') return null;
  var pack = getActivePack();
  if (!pack || !pack.days || !pack.days.length) return null;
  var nextDay = (typeof _apNextIncompleteDay === 'function') ? _apNextIncompleteDay(pack) : null;
  if (!nextDay) return null;
  /* Skip if a task already exists for this pack-day */
  var tasks = getTasks();
  for (var i = 0; i < tasks.length; i++) {
    if (tasks[i].linkedPackId === pack.id && tasks[i].linkedDayNumber === nextDay.day && tasks[i].status !== 'done') {
      return null;
    }
  }
  var meta = (typeof PACK_META !== 'undefined') ? (PACK_META[pack.id] || {}) : {};
  return {
    title: 'Complete ' + pack.title + ' - Day ' + nextDay.day + ': ' + nextDay.title,
    linkedPackId:    pack.id,
    linkedDayNumber: nextDay.day,
    icon:            pack.icon,
    packTitle:       pack.title,
    dayNumber:       nextDay.day,
    dayTitle:        nextDay.title,
    tags:            (meta.tags || []).slice()
  };
}

/* ── Renderer ── */
function _taskEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function _taskListItem(task, isSelected) {
  var isDone = task.status === 'done';
  var prioClass = 'task-priority-' + task.priority;
  var linkedHtml = '';
  var syncBadge = '';
  if (task.linkedPackId) {
    var packTitle = _taskPackTitle(task.linkedPackId);
    linkedHtml = '<span class="task-linked-badge">' + _taskEsc(packTitle)
      + (task.linkedDayNumber != null ? ' &middot; Day ' + task.linkedDayNumber : '') + '</span>';
    /* Stage 23: linked pack-day completion state */
    if (task.linkedDayNumber != null && typeof isPackDayComplete === 'function') {
      var dayDone = isPackDayComplete(task.linkedPackId, task.linkedDayNumber);
      syncBadge = '<span class="task-sync-badge ' + (dayDone ? 'task-sync-complete' : 'task-sync-open') + '">'
        + (dayDone ? 'DAY COMPLETE' : 'DAY OPEN') + '</span>';
    }
  }
  var tagsHtml = (task.tags || []).slice(0, 3).map(function (t) {
    return '<span class="task-tag">' + _taskEsc(t) + '</span>';
  }).join('');
  var dueHtml = task.dueDate
    ? '<span class="task-due">' + _taskEsc(_taskFormatDue(task.dueDate)) + '</span>'
    : '';
  return '<div class="task-card ' + prioClass + (isDone ? ' done' : '') + (isSelected ? ' active' : '') + '" data-task-id="' + _taskEsc(task.id) + '">'
    + '<button class="task-check" data-task-act="' + (isDone ? 'reopen' : 'complete') + '" data-task-id="' + _taskEsc(task.id) + '" aria-pressed="' + (isDone ? 'true' : 'false') + '">'
    +   (isDone ? '&#10003;' : '')
    + '</button>'
    + '<div class="task-card-main">'
    +   '<div class="task-card-title">' + _taskEsc(task.title) + '</div>'
    +   '<div class="task-card-meta">'
    +     '<span class="task-priority ' + prioClass + '">' + task.priority.toUpperCase() + '</span>'
    +     dueHtml
    +     linkedHtml
    +     syncBadge
    +     tagsHtml
    +   '</div>'
    + '</div>'
    + '<div class="task-card-actions">'
    +   '<button class="task-card-btn" data-task-act="open"   data-task-id="' + _taskEsc(task.id) + '">Open</button>'
    +   '<button class="task-card-btn" data-task-act="delete" data-task-id="' + _taskEsc(task.id) + '">Delete</button>'
    + '</div>'
    + '</div>';
}

function _taskDetailEmpty() {
  return '<div class="task-detail-empty">'
    + '<div class="task-detail-empty-icon">✓</div>'
    + '<div class="task-detail-empty-title">Pick a task</div>'
    + '<div class="task-detail-empty-sub">Select a task to edit details, link a pack day, or change priority.</div>'
    + '</div>';
}

function _taskDetailPanel(task) {
  if (!task) return _taskDetailEmpty();
  var tagsStr = (task.tags || []).join(', ');
  var linkedHtml = '';
  if (task.linkedPackId) {
    linkedHtml = '<div class="task-linked-row">'
      + '<div class="task-linked-info">'
      +   '<div class="task-linked-lbl">LINKED PACK</div>'
      +   '<div class="task-linked-val">' + _taskEsc(_taskPackTitle(task.linkedPackId))
      +     (task.linkedDayNumber != null ? ' &middot; Day ' + task.linkedDayNumber : '') + '</div>'
      + '</div>'
      + (task.linkedDayNumber != null
          ? '<button class="task-action" data-task-act="open-day" data-task-id="' + _taskEsc(task.id) + '">Open Day</button>'
          : '')
      + '</div>';
  }
  return '<div class="task-detail">'
    + '<input class="task-detail-title" id="taskDetailTitle" type="text" placeholder="Task title" value="' + _taskEsc(task.title) + '">'
    + '<textarea class="task-detail-notes" id="taskDetailNotes" placeholder="Notes (optional)">' + _taskEsc(task.notes || '') + '</textarea>'
    + '<div class="task-detail-row">'
    +   '<label class="task-detail-field"><span class="task-detail-lbl">Priority</span>'
    +     '<select class="task-detail-input" id="taskDetailPriority">'
    +       '<option value="low"' +    (task.priority === 'low'    ? ' selected' : '') + '>Low</option>'
    +       '<option value="medium"' + (task.priority === 'medium' ? ' selected' : '') + '>Medium</option>'
    +       '<option value="high"' +   (task.priority === 'high'   ? ' selected' : '') + '>High</option>'
    +     '</select>'
    +   '</label>'
    +   '<label class="task-detail-field"><span class="task-detail-lbl">Due Date</span>'
    +     '<input class="task-detail-input" id="taskDetailDue" type="date" value="' + _taskEsc(task.dueDate || '') + '">'
    +   '</label>'
    + '</div>'
    + '<label class="task-detail-field"><span class="task-detail-lbl">Tags (comma-separated)</span>'
    +   '<input class="task-detail-input" id="taskDetailTags" type="text" placeholder="focus, mindset" value="' + _taskEsc(tagsStr) + '">'
    + '</label>'
    + linkedHtml
    + '<div class="task-actions">'
    +   '<button class="task-action task-action-primary" data-task-act="save"   data-task-id="' + _taskEsc(task.id) + '">Save</button>'
    +   (task.status === 'done'
        ? '<button class="task-action" data-task-act="reopen"   data-task-id="' + _taskEsc(task.id) + '">Reopen</button>'
        : '<button class="task-action" data-task-act="complete" data-task-id="' + _taskEsc(task.id) + '">Complete</button>')
    +   '<button class="task-action task-action-danger" data-task-act="delete" data-task-id="' + _taskEsc(task.id) + '">Delete</button>'
    + '</div>'
    + '</div>';
}

function renderTasksWorkspace() {
  _tasksRestoreState();
  var state = _tasksState();
  var allTasks = getTasks();

  /* Stats */
  var openTasks   = allTasks.filter(function (t) { return t.status !== 'done'; });
  var today       = _taskTodayKey();
  var dueToday    = openTasks.filter(function (t) { return t.dueDate === today; }).length;
  var overdue     = openTasks.filter(function (t) { return t.dueDate && t.dueDate < today; }).length;
  var completed   = allTasks.filter(function (t) { return t.status === 'done'; }).length;

  /* Filtered list */
  var filtered = getFilteredTasks(state.query, state.filter);

  /* Default selection */
  var selectedId = state.selectedTaskId;
  var selected   = null;
  for (var i = 0; i < filtered.length; i++) {
    if (filtered[i].id === selectedId) { selected = filtered[i]; break; }
  }
  /* Allow selecting tasks from outside the current filter (e.g. just-completed) */
  if (!selected && selectedId) {
    for (var k = 0; k < allTasks.length; k++) {
      if (allTasks[k].id === selectedId) { selected = allTasks[k]; break; }
    }
  }

  var chips = [
    ['today',     'Today'],
    ['upcoming',  'Upcoming'],
    ['overdue',   'Overdue'],
    ['high',      'High Priority'],
    ['linked',    'Linked to Packs'],
    ['completed', 'Completed'],
    ['all',       'All']
  ];
  var chipsHtml = chips.map(function (c) {
    return '<button class="tasks-chip' + (state.filter === c[0] ? ' tasks-chip-on' : '') + '" data-task-filter="' + c[0] + '">' + c[1] + '</button>';
  }).join('');

  /* Suggested from active plan */
  var suggested = _taskSuggestedFromActivePlan();
  var suggestedHtml = '';
  if (suggested) {
    suggestedHtml = '<div class="task-suggested">'
      + '<div class="task-suggested-head">'
      +   '<div class="task-suggested-kicker">SUGGESTED FROM ACTIVE PLAN</div>'
      +   '<div class="task-suggested-title">' + _taskEsc(suggested.title) + '</div>'
      + '</div>'
      + '<button class="task-action task-action-primary" data-task-act="add-suggested">Add to Tasks</button>'
      + '</div>';
  }

  var listHtml = filtered.length
    ? filtered.map(function (t) { return _taskListItem(t, selected && t.id === selected.id); }).join('')
    : '<div class="task-empty">'
      + '<div class="task-empty-title">Nothing here yet</div>'
      + '<div class="task-empty-sub">Add a task above, change the filter, or accept the suggested task from your active plan.</div>'
      + '</div>';

  return '<div class="tasks-hub">'
    + '<div class="tasks-head">'
    +   '<h1 class="tasks-title">Tasks</h1>'
    +   '<p class="tasks-sub">Turn your plans into daily execution.</p>'
    + '</div>'
    + '<div class="tasks-stats">'
    +   '<div class="tasks-stat"><div class="tasks-stat-num">' + openTasks.length + '</div><div class="tasks-stat-lbl">Open Tasks</div></div>'
    +   '<div class="tasks-stat"><div class="tasks-stat-num">' + dueToday + '</div><div class="tasks-stat-lbl">Due Today</div></div>'
    +   '<div class="tasks-stat"><div class="tasks-stat-num">' + overdue + '</div><div class="tasks-stat-lbl">Overdue</div></div>'
    +   '<div class="tasks-stat"><div class="tasks-stat-num">' + completed + '</div><div class="tasks-stat-lbl">Completed</div></div>'
    + '</div>'
    + '<div class="tasks-quick-add">'
    +   '<input class="tasks-quick-input" id="tasksQuickInput" type="text" placeholder="Add a task..." autocomplete="off">'
    +   '<select class="tasks-quick-priority" id="tasksQuickPriority">'
    +     '<option value="low">Low</option>'
    +     '<option value="medium" selected>Medium</option>'
    +     '<option value="high">High</option>'
    +   '</select>'
    +   '<input class="tasks-quick-due" id="tasksQuickDue" type="date" value="' + today + '">'
    +   '<button class="tasks-quick-add-btn" id="tasksQuickAdd">Add</button>'
    + '</div>'
    + suggestedHtml
    + '<div class="tasks-toolbar">'
    +   '<div class="tasks-search-wrap">'
    +     '<span class="tasks-search-icon">⌕</span>'
    +     '<input class="tasks-search" id="tasksSearchInput" type="text" placeholder="Search tasks..." value="' + _taskEsc(state.query) + '" autocomplete="off" spellcheck="false">'
    +   '</div>'
    + '</div>'
    + '<div class="tasks-filter-chips">' + chipsHtml + '</div>'
    + '<div class="tasks-layout">'
    +   '<div class="tasks-list">' + listHtml + '</div>'
    +   '<div class="tasks-pane">' + _taskDetailPanel(selected) + '</div>'
    + '</div>'
    + '</div>';
}

function attachTasksEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Quick-add */
  var qInput = root.querySelector('#tasksQuickInput');
  var qPrio  = root.querySelector('#tasksQuickPriority');
  var qDue   = root.querySelector('#tasksQuickDue');
  var qBtn   = root.querySelector('#tasksQuickAdd');
  function quickAdd() {
    if (!qInput) return;
    var title = qInput.value.trim();
    if (!title) return;
    var newId = createTask({
      title: title,
      priority: qPrio ? qPrio.value : 'medium',
      dueDate:  qDue   ? qDue.value   : _taskTodayKey()
    });
    qInput.value = '';
    _tasksSetState({ selectedTaskId: newId });
    if (window.showToast) window.showToast('Task added.', 'success', 1500);
    if (window.showWorkspaceView) window.showWorkspaceView('tasks');
    if (typeof window.updateDailyReminderBanner === 'function') window.updateDailyReminderBanner();
  }
  if (qBtn)   qBtn.addEventListener('click', quickAdd);
  if (qInput) qInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') quickAdd(); });

  /* Search */
  var search = root.querySelector('#tasksSearchInput');
  if (search) {
    var st = null;
    search.addEventListener('input', function () {
      clearTimeout(st);
      var v = search.value;
      st = setTimeout(function () {
        _tasksSetState({ query: v });
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
        var again = document.getElementById('tasksSearchInput');
        if (again) { again.focus(); try { again.setSelectionRange(again.value.length, again.value.length); } catch (e) {} }
      }, 180);
    });
  }

  /* Filter chips */
  Array.prototype.forEach.call(root.querySelectorAll('[data-task-filter]'), function (chip) {
    chip.addEventListener('click', function () {
      _tasksSetState({ filter: chip.getAttribute('data-task-filter') || 'today', selectedTaskId: null });
      if (window.showWorkspaceView) window.showWorkspaceView('tasks');
    });
  });

  /* Card body click selects */
  Array.prototype.forEach.call(root.querySelectorAll('.task-card'), function (card) {
    card.addEventListener('click', function (ev) {
      var btn = ev.target.closest ? ev.target.closest('[data-task-act]') : null;
      if (btn) return;
      var tid = card.getAttribute('data-task-id');
      _tasksSetState({ selectedTaskId: tid });
      if (window.showWorkspaceView) window.showWorkspaceView('tasks');
    });
  });

  /* Action buttons (delegated) */
  Array.prototype.forEach.call(root.querySelectorAll('[data-task-act]'), function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.stopPropagation();
      var act = btn.getAttribute('data-task-act');
      var tid = btn.getAttribute('data-task-id');
      if (act === 'open') {
        _tasksSetState({ selectedTaskId: tid });
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      } else if (act === 'complete') {
        completeTask(tid);
        if (window.showToast) window.showToast('Task completed.', 'success', 1200);
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      } else if (act === 'reopen') {
        reopenTask(tid);
        if (window.showToast) window.showToast('Task reopened.', 'info', 1200);
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      } else if (act === 'delete') {
        if (!window.confirm('Delete this task? This cannot be undone.')) return;
        deleteTask(tid);
        _tasksSetState({ selectedTaskId: null });
        if (window.showToast) window.showToast('Task deleted.', 'success', 1200);
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      } else if (act === 'save') {
        var titleI = document.getElementById('taskDetailTitle');
        var notesI = document.getElementById('taskDetailNotes');
        var prioI  = document.getElementById('taskDetailPriority');
        var dueI   = document.getElementById('taskDetailDue');
        var tagsI  = document.getElementById('taskDetailTags');
        var tags   = tagsI ? tagsI.value.split(',').map(function (s) { return s.trim(); }).filter(Boolean) : [];
        updateTask(tid, {
          title:    titleI ? titleI.value : '',
          notes:    notesI ? notesI.value : '',
          priority: prioI  ? prioI.value  : 'medium',
          dueDate:  dueI   ? dueI.value   : null,
          tags:     tags
        });
        if (window.showToast) window.showToast('Task saved.', 'success', 1200);
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      } else if (act === 'open-day') {
        /* Find the task to extract pack + day */
        var tasks = getTasks();
        for (var i = 0; i < tasks.length; i++) {
          if (tasks[i].id === tid) {
            if (tasks[i].linkedPackId && tasks[i].linkedDayNumber != null && window.openPackDay) {
              window.openPackDay(tasks[i].linkedPackId, tasks[i].linkedDayNumber);
            }
            break;
          }
        }
      } else if (act === 'add-suggested') {
        var sug = _taskSuggestedFromActivePlan();
        if (!sug) return;
        var nid = createTask({
          title:           sug.title,
          priority:        'medium',
          dueDate:         _taskTodayKey(),
          linkedPackId:    sug.linkedPackId,
          linkedDayNumber: sug.linkedDayNumber,
          tags:            sug.tags
        });
        _tasksSetState({ selectedTaskId: nid });
        if (window.showToast) window.showToast('Task added from active plan.', 'success', 1500);
        if (window.showWorkspaceView) window.showWorkspaceView('tasks');
      }
    });
  });
}

function installStage21TasksHub() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  /* Replace Stage 6 wrapper + closure renderer entirely */
  window.EE_WORKSPACE_RENDER['tasks'] = renderTasksWorkspace;
  window.EE_WORKSPACE_EVENTS['tasks'] = attachTasksEvents;
}

if (typeof window !== 'undefined') {
  window.getTasks                  = getTasks;
  window.saveTasks                 = saveTasks;
  window.createTask                = createTask;
  window.updateTask                = updateTask;
  window.completeTask              = completeTask;
  window.reopenTask                = reopenTask;
  window.deleteTask                = deleteTask;
  window.getFilteredTasks          = getFilteredTasks;
  window.renderTasksWorkspace      = renderTasksWorkspace;
  window.attachTasksEvents         = attachTasksEvents;
  window.openTaskInWorkspace       = openTaskInWorkspace;
  window.installStage21TasksHub    = installStage21TasksHub;
  /* Stage 23 sync helpers */
  window.getLinkedTasksForPackDay  = getLinkedTasksForPackDay;
  window.isPackDayComplete         = isPackDayComplete;
  window.completeTaskFromPackSync  = completeTaskFromPackSync;
  window.completeLinkedPackDayFromTask = completeLinkedPackDayFromTask;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 24 - Daily Log workspace
   ════════════════════════════════════════════════════════════════ */

var DAILY_LOG_MOODS = ['focused','neutral','tired','strong','distracted'];

function getDailyLogs() {
  var raw = (typeof safeJsonParse === 'function')
    ? safeJsonParse(localStorage.getItem('ee_daily_logs'), {})
    : (function () { try { return JSON.parse(localStorage.getItem('ee_daily_logs') || '{}'); } catch (e) { return {}; } })();
  return (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {};
}
function saveDailyLogs(logs) {
  try { localStorage.setItem('ee_daily_logs', JSON.stringify(logs || {})); } catch (e) {}
}
function getDailyLog(dateKey) {
  if (!dateKey) return null;
  var logs = getDailyLogs();
  return logs[dateKey] || null;
}
function saveDailyLog(dateKey, patch) {
  if (!dateKey || !patch || typeof patch !== 'object') return false;
  var logs = getDailyLogs();
  var now  = Date.now();
  var existing = logs[dateKey];
  if (!existing) {
    existing = { date: dateKey, focus:'', wins:'', lesson:'', improvement:'', nextStep:'', mood:'neutral', createdAt: now, updatedAt: now };
  }
  if (typeof patch.focus       === 'string') existing.focus       = patch.focus;
  if (typeof patch.wins        === 'string') existing.wins        = patch.wins;
  if (typeof patch.lesson      === 'string') existing.lesson      = patch.lesson;
  if (typeof patch.improvement === 'string') existing.improvement = patch.improvement;
  if (typeof patch.nextStep    === 'string') existing.nextStep    = patch.nextStep;
  if (typeof patch.mood        === 'string' && DAILY_LOG_MOODS.indexOf(patch.mood) >= 0) existing.mood = patch.mood;
  existing.updatedAt = now;
  logs[dateKey] = existing;
  saveDailyLogs(logs);
  return true;
}

function _dlYMD(date) {
  date = date || new Date();
  return date.getFullYear()
    + '-' + String(date.getMonth() + 1).padStart(2, '0')
    + '-' + String(date.getDate()).padStart(2, '0');
}
function _dlTodayKey() {
  return (typeof todayKey === 'function') ? todayKey() : _dlYMD();
}

function getDailyActivitySummary(dateKey) {
  var completedDays = (typeof getCompletedDaysForDate === 'function') ? getCompletedDaysForDate(dateKey) : [];
  var checklistItems = (typeof getChecklistItemsCheckedForDate === 'function') ? getChecklistItemsCheckedForDate(dateKey) : 0;
  var packsTouched = {};
  completedDays.forEach(function (d) { if (d.packId) packsTouched[d.packId] = true; });
  /* Completed tasks: filter all tasks by completedAt date */
  var completedTasks = [];
  if (typeof getTasks === 'function') {
    getTasks().forEach(function (t) {
      if (t.status !== 'done' || !t.completedAt) return;
      var tk = todayKey(new Date(t.completedAt));
      if (tk === dateKey) completedTasks.push(t);
    });
  }
  /* Sort tasks by completion time descending */
  completedTasks.sort(function (a, b) { return (b.completedAt || 0) - (a.completedAt || 0); });
  return {
    dateKey:               dateKey,
    completedDays:         completedDays,
    completedTasks:        completedTasks,
    checklistItemsChecked: checklistItems,
    packsTouched:          Object.keys(packsTouched),
    totalActivityScore:    completedDays.length * 4 + completedTasks.length * 2 + Math.floor(checklistItems / 2)
  };
}

/* ── State ── */
function _dlState() {
  return {
    selectedDate: (typeof window !== 'undefined' && window._dailyLogSelectedDate) || _dlTodayKey()
  };
}
function _dlSetState(patch) {
  if (!patch) return;
  if (typeof patch.selectedDate === 'string') {
    window._dailyLogSelectedDate = patch.selectedDate;
    try { localStorage.setItem('ethos_daily_log_selected_date', patch.selectedDate); } catch (e) {}
  }
}
function _dlRestoreState() {
  try {
    var s = localStorage.getItem('ethos_daily_log_selected_date');
    if (s && !window._dailyLogSelectedDate) window._dailyLogSelectedDate = s;
  } catch (e) {}
}

function openDailyLogDate(dateKey) {
  if (!dateKey) return;
  /* Stage 27: if the Daily Log view is already open and the user has unsaved
     typing, flush it before we change the selected date. Otherwise the
     pending debounce gets cancelled by the re-mount and the typing is lost. */
  try {
    if (typeof _dailyLogDirty !== 'undefined' && _dailyLogDirty &&
        typeof autosaveDailyLogNow === 'function') {
      autosaveDailyLogNow();
    }
  } catch (e) {}
  _dlSetState({ selectedDate: dateKey });
  if (window.switchDashboardView) window.switchDashboardView('daily');
}

/* ── Format helpers ── */
function _dlPrettyDate(dateKey) {
  if (!dateKey) return '';
  var d = new Date(dateKey);
  if (isNaN(d.getTime())) return dateKey;
  return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
}
function _dlShortDate(dateKey) {
  if (!dateKey) return '';
  var d = new Date(dateKey);
  if (isNaN(d.getTime())) return dateKey;
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
function _dlTimeOf(ts) {
  if (!ts) return '';
  var d = new Date(ts);
  return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}
function _dlEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/* ── Renderer ── */
function renderDailyLogWorkspace() {
  _dlRestoreState();
  var state = _dlState();
  var date  = state.selectedDate;
  var log   = getDailyLog(date) || { focus:'', wins:'', lesson:'', improvement:'', nextStep:'', mood:'neutral', updatedAt:0 };
  var act   = getDailyActivitySummary(date);

  /* Date prev/next */
  var d = new Date(date);
  var prev = todayKey(new Date(d.getFullYear(), d.getMonth(), d.getDate() - 1));
  var next = todayKey(new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1));
  var today = _dlTodayKey();
  var isToday = (date === today);

  /* Completed pack days section */
  var completedDaysHtml = '';
  if (act.completedDays.length) {
    completedDaysHtml = act.completedDays.map(function (entry) {
      var meta  = _apMetaFor(entry.packId);
      var theme = _apThemeFor(meta);
      var style = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';
      return '<div class="dailylog-completed-row" style="' + style + '">'
        + '<div class="dailylog-completed-info">'
        +   '<div class="dailylog-completed-name">' + _dlEsc(entry.packTitle || entry.packId) + ' &middot; Day ' + entry.dayNumber + '</div>'
        +   (entry.dayTitle ? '<div class="dailylog-completed-sub">' + _dlEsc(entry.dayTitle) + '</div>' : '')
        + '</div>'
        + '<div class="dailylog-completed-actions">'
        +   '<button class="dailylog-btn" data-dl-act="open-day" data-dl-pack="' + _dlEsc(entry.packId) + '" data-dl-day="' + entry.dayNumber + '">Open Day</button>'
        +   '<button class="dailylog-btn" data-dl-act="open-progress" data-dl-pack="' + _dlEsc(entry.packId) + '">Open Progress</button>'
        + '</div>'
        + '</div>';
    }).join('');
  }

  /* Tasks completed section */
  var tasksDoneHtml = '';
  if (act.completedTasks.length) {
    tasksDoneHtml = act.completedTasks.map(function (t) {
      return '<div class="dailylog-task-row">'
        + '<div class="dailylog-task-info">'
        +   '<div class="dailylog-task-title">' + _dlEsc(t.title) + '</div>'
        +   '<div class="dailylog-task-meta">Completed ' + _dlEsc(_dlTimeOf(t.completedAt)) + '</div>'
        + '</div>'
        + '<button class="dailylog-btn" data-dl-act="open-task" data-dl-task="' + _dlEsc(t.id) + '">Open Task</button>'
        + '</div>';
    }).join('');
  }

  /* Previous logs - all dates with saved logs (excluding current) */
  var allLogs = getDailyLogs();
  var allDates = Object.keys(allLogs).sort().reverse(); /* newest first */
  var previousHtml = allDates.filter(function (k) { return k !== date; }).slice(0, 10).map(function (k) {
    var l = allLogs[k];
    var focusSnippet = (l.focus || l.wins || '').slice(0, 80);
    return '<button class="dailylog-prev-item" data-dl-act="open-date" data-dl-date="' + _dlEsc(k) + '">'
      + '<div class="dailylog-prev-date">' + _dlEsc(_dlShortDate(k)) + '</div>'
      + '<div class="dailylog-prev-snippet">' + _dlEsc(focusSnippet || '(empty)') + '</div>'
      + '<div class="dailylog-prev-mood">' + _dlEsc((l.mood || 'neutral').toUpperCase()) + '</div>'
      + '</button>';
  }).join('');

  /* Mood options */
  var moodOptions = DAILY_LOG_MOODS.map(function (m) {
    return '<option value="' + m + '"' + (log.mood === m ? ' selected' : '') + '>' + m.charAt(0).toUpperCase() + m.slice(1) + '</option>';
  }).join('');

  return '<div class="dailylog-hub">'
    + '<div class="dailylog-head">'
    +   '<h1 class="dailylog-title">Daily Log</h1>'
    +   '<p class="dailylog-sub">Review your execution, lessons, and next move.</p>'
    + '</div>'

    /* Stage 25: suggestion card (rendered above the date bar when applicable) */
    + (function () {
        if (typeof shouldShowDailyLogSuggestion !== 'function' || !shouldShowDailyLogSuggestion(date)) return '';
        var sug = buildDailyLogSuggestion(date);
        var previewSnippet = function (label, txt) {
          if (!txt) return '';
          var short = String(txt).replace(/\s+/g, ' ').trim();
          if (short.length > 110) short = short.slice(0, 110) + '...';
          return '<div class="dailylog-suggestion-preview-row">'
            + '<span class="dailylog-suggestion-preview-lbl">' + label + '</span>'
            + '<span class="dailylog-suggestion-preview-text">' + _dlEsc(short) + '</span>'
            + '</div>';
        };
        return '<div class="dailylog-suggestion">'
          + '<div class="dailylog-suggestion-head">'
          +   '<div class="dailylog-suggestion-title">Suggested Daily Review</div>'
          +   '<div class="dailylog-suggestion-sub">We found activity from this day. Use it to start your reflection.</div>'
          + '</div>'
          + '<div class="dailylog-suggestion-summary">' + _dlEsc(sug.summaryText) + '</div>'
          + '<div class="dailylog-suggestion-preview">'
          +   previewSnippet('Focus',     sug.focus)
          +   previewSnippet('Wins',      sug.wins)
          +   previewSnippet('Next Step', sug.nextStep)
          + '</div>'
          + '<div class="dailylog-suggestion-actions">'
          +   '<button class="dailylog-action dailylog-action-primary" data-dl-act="use-suggestion">Use Suggested Draft</button>'
          +   '<button class="dailylog-action dailylog-action-ghost"   data-dl-act="dismiss-suggestion">Ignore</button>'
          + '</div>'
          + '</div>';
      })()

    /* Date selector bar */
    + '<div class="dailylog-datebar">'
    +   '<button class="dailylog-datebtn" data-dl-act="prev-date" data-dl-date="' + _dlEsc(prev) + '">&larr; Previous</button>'
    +   '<button class="dailylog-datebtn dailylog-datebtn-today' + (isToday ? ' is-today' : '') + '" data-dl-act="today">Today</button>'
    +   '<button class="dailylog-datebtn" data-dl-act="next-date" data-dl-date="' + _dlEsc(next) + '">Next &rarr;</button>'
    +   '<div class="dailylog-date-current">' + _dlEsc(_dlPrettyDate(date)) + '</div>'
    +   '<input class="dailylog-date-input" id="dailylogDateInput" type="date" value="' + _dlEsc(date) + '">'
    + '</div>'

    /* Summary cards */
    + '<div class="dailylog-summary">'
    +   '<div class="dailylog-stat"><div class="dailylog-stat-num">' + act.completedDays.length + '</div><div class="dailylog-stat-lbl">Pack Days</div></div>'
    +   '<div class="dailylog-stat"><div class="dailylog-stat-num">' + act.completedTasks.length + '</div><div class="dailylog-stat-lbl">Tasks</div></div>'
    +   '<div class="dailylog-stat"><div class="dailylog-stat-num">' + act.checklistItemsChecked + '</div><div class="dailylog-stat-lbl">Checklist Items</div></div>'
    +   '<div class="dailylog-stat"><div class="dailylog-stat-num">' + act.packsTouched.length + '</div><div class="dailylog-stat-lbl">Packs Touched</div></div>'
    + '</div>'

    /* 2-col layout */
    + '<div class="dailylog-layout">'

    /* Left: Editor */
    +   '<div class="dailylog-editor">'
    +     '<div class="dailylog-section-h">REFLECTION</div>'
    +     '<label class="dailylog-field"><span class="dailylog-field-lbl">Today\'s Focus</span>'
    +       '<input class="dailylog-input" id="dlFocus" type="text" placeholder="What was today\'s focus?" value="' + _dlEsc(log.focus) + '">'
    +     '</label>'
    +     '<label class="dailylog-field"><span class="dailylog-field-lbl">Wins</span>'
    +       '<textarea class="dailylog-textarea" id="dlWins" placeholder="What went well today?">' + _dlEsc(log.wins) + '</textarea>'
    +     '</label>'
    +     '<label class="dailylog-field"><span class="dailylog-field-lbl">Lesson Learned</span>'
    +       '<textarea class="dailylog-textarea" id="dlLesson" placeholder="What did you learn?">' + _dlEsc(log.lesson) + '</textarea>'
    +     '</label>'
    +     '<label class="dailylog-field"><span class="dailylog-field-lbl">What Needs Improvement</span>'
    +       '<textarea class="dailylog-textarea" id="dlImprovement" placeholder="What could be better?">' + _dlEsc(log.improvement) + '</textarea>'
    +     '</label>'
    +     '<label class="dailylog-field"><span class="dailylog-field-lbl">Next Step</span>'
    +       '<input class="dailylog-input" id="dlNextStep" type="text" placeholder="What is the next concrete move?" value="' + _dlEsc(log.nextStep) + '">'
    +     '</label>'
    +     '<label class="dailylog-field dailylog-field-mood"><span class="dailylog-field-lbl">Mood</span>'
    +       '<select class="dailylog-input" id="dlMood">' + moodOptions + '</select>'
    +     '</label>'
    +     '<div class="dailylog-actions">'
    +       '<button class="dailylog-action dailylog-action-primary" data-dl-act="save">Save Daily Log</button>'
    +       '<button class="dailylog-action" data-dl-act="use-template">Use Daily Reflection Template</button>'
    +       '<button class="dailylog-action dailylog-action-ghost" data-dl-act="clear">Clear Draft</button>'
    +       '<div class="dailylog-save-status' + (hasMeaningfulDailyLog(date) ? ' saved' : '') + '" id="dailylogSaveStatus" role="status" aria-live="polite" aria-atomic="true">'
    +         (hasMeaningfulDailyLog(date) ? 'Saved' : '')
    +       '</div>'
    +     '</div>'
    +   '</div>'

    /* Right: Activity + previous logs */
    +   '<div class="dailylog-activity">'
    +     '<div class="dailylog-section"><div class="dailylog-section-h">COMPLETED PACK DAYS</div>'
    +       (completedDaysHtml || '<div class="dailylog-empty">No pack days completed on this date.</div>')
    +     '</div>'
    +     '<div class="dailylog-section"><div class="dailylog-section-h">TASKS COMPLETED</div>'
    +       (tasksDoneHtml || '<div class="dailylog-empty">No tasks completed on this date.</div>')
    +     '</div>'
    +     '<div class="dailylog-section"><div class="dailylog-section-h">CHECKLIST ACTIVITY</div>'
    +       '<div class="dailylog-checklist-row">' + act.checklistItemsChecked + ' checklist item' + (act.checklistItemsChecked === 1 ? '' : 's') + ' checked.</div>'
    +     '</div>'
    +     '<div class="dailylog-section"><div class="dailylog-section-h">PREVIOUS LOGS</div>'
    +       (previousHtml ? '<div class="dailylog-prev-list">' + previousHtml + '</div>' : '<div class="dailylog-empty">No previous logs yet.</div>')
    +     '</div>'
    +   '</div>'

    + '</div>'
    + '</div>';
}

function attachDailyLogEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Stage 26: reset any pending autosave timer left over from a prior render */
  if (_dailyLogAutosaveTimer) { clearTimeout(_dailyLogAutosaveTimer); _dailyLogAutosaveTimer = null; }
  _dailyLogDirty  = false;
  _dailyLogSaving = false;

  /* Stage 26: bind input/change/blur on the 6 editor fields */
  ['dlFocus','dlWins','dlLesson','dlImprovement','dlNextStep'].forEach(function (id) {
    var el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('input', markDailyLogDirty);
    el.addEventListener('blur', function () {
      if (_dailyLogDirty) autosaveDailyLogNow();
    });
  });
  var moodEl = document.getElementById('dlMood');
  if (moodEl) {
    moodEl.addEventListener('change', function () {
      markDailyLogDirty();
      /* Selects don't get a useful blur on iOS - flush on change */
      autosaveDailyLogNow();
    });
  }

  /* Date input - autosave current date BEFORE switching */
  var dateInp = root.querySelector('#dailylogDateInput');
  if (dateInp) {
    dateInp.addEventListener('change', function () {
      if (dateInp.value) {
        if (_dailyLogDirty) autosaveDailyLogNow();
        _dlSetState({ selectedDate: dateInp.value });
        if (window.showWorkspaceView) window.showWorkspaceView('daily');
      }
    });
  }

  /* Action buttons (delegated) */
  Array.prototype.forEach.call(root.querySelectorAll('[data-dl-act]'), function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.stopPropagation();
      var act = btn.getAttribute('data-dl-act');
      if (act === 'prev-date' || act === 'next-date' || act === 'open-date') {
        /* Stage 26: flush autosave for the current date before switching */
        if (_dailyLogDirty) autosaveDailyLogNow();
        var dk = btn.getAttribute('data-dl-date');
        if (dk) {
          _dlSetState({ selectedDate: dk });
          if (window.showWorkspaceView) window.showWorkspaceView('daily');
        }
      } else if (act === 'today') {
        /* Stage 26: flush autosave before switching */
        if (_dailyLogDirty) autosaveDailyLogNow();
        _dlSetState({ selectedDate: _dlTodayKey() });
        if (window.showWorkspaceView) window.showWorkspaceView('daily');
      } else if (act === 'save') {
        var state = _dlState();
        var values = getDailyLogFormValues() || {};
        saveDailyLog(state.selectedDate, values);
        /* Stage 26: reflect saved state in UI without re-rendering the workspace */
        _dailyLogDirty = false;
        _dailyLogLastSavedAt = Date.now();
        if (_dailyLogAutosaveTimer) { clearTimeout(_dailyLogAutosaveTimer); _dailyLogAutosaveTimer = null; }
        setDailyLogSaveStatus('saved', 'Saved');
        if (window.showToast) window.showToast('Daily log saved.', 'success', 1500);
      } else if (act === 'use-template') {
        if (typeof _tplUseTemplate === 'function') {
          _tplUseTemplate('daily-reflection');
        } else if (window.showToast) {
          window.showToast('Open Templates -> Daily Reflection.', 'info', 1800);
        }
      } else if (act === 'clear') {
        if (!window.confirm('Clear the current draft? After autosave fires, the saved entry for this date will be blank.')) return;
        ['dlFocus','dlWins','dlLesson','dlImprovement','dlNextStep'].forEach(function (id) {
          var el = document.getElementById(id);
          if (el) el.value = '';
        });
        var moodEl2 = document.getElementById('dlMood');
        if (moodEl2) moodEl2.value = 'neutral';
        if (window.showToast) window.showToast('Draft cleared.', 'info', 1200);
        /* Stage 26: cleared state should also autosave so the persisted log matches the editor */
        markDailyLogDirty();
        scheduleDailyLogAutosave();
      } else if (act === 'open-day') {
        var pid = btn.getAttribute('data-dl-pack');
        var dn  = parseInt(btn.getAttribute('data-dl-day'), 10);
        if (pid && !isNaN(dn) && window.openPackDay) window.openPackDay(pid, dn);
      } else if (act === 'open-progress') {
        var pid2 = btn.getAttribute('data-dl-pack');
        if (pid2 && window.openPackProgress) window.openPackProgress(pid2);
      } else if (act === 'open-task') {
        var tid = btn.getAttribute('data-dl-task');
        if (tid && window.openTaskInWorkspace) window.openTaskInWorkspace(tid);
      } else if (act === 'use-suggestion') {
        /* Stage 25: fill DOM fields with the suggestion, but DO NOT save.
           The user must still click Save Daily Log to persist.
           Stage 26: mark dirty so the autosave debounce + indicator engage. */
        var stateUS = _dlState();
        var sug = buildDailyLogSuggestion(stateUS.selectedDate);
        var f = document.getElementById('dlFocus');       if (f) f.value = sug.focus;
        var w = document.getElementById('dlWins');        if (w) w.value = sug.wins;
        var l = document.getElementById('dlLesson');      if (l) l.value = sug.lesson;
        var ii = document.getElementById('dlImprovement');if (ii) ii.value = sug.improvement;
        var n = document.getElementById('dlNextStep');    if (n) n.value = sug.nextStep;
        var m = document.getElementById('dlMood');        if (m && DAILY_LOG_MOODS.indexOf(sug.mood) >= 0) m.value = sug.mood;
        if (window.showToast) window.showToast('Suggested draft applied. Review and save when ready.', 'success', 2200);
        _dailyLogDirty = true;
        setDailyLogSaveStatus('dirty', 'Unsaved suggested draft');
        scheduleDailyLogAutosave(2500);
      } else if (act === 'dismiss-suggestion') {
        var stateDS = _dlState();
        dismissDailyLogSuggestion(stateDS.selectedDate);
        if (window.showWorkspaceView) window.showWorkspaceView('daily');
      }
    });
  });
}

/* ════════════════════════════════════════════════════════════════
   STAGE 25 - Daily Log auto-prefill from activity
   ════════════════════════════════════════════════════════════════ */

function hasMeaningfulDailyLog(dateKey) {
  if (!dateKey) return false;
  var log = getDailyLog(dateKey);
  if (!log) return false;
  /* Any of the 5 reflection fields with non-blank content counts as meaningful */
  var fields = ['focus','wins','lesson','improvement','nextStep'];
  for (var i = 0; i < fields.length; i++) {
    var v = log[fields[i]];
    if (typeof v === 'string' && v.trim() !== '') return true;
  }
  return false;
}

/* Stage 25: defensive JSON parse that doesn't depend on Stage 20's
   safeJsonParse being loaded yet. */
function _dlSafeParse(raw, fallback) {
  if (typeof safeJsonParse === 'function') return safeJsonParse(raw, fallback);
  if (raw == null || raw === '') return fallback;
  try { var p = JSON.parse(raw); return (p === undefined) ? fallback : p; }
  catch (e) { return fallback; }
}
function isDailyLogSuggestionDismissed(dateKey) {
  if (!dateKey) return false;
  try {
    var map = _dlSafeParse(localStorage.getItem('ethos_daily_log_suggestion_dismissed'), {});
    return !!(map && map[dateKey]);
  } catch (e) { return false; }
}
function dismissDailyLogSuggestion(dateKey) {
  if (!dateKey) return;
  try {
    var map = _dlSafeParse(localStorage.getItem('ethos_daily_log_suggestion_dismissed'), {});
    if (!map || typeof map !== 'object') map = {};
    map[dateKey] = true;
    localStorage.setItem('ethos_daily_log_suggestion_dismissed', JSON.stringify(map));
  } catch (e) {}
}

function buildDailyLogSuggestion(dateKey) {
  var act = getDailyActivitySummary(dateKey);
  var hasPackDays   = act.completedDays.length > 0;
  var hasTasks      = act.completedTasks.length > 0;
  var hasChecklist  = act.checklistItemsChecked > 0;

  /* ── Focus ── */
  var focus;
  if (hasPackDays) {
    var firstPack = act.completedDays[0];
    focus = 'Execute ' + (firstPack.packTitle || firstPack.packId) + ' and keep momentum.';
  } else if (hasTasks) {
    focus = 'Complete key tasks and keep the day moving.';
  } else if (hasChecklist) {
    focus = 'Follow through on small execution steps.';
  } else {
    focus = 'Review the day and choose the next move.';
  }

  /* ── Wins ── */
  var winLines = [];
  if (hasPackDays) {
    act.completedDays.forEach(function (d) {
      var line = 'Completed ' + (d.packTitle || d.packId);
      if (d.dayNumber != null) line += ' Day ' + d.dayNumber;
      if (d.dayTitle) line += ': ' + d.dayTitle;
      line += '.';
      winLines.push(line);
    });
  }
  if (hasTasks) {
    winLines.push('Finished ' + act.completedTasks.length + ' task' + (act.completedTasks.length === 1 ? '' : 's') + '.');
  }
  if (hasChecklist) {
    winLines.push('Checked ' + act.checklistItemsChecked + ' checklist item' + (act.checklistItemsChecked === 1 ? '' : 's') + '.');
  }
  var wins = winLines.join('\n');

  /* ── Lesson ── */
  var lesson;
  var heavyActivity = (act.completedTasks.length >= 3) || (act.checklistItemsChecked >= 6);
  if (heavyActivity) {
    lesson = 'Momentum comes from finishing small commitments, not waiting for perfect motivation.';
  } else {
    lesson = 'Small actions compound when I track them honestly.';
  }

  /* ── Improvement ── */
  var improvement = 'Be more intentional about the first priority before adding more tasks.';

  /* ── Next Step ── */
  var nextStep;
  var pack = (typeof getActivePack === 'function') ? getActivePack() : null;
  if (pack && pack.days && pack.days.length) {
    var nextDay = (typeof _apNextIncompleteDay === 'function') ? _apNextIncompleteDay(pack) : null;
    if (nextDay) {
      nextStep = 'Continue ' + pack.title + ' - Day ' + nextDay.day + ': ' + nextDay.title + '.';
    } else {
      nextStep = 'Choose the next pack to start or review your progress.';
    }
  } else {
    nextStep = 'Choose one priority task and complete it before adding more.';
  }

  /* ── Mood ── */
  var mood;
  if (hasPackDays || act.completedTasks.length >= 3) mood = 'strong';
  else if (hasTasks || hasChecklist)                 mood = 'focused';
  else                                                mood = 'neutral';

  /* ── Summary text ── */
  var summaryParts = [];
  if (hasPackDays)  summaryParts.push(act.completedDays.length + ' pack day' + (act.completedDays.length === 1 ? '' : 's'));
  if (hasTasks)     summaryParts.push(act.completedTasks.length + ' task' + (act.completedTasks.length === 1 ? '' : 's'));
  if (hasChecklist) summaryParts.push(act.checklistItemsChecked + ' checklist item' + (act.checklistItemsChecked === 1 ? '' : 's'));
  var summaryText = summaryParts.length
    ? ('Activity: ' + summaryParts.join(' - ') + '.')
    : 'No recorded activity yet.';

  return {
    focus:       focus,
    wins:        wins,
    lesson:      lesson,
    improvement: improvement,
    nextStep:    nextStep,
    mood:        mood,
    summaryText: summaryText
  };
}

function shouldShowDailyLogSuggestion(dateKey) {
  if (!dateKey) return false;
  /* Already meaningful log -> never show */
  if (hasMeaningfulDailyLog(dateKey)) return false;
  /* Dismissed for this date -> never show */
  if (isDailyLogSuggestionDismissed(dateKey)) return false;
  /* Only show when there's real activity to summarize */
  var act = getDailyActivitySummary(dateKey);
  return (act.completedDays.length > 0)
      || (act.completedTasks.length > 0)
      || (act.checklistItemsChecked > 0);
}

if (typeof window !== 'undefined') {
  window.hasMeaningfulDailyLog        = hasMeaningfulDailyLog;
  window.isDailyLogSuggestionDismissed = isDailyLogSuggestionDismissed;
  window.dismissDailyLogSuggestion    = dismissDailyLogSuggestion;
  window.buildDailyLogSuggestion      = buildDailyLogSuggestion;
  window.shouldShowDailyLogSuggestion = shouldShowDailyLogSuggestion;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 26 - Daily Log autosave + dirty indicator
   ════════════════════════════════════════════════════════════════ */

var _dailyLogAutosaveTimer = null;
var _dailyLogDirty         = false;
var _dailyLogSaving        = false;
var _dailyLogLastSavedAt   = 0;
var DL_AUTOSAVE_DEBOUNCE_MS = 1500;

/* Read current values from the editor DOM (returns null if editor is gone). */
function getDailyLogFormValues() {
  var f = document.getElementById('dlFocus');
  var w = document.getElementById('dlWins');
  var l = document.getElementById('dlLesson');
  var ii = document.getElementById('dlImprovement');
  var n = document.getElementById('dlNextStep');
  var m = document.getElementById('dlMood');
  if (!f && !w && !l && !ii && !n && !m) return null;
  return {
    focus:       f ? f.value  : '',
    wins:        w ? w.value  : '',
    lesson:      l ? l.value  : '',
    improvement: ii ? ii.value : '',
    nextStep:    n ? n.value  : '',
    mood:        m ? m.value  : 'neutral'
  };
}

function setDailyLogSaveStatus(status, text) {
  var el = document.getElementById('dailylogSaveStatus');
  if (!el) return;
  /* Strip prior state classes */
  ['saved','dirty','saving','error'].forEach(function (s) { el.classList.remove(s); });
  if (status) el.classList.add(status);
  if (typeof text === 'string') el.textContent = text;
}

function markDailyLogDirty() {
  _dailyLogDirty = true;
  setDailyLogSaveStatus('dirty', 'Unsaved changes');
  scheduleDailyLogAutosave();
}

function resetDailyLogDirtyState() {
  _dailyLogDirty = false;
  if (_dailyLogAutosaveTimer) { clearTimeout(_dailyLogAutosaveTimer); _dailyLogAutosaveTimer = null; }
}

function scheduleDailyLogAutosave(delayMs) {
  if (_dailyLogAutosaveTimer) clearTimeout(_dailyLogAutosaveTimer);
  var d = (typeof delayMs === 'number' && delayMs > 0) ? delayMs : DL_AUTOSAVE_DEBOUNCE_MS;
  _dailyLogAutosaveTimer = setTimeout(function () {
    _dailyLogAutosaveTimer = null;
    autosaveDailyLogNow();
  }, d);
}

function autosaveDailyLogNow() {
  if (!_dailyLogDirty) return false;
  if (_dailyLogSaving) return false;
  var state = _dlState();
  var values = getDailyLogFormValues();
  if (!values) return false; /* editor not in DOM */
  _dailyLogSaving = true;
  setDailyLogSaveStatus('saving', 'Saving...');
  var ok = false;
  try {
    ok = !!saveDailyLog(state.selectedDate, values);
  } catch (e) { ok = false; }
  _dailyLogSaving = false;
  if (ok) {
    _dailyLogDirty = false;
    _dailyLogLastSavedAt = Date.now();
    setDailyLogSaveStatus('saved', 'Draft saved - just now');
    return true;
  } else {
    setDailyLogSaveStatus('error', 'Autosave failed');
    return false;
  }
}

if (typeof window !== 'undefined') {
  window.getDailyLogFormValues   = getDailyLogFormValues;
  window.setDailyLogSaveStatus   = setDailyLogSaveStatus;
  window.scheduleDailyLogAutosave = scheduleDailyLogAutosave;
  window.autosaveDailyLogNow     = autosaveDailyLogNow;
  window.markDailyLogDirty       = markDailyLogDirty;
  window.resetDailyLogDirtyState = resetDailyLogDirtyState;
}

function installStage24DailyLogHub() {
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};
  /* Replace Stage 6 wrapper entirely */
  window.EE_WORKSPACE_RENDER['daily'] = renderDailyLogWorkspace;
  window.EE_WORKSPACE_EVENTS['daily'] = attachDailyLogEvents;
}

if (typeof window !== 'undefined') {
  window.getDailyLogs              = getDailyLogs;
  window.saveDailyLogs             = saveDailyLogs;
  window.getDailyLog               = getDailyLog;
  window.saveDailyLog              = saveDailyLog;
  window.getDailyActivitySummary   = getDailyActivitySummary;
  window.renderDailyLogWorkspace   = renderDailyLogWorkspace;
  window.attachDailyLogEvents      = attachDailyLogEvents;
  window.openDailyLogDate          = openDailyLogDate;
  window.installStage24DailyLogHub = installStage24DailyLogHub;
}

/* ── Suggested-pack chips for the empty state ── */
function _apSuggestedPacks() {
  var ids = ['morning-mastery','clear-skin','business-idea'];
  if (typeof PLAN_PACKS_DATA === 'undefined') return [];
  var found = [];
  ids.forEach(function (id) {
    for (var i = 0; i < PLAN_PACKS_DATA.length; i++) {
      if (PLAN_PACKS_DATA[i].id === id) { found.push(PLAN_PACKS_DATA[i]); return; }
    }
  });
  return found;
}

/* ════════════════════════════════════════════════════════════════
   STAGE 22 - Today's open tasks card inside My Active Plan
   ════════════════════════════════════════════════════════════════ */
function _apRenderTodayTasksCard() {
  if (typeof getTasks !== 'function') return '';
  var today = (typeof todayKey === 'function') ? todayKey() : new Date().toISOString().slice(0, 10);
  var allTasks = getTasks();
  var todayOpen = allTasks.filter(function (t) {
    return t.status === 'open' && t.dueDate === today;
  });
  /* Sort by priority desc (high -> medium -> low), then by updatedAt desc */
  var prioRank = { high: 0, medium: 1, low: 2 };
  todayOpen.sort(function (a, b) {
    var pa = prioRank[a.priority] != null ? prioRank[a.priority] : 1;
    var pb = prioRank[b.priority] != null ? prioRank[b.priority] : 1;
    if (pa !== pb) return pa - pb;
    return (b.updatedAt || 0) - (a.updatedAt || 0);
  });

  var visible    = todayOpen.slice(0, 5);
  var overflow   = todayOpen.length - visible.length;
  var rowsHtml   = '';

  if (visible.length) {
    rowsHtml = visible.map(function (t) {
      var prioClass = 'task-priority-' + (t.priority || 'medium');
      var linkedHtml = '';
      var syncBadge = '';
      if (t.linkedPackId) {
        var packTitle = (typeof _taskPackTitle === 'function') ? _taskPackTitle(t.linkedPackId) : t.linkedPackId;
        linkedHtml = '<span class="ap-task-linked">' + _apDpEsc(packTitle)
          + (t.linkedDayNumber != null ? ' &middot; Day ' + t.linkedDayNumber : '') + '</span>';
        /* Stage 23: linked day sync state */
        if (t.linkedDayNumber != null && typeof isPackDayComplete === 'function') {
          var dayDone = isPackDayComplete(t.linkedPackId, t.linkedDayNumber);
          syncBadge = '<span class="ap-task-sync-badge ' + (dayDone ? 'task-sync-complete' : 'task-sync-open') + '">'
            + (dayDone ? 'DAY DONE' : 'DAY OPEN') + '</span>';
        }
      }
      var hasDayLink = !!(t.linkedPackId && t.linkedDayNumber != null);
      return '<div class="ap-task-row ' + prioClass + '" data-ap-task-id="' + _apDpEsc(t.id) + '">'
        + '<button class="ap-task-check" data-ap-task-act="complete" data-ap-task-id="' + _apDpEsc(t.id) + '" aria-pressed="false" aria-label="Complete task"></button>'
        + '<div class="ap-task-main">'
        +   '<div class="ap-task-title">' + _apDpEsc(t.title) + '</div>'
        +   '<div class="ap-task-meta">'
        +     '<span class="ap-task-priority ' + prioClass + '">' + (t.priority || 'medium').toUpperCase() + '</span>'
        +     linkedHtml
        +     syncBadge
        +   '</div>'
        + '</div>'
        + '<div class="ap-task-actions">'
        +   (hasDayLink ? '<button class="ap-task-btn" data-ap-task-act="open-day" data-ap-task-id="' + _apDpEsc(t.id) + '">Open Day</button>' : '')
        +   '<button class="ap-task-btn" data-ap-task-act="open" data-ap-task-id="' + _apDpEsc(t.id) + '">Open</button>'
        + '</div>'
        + '</div>';
    }).join('');
  }

  /* Suggested-from-active-plan inline. Only show when no open today-task already exists
     for the active pack's next day (Stage 21's helper handles the dedup). */
  var suggested = (typeof _taskSuggestedFromActivePlan === 'function') ? _taskSuggestedFromActivePlan() : null;
  var suggestedHtml = '';
  if (suggested) {
    suggestedHtml = '<div class="ap-task-suggested-inline">'
      + '<div class="ap-task-suggested-text">' + _apDpEsc(suggested.title) + '</div>'
      + '<button class="ap-task-btn ap-task-btn-primary" data-ap-task-act="add-suggested">Add Plan Task</button>'
      + '</div>';
  }

  var overflowHtml = (overflow > 0)
    ? '<button class="ap-tasks-more" data-ap-task-act="open-all">Open all tasks (' + overflow + ' more)</button>'
    : '';

  var emptyHtml = visible.length
    ? ''
    : '<div class="ap-task-empty">No tasks due today.</div>';

  return '<div class="ap-card ap-tasks-card">'
    + '<div class="ap-card-h">TODAY\'S TASKS</div>'
    + '<div class="ap-tasks-sub">Open tasks due today.</div>'
    + (rowsHtml ? '<div class="ap-task-rows">' + rowsHtml + '</div>' : emptyHtml)
    + suggestedHtml
    + overflowHtml
    + '<div class="ap-task-quickadd">'
    +   '<input class="ap-task-quickadd-input" id="apTaskQuickInput" type="text" placeholder="Add task for today..." autocomplete="off">'
    +   '<button class="ap-task-quickadd-btn" id="apTaskQuickAdd">Add</button>'
    + '</div>'
    + '<button class="ap-foot-btn ap-tasks-open-all" data-ap-task-act="open-all">Open Tasks</button>'
    + '</div>';
}

function _apAttachTodayTasksEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  var card = root.querySelector('.ap-tasks-card');
  if (!card) return;

  /* Quick-add */
  var qInp = card.querySelector('#apTaskQuickInput');
  var qBtn = card.querySelector('#apTaskQuickAdd');
  function quickAdd() {
    if (!qInp || typeof createTask !== 'function') return;
    var title = qInp.value.trim();
    if (!title) return;
    createTask({ title: title, dueDate: todayKey(), priority: 'medium' });
    qInp.value = '';
    if (window.showToast) window.showToast('Task added.', 'success', 1200);
    if (window.showWorkspaceView) window.showWorkspaceView('active-plan');
    if (typeof window.updateDailyReminderBanner === 'function') window.updateDailyReminderBanner();
  }
  if (qBtn) qBtn.addEventListener('click', quickAdd);
  if (qInp) qInp.addEventListener('keydown', function (e) { if (e.key === 'Enter') quickAdd(); });

  /* Delegated task action buttons */
  Array.prototype.forEach.call(card.querySelectorAll('[data-ap-task-act]'), function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.stopPropagation();
      var act = btn.getAttribute('data-ap-task-act');
      var tid = btn.getAttribute('data-ap-task-id');
      if (act === 'complete') {
        if (typeof completeTask === 'function') completeTask(tid);
        if (window.showToast) window.showToast('Task completed.', 'success', 1200);
        if (window.showWorkspaceView) window.showWorkspaceView('active-plan');
        if (typeof window.updateDailyReminderBanner === 'function') window.updateDailyReminderBanner();
      } else if (act === 'open') {
        if (typeof openTaskInWorkspace === 'function') openTaskInWorkspace(tid);
      } else if (act === 'open-day') {
        /* Look up the linked pack + day on the task and open it */
        if (typeof getTasks !== 'function') return;
        var tasks = getTasks();
        for (var i = 0; i < tasks.length; i++) {
          if (tasks[i].id === tid && tasks[i].linkedPackId && tasks[i].linkedDayNumber != null) {
            if (window.openPackDay) window.openPackDay(tasks[i].linkedPackId, tasks[i].linkedDayNumber);
            break;
          }
        }
      } else if (act === 'open-all') {
        if (window.switchDashboardView) window.switchDashboardView('tasks');
      } else if (act === 'add-suggested') {
        if (typeof _taskSuggestedFromActivePlan !== 'function') return;
        var sug = _taskSuggestedFromActivePlan();
        if (!sug) return;
        createTask({
          title:           sug.title,
          priority:        'medium',
          dueDate:         todayKey(),
          linkedPackId:    sug.linkedPackId,
          linkedDayNumber: sug.linkedDayNumber,
          tags:            sug.tags
        });
        if (window.showToast) window.showToast('Active plan task added.', 'success', 1500);
        if (window.showWorkspaceView) window.showWorkspaceView('active-plan');
      }
    });
  });
}

/* ── Renderer ── */
function renderActivePlan() {
  var pack = getActivePack();
  /* Stage 11: cross-pack Today Command Center is the daily home strip */
  var todayDashboardHtml = (typeof renderTodayDashboard === 'function') ? renderTodayDashboard() : '';

  if (!pack) {
    /* Empty state. If the Today dashboard already covers the no-started-pack
       case with its own empty card, skip the legacy suggested-packs grid. */
    var startedAny = (typeof getStartedPacks === 'function') ? (getStartedPacks().length > 0) : false;
    var suggested = startedAny ? '' : _apSuggestedPacks().map(function (p) {
      var meta  = _apMetaFor(p.id);
      var theme = _apThemeFor(meta);
      return '<div class="ap-suggest" data-suggest="' + _apDpEsc(p.id) + '" '
        + 'style="--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';">'
        + '<div class="ap-suggest-icon">' + p.icon + '</div>'
        + '<div class="ap-suggest-title">' + _apDpEsc(p.title) + '</div>'
        + '<div class="ap-suggest-meta">' + _apDpEsc(p.category) + ' - ' + p.totalDays + ' days</div>'
        + '<div class="ap-suggest-cta">Open Pack</div>'
        + '</div>';
    }).join('');
    /* When packs are started but no active plan: show the dashboard +
       a compact "Pick one as your active plan" prompt. */
    var hasActiveBody = startedAny
      ? ''
      : '<div class="ap-empty">'
        +   '<div class="ap-empty-icon">★</div>'
        +   '<div class="ap-empty-title">No Active Plan Yet</div>'
        +   '<div class="ap-empty-sub">Choose a Plan Pack to begin your guided transformation.</div>'
        +   '<div class="ap-empty-actions">'
        +     '<button class="ee-active-empty-cta" id="apBrowsePacks">Browse Plan Packs</button>'
        +     '<button class="ee-active-empty-cta" id="apCompareEmpty">Compare Plans</button>'
        +   '</div>'
        + '</div>'
        + (suggested ? '<div class="ap-suggest-head">Suggested starting packs</div>'
                     + '<div class="ap-suggest-row">' + suggested + '</div>' : '');
    return '<div class="ap-shell">'
      + todayDashboardHtml
      + hasActiveBody
      + '</div>';
  }

  /* Active state - full dashboard */
  var meta  = _apMetaFor(pack.id);
  var theme = _apThemeFor(meta);
  var comp  = _apCompletion(pack);
  var pp    = _apPackProgressFor(pack.id);
  var nextDay = _apNextIncompleteDay(pack);
  var streak  = 0;
  if (pack.days && pack.days.length) {
    for (var s = pack.days.length - 1; s >= 0; s--) {
      if (pp['day_' + pack.days[s].day]) streak++; else break;
    }
  }
  var hasDays = pack.days && pack.days.length > 0;

  /* Hero */
  var ctaLabel, ctaCls = '';
  if (!hasDays) { ctaLabel = 'Days In Development'; ctaCls = ' pp-dh-cta-muted'; }
  else if (nextDay) ctaLabel = (comp.completed > 0 ? 'Continue Day ' + nextDay.day : 'Start Day ' + nextDay.day);
  else ctaLabel = 'Review Progress';

  var styleVars = '--pp-pri:' + theme.primary + ';--pp-sec:' + theme.secondary + ';--pp-glow:' + theme.glow + ';';
  var heroHtml = ''
    + '<div class="ap-hero" style="' + styleVars + '">'
    +   '<div class="ap-hero-glow" aria-hidden="true"></div>'
    +   '<div class="ap-hero-top">'
    +     '<div class="ap-hero-icon">' + pack.icon + '</div>'
    +     '<div class="ap-hero-info">'
    +       '<span class="ap-hero-status">ACTIVE PLAN</span>'
    +       '<h1 class="ap-hero-title">' + _apDpEsc(pack.title) + '</h1>'
    +       '<div class="ap-hero-meta">'
    +         '<span>' + _apDpEsc(pack.category) + '</span><span class="ap-hero-sep">&middot;</span>'
    +         '<span>' + pack.totalDays + ' days</span><span class="ap-hero-sep">&middot;</span>'
    +         '<span>' + _apDpEsc(meta.difficulty || 'Medium') + '</span>'
    +         (nextDay ? '<span class="ap-hero-sep">&middot;</span><span class="ap-hero-current">Day ' + nextDay.day + ' of ' + pack.totalDays + '</span>' : '')
    +       '</div>'
    +     '</div>'
    +     '<button class="ap-action-primary' + ctaCls + '" id="apContinue">' + ctaLabel + '</button>'
    +   '</div>'
    +   '<div class="ap-hero-prog">'
    +     '<div class="ap-hero-prog-row">'
    +       '<span class="ap-hero-prog-lbl">Progress</span>'
    +       '<span class="ap-hero-prog-val">' + comp.completed + ' / ' + comp.total + ' days &middot; ' + comp.pct + '%</span>'
    +     '</div>'
    +     '<div class="ap-hero-prog-bar"><div class="ap-hero-prog-fill" style="width:' + comp.pct + '%;"></div></div>'
    +   '</div>'
    + '</div>';

  /* Today's Focus */
  var todayHtml;
  if (!hasDays) {
    todayHtml = '<div class="ap-card ap-today-card">'
      + '<div class="ap-card-h">TODAY\'S FOCUS</div>'
      + '<div class="ap-section-body">Day-by-day content for this pack is in development. The Overview, Schedule, Notes, and Tools tabs are available on the pack detail page.</div>'
      + '</div>';
  } else if (nextDay) {
    todayHtml = '<div class="ap-card ap-today-card">'
      + '<div class="ap-card-h">TODAY\'S FOCUS</div>'
      + '<div class="ap-today-num">Day ' + nextDay.day + '</div>'
      + '<div class="ap-today-title">' + _apDpEsc(nextDay.title) + '</div>'
      + '<div class="ap-today-text">' + _apDpEsc(nextDay.task || '') + '</div>'
      + '<div class="ap-today-action">'
      +   '<div class="ap-today-action-lbl">ACTION</div>'
      +   '<div class="ap-today-action-text">' + _apDpEsc(nextDay.action || '') + '</div>'
      + '</div>'
      + '<button class="ap-action-primary ap-today-cta" id="apToday">Continue Today</button>'
      /* Stage 32-B: daily-loop shortcut. Reuses the existing ap-foot-btn
         secondary style so no new CSS is required. Routes to the Daily Log
         workspace via the central switchDashboardView - the Daily Log
         auto-populates today's activity (Stage 25 suggestion + pack-day +
         task rollup) on mount, so a single click closes the daily loop. */
      + '<button class="ap-foot-btn" id="activePlanLogTodayBtn" type="button">Log Today</button>'
      + '</div>';
  } else {
    /* Stage 9: stronger Plan Complete state with ceremony entry point */
    todayHtml = '<div class="ap-card ap-today-card ap-complete-card">'
      + '<div class="ap-card-h">PLAN COMPLETE</div>'
      + '<div class="ap-today-title">' + _apDpEsc(pack.title) + ' complete.</div>'
      + '<div class="ap-today-text">You completed ' + _apDpEsc(pack.title) + '. Review your progress, replay the ceremony, or choose the next pack.</div>'
      + '<div class="ap-complete-actions">'
      +   '<button class="ap-action-primary ap-today-cta" id="apToday">Review Progress</button>'
      +   '<button class="ap-foot-btn" id="apViewCeremony">View Completion</button>'
      +   '<button class="ap-foot-btn" id="apChooseNext">Choose Next Pack</button>'
      +   '<button class="ap-foot-btn ap-foot-btn-danger" id="apClearActive">Clear Active Plan</button>'
      + '</div>'
      + '</div>';
  }

  /* Today's Checklist - Stage 8: use real per-day checklist if available,
     synced with the day view via shared localStorage state. */
  var realChecklist = (nextDay && typeof getChecklistForDay === 'function')
    ? getChecklistForDay(pack, nextDay) : null;
  var checklistHtml;
  if (realChecklist && realChecklist.length) {
    var apClState = getDayChecklistState(pack.id, nextDay.day);
    checklistHtml = '<div class="ap-card ap-checklist-card">'
      + '<div class="ap-card-h">TODAY\'S CHECKLIST &middot; DAY ' + nextDay.day + '</div>'
      + '<ul class="ap-checklist ap-checklist-real">'
      +   realChecklist.map(function (label, i) {
            var checked = isChecklistItemChecked(apClState, i);
            return '<li class="ap-chk' + (checked ? ' done' : '') + '" '
              +    'data-cl-pack="' + _apDpEsc(pack.id) + '" data-cl-day="' + nextDay.day + '" data-cl-idx="' + i + '" '
              +    'role="button" tabindex="0" aria-pressed="' + (checked ? 'true' : 'false') + '">'
              +      '<span class="ap-chk-box" aria-hidden="true">' + (checked ? '&#10003;' : '') + '</span>'
              +      '<span class="ap-chk-text">' + _apDpEsc(label) + '</span>'
              +    '</li>';
          }).join('')
      + '</ul>'
      + '</div>';
  } else {
    var fallback = nextDay
      ? [ "Read today's focus", "Complete today's action", "Write reflection", 'Mark day complete' ]
      : [ 'Review your progress', 'Pick the next pack or restart' ];
    checklistHtml = '<div class="ap-card ap-checklist-card">'
      + '<div class="ap-card-h">TODAY\'S CHECKLIST</div>'
      + '<ul class="ap-checklist">'
      +   fallback.map(function (it) {
            return '<li class="ap-chk"><span class="ap-chk-box"></span><span class="ap-chk-text">' + _apDpEsc(it) + '</span></li>';
          }).join('')
      + '</ul>'
      + '</div>';
  }

  /* Progress */
  var milestones = [25,50,75,100].map(function (m) {
    var hit = comp.pct >= m;
    return '<div class="ap-mile' + (hit ? ' ap-mile-hit' : '') + '">'
      + '<div class="ap-mile-num">' + m + '%</div>'
      + '<div class="ap-mile-lbl">' + (hit ? 'Reached' : 'Locked') + '</div>'
      + '</div>';
  }).join('');
  var progressHtml = '<div class="ap-card ap-progress-card">'
    + '<div class="ap-card-h">PROGRESS</div>'
    + '<div class="ap-prog-stats">'
    +   '<div class="ap-pstat"><div class="ap-pstat-num">' + comp.completed + '</div><div class="ap-pstat-lbl">Done</div></div>'
    +   '<div class="ap-pstat"><div class="ap-pstat-num">' + Math.max(0, comp.total - comp.completed) + '</div><div class="ap-pstat-lbl">Left</div></div>'
    +   '<div class="ap-pstat"><div class="ap-pstat-num">' + streak + '</div><div class="ap-pstat-lbl">Streak</div></div>'
    +   '<div class="ap-pstat"><div class="ap-pstat-num">' + comp.pct + '%</div><div class="ap-pstat-lbl">Complete</div></div>'
    + '</div>'
    + '<div class="ap-prog-bar"><div class="ap-prog-fill" style="width:' + comp.pct + '%;"></div></div>'
    + '<div class="ap-miles">' + milestones + '</div>'
    + '</div>';

  /* Weekly Schedule - Stage 8: pack-specific via PACK_SCHEDULES */
  var apSched = (typeof PACK_SCHEDULES !== 'undefined') ? PACK_SCHEDULES[pack.id] : null;
  var apBlocks;
  if (apSched && apSched.length) {
    apBlocks = apSched.slice(0, 3);
  } else {
    apBlocks = [
      { label:'Mon - Fri', title:'Core Practice', items:[
          pack.title + ' core practice',
          '10-15 minutes movement or stretching',
          'Short reflection note',
          'Set tomorrow\'s top priority' ] },
      { label:'Sat',          title:'Light Reset', items:[ 'Lighter version of core practice', 'Catch up on any missed day' ] },
      { label:'Sun (Review)', title:'Weekly Review', items:[ 'Weekly review (15 minutes)', 'Plan the next 7 days', 'Adjust schedule based on what worked' ] }
    ];
  }
  function _apSchedBlock(b, accent) {
    var title = b.title ? ('<div class="ap-sched-title">' + _apDpEsc(b.title) + '</div>') : '';
    return '<div class="ap-sched-block' + (accent ? ' ap-sched-block-accent' : '') + '">'
      + '<div class="ap-sched-label">' + _apDpEsc(b.label) + '</div>'
      + title
      + '<ul class="ap-sched-list">' + (b.items || []).map(function (i) { return '<li>' + _apDpEsc(i) + '</li>'; }).join('') + '</ul>'
      + '</div>';
  }
  var scheduleHtml = '<div class="ap-card ap-schedule-card">'
    + '<div class="ap-card-h">WEEKLY SCHEDULE</div>'
    + '<div class="ap-sched-grid">'
    +   _apSchedBlock(apBlocks[0], true)
    +   (apBlocks[1] ? _apSchedBlock(apBlocks[1]) : '')
    +   (apBlocks[2] ? _apSchedBlock(apBlocks[2]) : '')
    + '</div>'
    + '</div>';

  /* Connected Worlds */
  var worlds = meta.worlds || [];
  var worldsHtml = '';
  if (worlds.length) {
    worldsHtml = '<div class="ap-card ap-worlds-card">'
      + '<div class="ap-card-h">CONNECTED WORLDS</div>'
      + '<div class="ap-worlds">'
      +   worlds.map(function (w) {
            return '<button class="ap-world-chip" data-world="' + _apDpEsc(w) + '">' + _apDpEsc(w) + '</button>';
          }).join('')
      + '</div>'
      + '</div>';
  }

  /* Notes preview */
  var notesText = '';
  try { notesText = localStorage.getItem('ee_pack_notes_' + pack.id) || ''; } catch (e) {}
  var notesPreview = notesText
    ? _apDpEsc(notesText.length > 320 ? notesText.slice(0, 320) + '...' : notesText)
    : '<span class="ap-notes-empty">No notes saved yet. Open the Notes tab on the pack detail page to start writing.</span>';
  var notesHtml = '<div class="ap-card ap-notes-card">'
    + '<div class="ap-card-h">NOTES PREVIEW</div>'
    + '<div class="ap-notes-preview">' + notesPreview + '</div>'
    + '<button class="ap-link-btn" id="apOpenNotes">Open Notes Tab</button>'
    + '</div>';

  /* Footer actions: Reset */
  var footHtml = '<div class="ap-foot">'
    + '<button class="ap-foot-btn" id="apOpenDetail">Open Pack Detail</button>'
    + '<button class="ap-foot-btn ap-foot-btn-danger" id="apReset">Reset Plan</button>'
    + '</div>';

  /* Stage 22: surface today's open tasks under Today's Focus */
  var tasksHtml = (typeof _apRenderTodayTasksCard === 'function') ? _apRenderTodayTasksCard() : '';

  return '<div class="ap-shell" style="' + styleVars + '">'
    + todayDashboardHtml
    + heroHtml
    + '<div class="ap-grid">'
    +   '<div class="ap-col-left">' + todayHtml + tasksHtml + checklistHtml + worldsHtml + '</div>'
    +   '<div class="ap-col-right">' + progressHtml + scheduleHtml + notesHtml + '</div>'
    + '</div>'
    + footHtml
    + '</div>';
}

function attachActivePlanEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;

  /* Stage 11: Today Command Center events */
  if (typeof attachTodayDashboardEvents === 'function') attachTodayDashboardEvents();

  /* Stage 22: Today's Tasks card events */
  if (typeof _apAttachTodayTasksEvents === 'function') _apAttachTodayTasksEvents();

  /* Empty-state buttons */
  var browse = root.querySelector('#apBrowsePacks') || root.querySelector('#eeBrowsePacksBtn');
  if (browse) browse.addEventListener('click', function () {
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });
  var compareEmpty = root.querySelector('#apCompareEmpty');
  if (compareEmpty) compareEmpty.addEventListener('click', function () {
    if (window.showPlanComparisonModal) window.showPlanComparisonModal();
  });
  Array.prototype.forEach.call(root.querySelectorAll('[data-suggest]'), function (card) {
    card.addEventListener('click', function () {
      var id = card.getAttribute('data-suggest');
      if (!id) return;
      if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(id, null);
      if (window.switchDashboardView) window.switchDashboardView('plan-packs');
    });
  });

  /* Active-state buttons */
  var continueBtn = root.querySelector('#apContinue') || root.querySelector('#apToday');
  if (continueBtn) continueBtn.addEventListener('click', continueActivePlan);
  /* Both #apContinue (hero) and #apToday (today card) trigger the same flow */
  var todayBtn = root.querySelector('#apToday');
  if (todayBtn && todayBtn !== continueBtn) todayBtn.addEventListener('click', continueActivePlan);

  /* Stage 32-B: daily-loop shortcut inside the Today's Focus card. Only
     rendered when there's a nextDay (active in-flight state); guard with
     querySelector so plan-complete / in-development states no-op. */
  var logTodayBtn = root.querySelector('#activePlanLogTodayBtn');
  if (logTodayBtn) logTodayBtn.addEventListener('click', function () {
    if (window.switchDashboardView) {
      window.switchDashboardView('daily');
    } else if (window.showToast) {
      window.showToast('Daily Log is unavailable right now.', 'info', 1800);
    }
  });

  var openDetail = root.querySelector('#apOpenDetail');
  if (openDetail) openDetail.addEventListener('click', function () {
    var pack = getActivePack();
    if (!pack) return;
    window._ppDetailTab = 'overview';
    if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pack.id, null);
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });

  var openNotes = root.querySelector('#apOpenNotes');
  if (openNotes) openNotes.addEventListener('click', function () {
    var pack = getActivePack();
    if (!pack) return;
    window._ppDetailTab = 'notes';
    if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(pack.id, null);
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });

  /* Connected world chips - switch to Graph View and focus the world */
  Array.prototype.forEach.call(root.querySelectorAll('[data-world]'), function (chip) {
    chip.addEventListener('click', function () {
      var wid = chip.getAttribute('data-world');
      if (window.switchDashboardView) window.switchDashboardView('graph');
      if (wid && window.EE_GRAPH_API && window.EE_GRAPH_API.focusWorld) {
        setTimeout(function () { window.EE_GRAPH_API.focusWorld(wid); }, 60);
      }
    });
  });

  /* Stage 9: complete-state buttons */
  var viewCer = root.querySelector('#apViewCeremony');
  if (viewCer) viewCer.addEventListener('click', function () {
    var pack = getActivePack();
    if (pack && window.showPackCompletionModal) window.showPackCompletionModal(pack.id);
  });
  var chooseNext = root.querySelector('#apChooseNext');
  if (chooseNext) chooseNext.addEventListener('click', function () {
    var pack = getActivePack();
    var nextRef = pack ? getSuggestedNextPack(pack.id) : null;
    if (nextRef) {
      if (window.EE_PACK_NAV) window.EE_PACK_NAV.setPackTarget(nextRef.id, null);
      window._ppDetailTab = 'overview';
    }
    if (window.switchDashboardView) window.switchDashboardView('plan-packs');
  });
  var clearActive = root.querySelector('#apClearActive');
  if (clearActive) clearActive.addEventListener('click', function () {
    if (!window.confirm('Clear the active plan? Your progress and notes will stay.')) return;
    if (window.resetActivePlan) window.resetActivePlan({ alsoProgress: false });
  });

  /* Stage 8: checklist toggles inside Active Plan Today's Checklist - state
     is shared with the day view via getDayChecklistState/saveDayChecklistState. */
  function _apToggleChecklistEl(el) {
    var pid = el.getAttribute('data-cl-pack');
    var dn  = parseInt(el.getAttribute('data-cl-day'), 10);
    var idx = parseInt(el.getAttribute('data-cl-idx'), 10);
    if (!pid || isNaN(dn) || isNaN(idx)) return;
    if (typeof toggleDayChecklistItem === 'function') toggleDayChecklistItem(pid, dn, idx);
    /* Re-render Active Plan in place to reflect the new state */
    if (window.showWorkspaceView) window.showWorkspaceView('active-plan');
    /* Stage 13: refresh pinned reminder */
    if (typeof window.updateDailyReminderBanner === 'function') window.updateDailyReminderBanner();
  }
  Array.prototype.forEach.call(root.querySelectorAll('.ap-chk[data-cl-pack]'), function (item) {
    item.addEventListener('click', function () { _apToggleChecklistEl(item); });
    item.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); _apToggleChecklistEl(item); }
    });
  });

  /* Reset Plan */
  var resetBtn = root.querySelector('#apReset');
  if (resetBtn) resetBtn.addEventListener('click', function () {
    var msg = 'Reset this active plan? This clears the active plan selection.\n\n'
            + 'OK = Reset active plan only (your saved progress stays).\n'
            + 'Cancel = Keep everything.';
    if (!window.confirm(msg)) return;
    resetActivePlan({ alsoProgress: false });
  });
}

/* Expose so other parts of the app can use the active-plan API */
if (typeof window !== 'undefined') {
  window.getActivePackId   = getActivePackId;
  window.setActivePack     = setActivePack;
  window.clearActivePack   = clearActivePack;
  window.getActivePack     = getActivePack;
  window.continueActivePlan = continueActivePlan;
  window.resetActivePlan   = resetActivePlan;
}

function renderWorkspaceContent(viewId) {
  /* Stage 6: registry first for ALL views so Notes / Tasks / Daily / Templates
     / Calendar / Tags actually render their content (with Stage 6 empty-state
     wrappers). Fall back to a polished placeholder if no renderer is wired. */
  if (window.EE_WORKSPACE_RENDER && typeof window.EE_WORKSPACE_RENDER[viewId] === 'function') {
    try { return window.EE_WORKSPACE_RENDER[viewId](); }
    catch (e) { /* fall through to placeholder on render error */ }
  }
  var meta = WS_META[viewId] || {};
  return wsPlaceholder(
    { notes: '📝', daily: '📅', tasks: '✓', templates: '⊞', dataview: '⋮⋮', calendar: '◻', tags: '#' }[viewId] || '◈',
    meta.title || viewId,
    meta.subtitle || 'This section will populate as you use the dashboard.'
  );
}

function wsPlaceholder(icon, title, sub) {
  return '<div class="ws-placeholder">'
    + '<div class="ws-placeholder-icon">' + icon + '</div>'
    + '<div class="ws-placeholder-title">' + title + '</div>'
    + '<div class="ws-placeholder-sub">' + sub + '</div>'
    + '</div>';
}

/* ════════════════════════════════════════════════════════════════
   STAGE 6 - Polish: transitions, shortcuts, empty states, persistence
   ════════════════════════════════════════════════════════════════ */

var _eePrefersReducedMotion = (typeof window !== 'undefined' && window.matchMedia)
  ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

function _eeEsc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

/* ── Skeleton helper - returns a small shimmer card ── */
function eeSkeletonHTML(opts) {
  opts = opts || {};
  var lines = opts.lines || 3;
  var html = '<div class="skeleton skeleton-card">';
  for (var i = 0; i < lines; i++) {
    var widthCls = (i === lines - 1) ? ' skeleton-line-short' : '';
    html += '<div class="skeleton-line' + widthCls + '"></div>';
  }
  return html + '</div>';
}

/* ── Premium empty-state card ── */
function eeEmptyCard(opts) {
  opts = opts || {};
  var actionsHtml = '';
  if (opts.actions && opts.actions.length) {
    actionsHtml = '<div class="ws-empty-actions">'
      + opts.actions.map(function (a) {
          var primary = a.primary ? ' ws-empty-cta-primary' : '';
          return '<button class="ws-empty-cta' + primary + '" data-ws-action="' + _eeEsc(a.key || '') + '">' + _eeEsc(a.label) + '</button>';
        }).join('')
      + '</div>';
  }
  return '<div class="ws-empty">'
    + '<div class="ws-empty-icon">' + _eeEsc(opts.icon || '◈') + '</div>'
    + '<div class="ws-empty-title">' + _eeEsc(opts.title || '') + '</div>'
    + (opts.subtitle ? '<div class="ws-empty-sub">' + _eeEsc(opts.subtitle) + '</div>' : '')
    + actionsHtml
    + '</div>';
}

/* Bind Stage 6 empty-action buttons - call a per-view router */
function _eeBindEmptyActions(handler) {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  Array.prototype.forEach.call(root.querySelectorAll('[data-ws-action]'), function (btn) {
    btn.addEventListener('click', function () { handler(btn.getAttribute('data-ws-action'), btn); });
  });
}

/* ── Workspace empty-state wrappers ── */
function eeNotesIsEmpty()    { try { return !(localStorage.getItem('ee_notes') || '').trim(); } catch (e) { return true; } }
function eeTasksIsEmpty()    { try { return (JSON.parse(localStorage.getItem('ee_tasks') || '[]') || []).length === 0; } catch (e) { return true; } }
function eeDailyIsEmpty()    {
  var d = new Date();
  var key = 'ee_daily_' + d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
  try { return !(localStorage.getItem(key) || '').trim(); } catch (e) { return true; }
}

function renderNotesEmpty() {
  return eeEmptyCard({
    icon: '📝',
    title: 'No Notes Yet',
    subtitle: 'Capture thoughts, lessons, and ideas connected to your worlds and plans.',
    actions: [
      { key: 'create-note', label: 'Create Note', primary: true },
      { key: 'open-packs',  label: 'Open Plan Packs' }
    ]
  });
}
function renderDailyEmpty() {
  var today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
  return '<div class="ws-empty ws-empty-form">'
    + '<div class="ws-empty-icon">📅</div>'
    + '<div class="ws-empty-title">Start Today\'s Log</div>'
    + '<div class="ws-empty-sub">' + _eeEsc(today) + '</div>'
    + '<div class="ws-form-grid">'
    +   '<label class="ws-form-row"><span class="ws-form-lbl">Today\'s Focus</span><input class="ws-form-input" id="eeDailyFocus" type="text" placeholder="What is the one thing today is about?"></label>'
    +   '<label class="ws-form-row"><span class="ws-form-lbl">Win</span><input class="ws-form-input" id="eeDailyWin" type="text" placeholder="What went well?"></label>'
    +   '<label class="ws-form-row"><span class="ws-form-lbl">Lesson</span><input class="ws-form-input" id="eeDailyLesson" type="text" placeholder="What did you learn?"></label>'
    +   '<label class="ws-form-row"><span class="ws-form-lbl">Next Step</span><input class="ws-form-input" id="eeDailyNext" type="text" placeholder="What is the very next move?"></label>'
    + '</div>'
    + '<div class="ws-empty-actions"><button class="ws-empty-cta ws-empty-cta-primary" data-ws-action="save-daily">Save Daily Log</button></div>'
    + '</div>';
}
function renderTasksEmpty() {
  return eeEmptyCard({
    icon: '✓',
    title: 'No Tasks Yet',
    subtitle: 'Tasks from Plan Packs and templates will appear here.',
    actions: [
      { key: 'add-task',         label: 'Add Task', primary: true },
      { key: 'open-active-plan', label: 'Open Active Plan' }
    ]
  });
}
function renderTemplatesEmpty() {
  return eeEmptyCard({
    icon: '⊞',
    title: 'Use a Template',
    subtitle: 'Create notes, reviews, trackers, and planning pages faster.',
    actions: [ { key: 'open-packs', label: 'Open Plan Packs', primary: true } ]
  });
}
function renderCalendarEmpty() {
  return eeEmptyCard({
    icon: '◻',
    title: 'No Scheduled Blocks Yet',
    subtitle: 'Plan Pack schedules and milestones will appear here.',
    actions: [ { key: 'open-packs', label: 'Browse Plan Packs', primary: true } ]
  });
}
function renderTagsEmpty() {
  return eeEmptyCard({
    icon: '#',
    title: 'No Tags Yet',
    subtitle: 'Tags help organize worlds, notes, tasks, and plans.',
    actions: [ { key: 'open-packs', label: 'Open Plan Packs', primary: true } ]
  });
}

function _eeRouteEmptyAction(action) {
  if (action === 'open-packs')        { if (window.switchDashboardView) window.switchDashboardView('plan-packs'); return; }
  if (action === 'open-active-plan')  { if (window.switchDashboardView) window.switchDashboardView('active-plan'); return; }
  if (action === 'create-note')       {
    /* Drop a starter note so the workspace flips into the real editor on next render */
    try { localStorage.setItem('ee_notes', '# New Note\n\n'); } catch (e) {}
    if (window.refreshCurrentView) window.refreshCurrentView();
    return;
  }
  if (action === 'add-task') {
    try {
      var t = JSON.parse(localStorage.getItem('ee_tasks') || '[]');
      t.push({ text: 'New task', done: false });
      localStorage.setItem('ee_tasks', JSON.stringify(t));
    } catch (e) {}
    if (window.refreshCurrentView) window.refreshCurrentView();
    return;
  }
  if (action === 'save-daily') {
    var parts = [
      "Focus: "    + (document.getElementById('eeDailyFocus')  ? document.getElementById('eeDailyFocus').value  : ''),
      "Win: "      + (document.getElementById('eeDailyWin')    ? document.getElementById('eeDailyWin').value    : ''),
      "Lesson: "   + (document.getElementById('eeDailyLesson') ? document.getElementById('eeDailyLesson').value : ''),
      "Next Step: "+ (document.getElementById('eeDailyNext')   ? document.getElementById('eeDailyNext').value   : '')
    ].join('\n');
    var d = new Date();
    var key = 'ee_daily_' + d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
    try { localStorage.setItem(key, parts); } catch (e) {}
    if (window.showToast) window.showToast('Daily log saved.', 'success', 1800);
    if (window.refreshCurrentView) window.refreshCurrentView();
  }
}

/* Install Stage 6 wrappers AFTER the closure has registered its renderers.
   Called once after init from initDashboard. */
function installStage6WorkspaceWrappers() {
  /* Stage 20: wrap-on-wrap would compound if called twice. Guard. */
  if (window.__eeStage6WrappersInstalled) return;
  window.__eeStage6WrappersInstalled = true;
  if (!window.EE_WORKSPACE_RENDER) window.EE_WORKSPACE_RENDER = {};
  if (!window.EE_WORKSPACE_EVENTS) window.EE_WORKSPACE_EVENTS = {};

  function wrapRender(viewId, isEmptyFn, emptyRenderer) {
    var orig = window.EE_WORKSPACE_RENDER[viewId];
    window.EE_WORKSPACE_RENDER[viewId] = function () {
      if (isEmptyFn()) return emptyRenderer();
      return (typeof orig === 'function') ? orig() : wsPlaceholder('◈', viewId, '');
    };
  }
  function wrapEvents(viewId, extra) {
    var orig = window.EE_WORKSPACE_EVENTS[viewId];
    window.EE_WORKSPACE_EVENTS[viewId] = function () {
      if (typeof orig === 'function') { try { orig(); } catch (e) {} }
      if (typeof extra === 'function') { try { extra(); } catch (e) {} }
    };
  }

  wrapRender('notes',     eeNotesIsEmpty, renderNotesEmpty);
  wrapRender('tasks',     eeTasksIsEmpty, renderTasksEmpty);
  wrapRender('daily',     eeDailyIsEmpty, renderDailyEmpty);
  wrapRender('templates', function () { return false; }, renderTemplatesEmpty); /* templates fallback unused unless renderer fails */

  /* Provide renderers for views that previously had no workspace render */
  if (!window.EE_WORKSPACE_RENDER['calendar']) window.EE_WORKSPACE_RENDER['calendar'] = renderCalendarEmpty;
  if (!window.EE_WORKSPACE_RENDER['tags'])     window.EE_WORKSPACE_RENDER['tags']     = renderTagsEmpty;

  /* Empty-action button binder runs after any of these render */
  var binder = function () { _eeBindEmptyActions(_eeRouteEmptyAction); };
  wrapEvents('notes',     binder);
  wrapEvents('tasks',     binder);
  wrapEvents('daily',     binder);
  wrapEvents('templates', binder);
  window.EE_WORKSPACE_EVENTS['calendar'] = binder;
  window.EE_WORKSPACE_EVENTS['tags']     = binder;
}

/* ── View transitions (lightweight fade + tiny upward slide) ── */
function eeTransitionWorkspace(direction, cb) {
  if (_eePrefersReducedMotion) { if (typeof cb === 'function') cb(); return; }
  var ws = document.getElementById('dashboardWorkspace');
  if (!ws) { if (typeof cb === 'function') cb(); return; }
  ws.classList.add('workspace-transitioning');
  if (direction === 'out') {
    ws.classList.add('view-leaving');
    setTimeout(function () {
      ws.classList.remove('view-leaving');
      if (typeof cb === 'function') cb();
    }, 120);
    return;
  }
  /* "in" - apply entering class on next frame so animation runs */
  ws.classList.add('view-entering');
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      ws.classList.remove('view-entering');
      ws.classList.remove('workspace-transitioning');
      if (typeof cb === 'function') cb();
    });
  });
}

/* ── UI state persistence ── */
function eeSaveUiState(partial) {
  try {
    var s = JSON.parse(localStorage.getItem('ethos_ui_state') || '{}');
    for (var k in partial) if (Object.prototype.hasOwnProperty.call(partial, k)) s[k] = partial[k];
    localStorage.setItem('ethos_ui_state', JSON.stringify(s));
  } catch (e) {}
  /* Mirror individual keys per spec */
  try {
    if (partial.currentView    != null) localStorage.setItem('ethos_ui_current_view',    String(partial.currentView));
    if (partial.packFilter     != null) localStorage.setItem('ethos_ui_pack_filter',     String(partial.packFilter));
    if (partial.packSearch     != null) localStorage.setItem('ethos_ui_pack_search',     String(partial.packSearch));
    if (partial.activePackTab  != null) localStorage.setItem('ethos_ui_active_pack_tab', String(partial.activePackTab));
  } catch (e) {}
}
function eeLoadUiState() {
  var s = {};
  try { s = JSON.parse(localStorage.getItem('ethos_ui_state') || '{}'); } catch (e) {}
  /* Fall back to individual keys if combined blob is missing */
  try {
    if (s.currentView == null)    s.currentView    = localStorage.getItem('ethos_ui_current_view');
    if (s.packFilter == null)     s.packFilter     = localStorage.getItem('ethos_ui_pack_filter');
    if (s.packSearch == null)     s.packSearch     = localStorage.getItem('ethos_ui_pack_search');
    if (s.activePackTab == null)  s.activePackTab  = localStorage.getItem('ethos_ui_active_pack_tab');
  } catch (e) {}
  return s;
}

/* Restore UI state safely on init - called at the end of initDashboard. */
function eeRestoreUiState() {
  var allowed = { graph:1, 'plan-packs':1, 'active-plan':1, notes:1, daily:1, tasks:1, templates:1, dataview:1, calendar:1, tags:1, settings:1 };
  var state = eeLoadUiState();
  /* Pack market filter / search */
  if (state.packFilter)    window._ppMarketFilter = state.packFilter;
  if (state.packSearch)    window._ppMarketSearch = state.packSearch;
  if (state.activePackTab) window._ppDetailTab    = state.activePackTab;
  /* View restore */
  var target = (state.currentView && allowed[state.currentView]) ? state.currentView : 'graph';
  try {
    if (window.switchDashboardView) window.switchDashboardView(target);
  } catch (e) {
    if (window.switchDashboardView) window.switchDashboardView('graph');
  }
}

/* ── Keyboard shortcuts ── */
function _eeIsTypingTarget(t) {
  if (!t) return false;
  var tag = (t.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
  if (t.isContentEditable) return true;
  return false;
}
function eeShowShortcutHelp() {
  var modal = document.getElementById('eeShortcutModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'eeShortcutModal';
    modal.className = 'ee-plan-modal';
    modal.innerHTML = ''
      + '<div class="ee-plan-backdrop" data-eeclose="1"></div>'
      + '<div class="ee-plan-dialog ee-shortcut-dialog" role="dialog" aria-modal="true" aria-label="Keyboard shortcuts">'
      +   '<button class="ee-plan-x" id="eeShortcutClose" aria-label="Close shortcuts">&times;</button>'
      +   '<div class="ee-plan-head">'
      +     '<div class="ee-plan-kicker">SHORTCUTS</div>'
      +     '<h2 class="ee-plan-title">Keyboard Shortcuts</h2>'
      +   '</div>'
      +   '<table class="ee-shortcut-tbl"><tbody>'
      +     '<tr><td><kbd>Cmd</kbd>/<kbd>Ctrl</kbd> + <kbd>K</kbd></td><td>Focus search</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>G</kbd></td><td>Graph View</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>P</kbd></td><td>Plan Packs</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>A</kbd></td><td>My Active Plan</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>N</kbd></td><td>Notes</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>T</kbd></td><td>Tasks</td></tr>'
      +     '<tr><td><kbd>G</kbd> <kbd>S</kbd></td><td>Settings</td></tr>'
      +     '<tr><td><kbd>?</kbd></td><td>Show this help</td></tr>'
      +     '<tr><td><kbd>Esc</kbd></td><td>Close modal / panel</td></tr>'
      +   '</tbody></table>'
      + '</div>';
    document.body.appendChild(modal);
    modal.addEventListener('click', function (e) {
      if (e.target && e.target.getAttribute && e.target.getAttribute('data-eeclose') === '1') eeHideShortcutHelp();
    });
    var x = modal.querySelector('#eeShortcutClose');
    if (x) x.addEventListener('click', eeHideShortcutHelp);
  }
  /* Stage 29: focus restore pattern. */
  _eeStashFocusOpener('shortcut', modal);
  modal.classList.add('ee-plan-modal-open');
  document.body.style.overflow = 'hidden';
  /* Stage 29: send keyboard focus into the dialog so Esc/Tab/Enter act on it
     instead of background DOM. Close button is the safest first stop because
     it's always present and the dialog is read-only otherwise. */
  setTimeout(function () {
    var btn = document.getElementById('eeShortcutClose');
    if (btn && typeof btn.focus === 'function') {
      try { btn.focus(); } catch (e) {}
    }
  }, 30);
}
function eeHideShortcutHelp() {
  var modal = document.getElementById('eeShortcutModal');
  if (!modal) return;
  modal.classList.remove('ee-plan-modal-open');
  document.body.style.overflow = '';
  _eeRestoreFocusOpener('shortcut');
}

function installStage6Shortcuts() {
  /* Stage 20: each call attaches a fresh document keydown listener. Guard. */
  if (window.__eeStage6ShortcutsInstalled) return;
  window.__eeStage6ShortcutsInstalled = true;
  var gPending = false;
  var gTimer   = null;
  function clearG() { gPending = false; clearTimeout(gTimer); }

  document.addEventListener('keydown', function (e) {
    /* Cmd/Ctrl + K - focus search even from inputs */
    if ((e.metaKey || e.ctrlKey) && (e.key === 'k' || e.key === 'K')) {
      e.preventDefault();
      var s = document.getElementById('tbSrchInput');
      if (s) { s.focus(); s.select(); }
      return;
    }
    if (_eeIsTypingTarget(e.target)) return;
    /* ? help - shift+/ on most keyboards */
    if (e.key === '?' || (e.shiftKey && e.key === '/')) {
      e.preventDefault();
      eeShowShortcutHelp();
      return;
    }
    /* Esc closes shortcut modal (the global Esc handler covers graph return) */
    if (e.key === 'Escape') {
      var m = document.getElementById('eeShortcutModal');
      if (m && m.classList.contains('ee-plan-modal-open')) { eeHideShortcutHelp(); return; }
    }
    /* g-prefix sequences */
    if (!gPending && (e.key === 'g' || e.key === 'G')) {
      gPending = true;
      gTimer = setTimeout(clearG, 1200);
      return;
    }
    if (gPending) {
      var k = (e.key || '').toLowerCase();
      var map = { g: 'graph', p: 'plan-packs', a: 'active-plan', n: 'notes', t: 'tasks', s: 'settings' };
      if (map[k]) {
        e.preventDefault();
        if (window.switchDashboardView) window.switchDashboardView(map[k]);
      }
      clearG();
    }
  });
}

/* ── Mobile responsive default ── */
function eeApplyMobileDefaults() {
  if (typeof window === 'undefined' || !window.matchMedia) return;
  var narrow = window.matchMedia('(max-width: 900px)').matches;
  if (!narrow) return;
  var alreadySet = false;
  try { alreadySet = localStorage.getItem('ethos_sidebar_collapsed') != null; } catch (e) {}
  if (!alreadySet && typeof setSidebarCollapsed === 'function') setSidebarCollapsed(true);
}

/* Mobile slide-over toggle (hamburger) */
function eeToggleMobileSidebar() {
  var root = document.getElementById('dashRoot');
  if (!root) return;
  var open = root.classList.toggle('sidebar-mobile-open');
  var bd = document.getElementById('eeMobileBackdrop');
  if (bd) bd.classList.toggle('ee-show', open);
  /* Stage 28: keep hamburger aria-expanded + label in sync with state. */
  var ham = document.getElementById('eeMobileHamburger');
  if (ham) {
    ham.setAttribute('aria-expanded', open ? 'true' : 'false');
    ham.setAttribute('aria-label', open ? 'Close sidebar' : 'Open sidebar');
  }
}
function eeInstallMobileHamburger() {
  if (document.getElementById('eeMobileHamburger')) return;
  var topBar = document.getElementById('dashTopBar');
  if (!topBar) return;
  var btn = document.createElement('button');
  btn.id = 'eeMobileHamburger';
  btn.className = 'ee-hamburger';
  btn.type = 'button';
  /* Stage 28: more accurate label + expanded state for screen readers. */
  btn.setAttribute('aria-label', 'Open sidebar');
  btn.setAttribute('aria-expanded', 'false');
  btn.setAttribute('aria-controls', 'dashSidebar');
  btn.innerHTML = '<span></span><span></span><span></span>';
  btn.addEventListener('click', eeToggleMobileSidebar);
  topBar.insertBefore(btn, topBar.firstChild);

  /* Backdrop to close the slide-over */
  var bd = document.createElement('div');
  bd.id = 'eeMobileBackdrop';
  bd.className = 'ee-mobile-backdrop';
  /* Stage 28: not a focusable button visually, but expose intent for AT. */
  bd.setAttribute('role', 'button');
  bd.setAttribute('aria-label', 'Close sidebar');
  bd.setAttribute('tabindex', '-1');
  bd.addEventListener('click', eeToggleMobileSidebar);
  document.body.appendChild(bd);
}

/* ════════════════════════════════════════════════════════════════
   STAGE 2 — Membership / billing system + free-user upgrade modal
   ════════════════════════════════════════════════════════════════
   Plan levels: 'free' · 'empire-core' · 'empire-pro' · 'dev'
   Read order: dev token → localStorage 'ethos_plan_level' → infer
   from existing window.EE_IS_PRO (real Stripe state) → 'free'.
   This means real Pro subscribers are NOT downgraded to free when
   ethos_plan_level is unset, but testers can override at will. */

function getUserPlanLevel() {
  /* Stage 33-B-6: dev/mock self-grant flags only fire when
     EE_DEV_FLAGS_ALLOWED is true. In production the dev token literal in
     localStorage is silently ignored even if a user pastes it via DevTools;
     the function falls through to window.EE_USER_PLAN (the real
     Firestore-derived plan from Stage 33-B-5). */
  var devAllowed = typeof window !== 'undefined' && window.EE_DEV_FLAGS_ALLOWED === true;
  if (devAllowed) {
    try {
      if (localStorage.getItem('ee_dev_token') === 'EthosEmpire-DEV-X9K2-2026') return 'dev';
      var mock = localStorage.getItem('ethos_plan_level');
      if (mock === 'free' || mock === 'empire-core' || mock === 'empire-pro' || mock === 'dev') return mock;
    } catch (e) {}
  }
  /* Stage 33-B-5: read the already-normalized plan key set by the
     dashboard.html boot block. That value is derived from the Firestore
     `plan` field gated by subscriptionStatus (Stage 33-B-4 writes the
     field, eeNormalizePlanFromProfile gates it on active|trialing). No
     more inferring Pro from "any active subscription" - a $30 Core user
     resolves to 'empire-core' here, not 'empire-pro'. */
  if (typeof window !== 'undefined' && typeof window.EE_USER_PLAN === 'string') {
    var p = window.EE_USER_PLAN;
    if (p === 'free' || p === 'empire-core' || p === 'empire-pro' || p === 'dev') return p;
  }
  return 'free';
}

/* Stage 33-B-5: isEmpireCorePlan was previously "core OR pro OR dev" -
   a legacy "Pro implies Core access" shortcut. With the normalized plan
   key, isEmpireCorePlan now means strictly the $30 Core tier, matching
   isEmpireProPlan's strict semantics. No callers depended on the old
   broader meaning (grep: this helper had zero call sites). */
function isFreePlan()         { return getUserPlanLevel() === 'free'; }
function isEmpireCorePlan()   { return getUserPlanLevel() === 'empire-core'; }
function isEmpireProPlan()    { var l = getUserPlanLevel(); return l === 'empire-pro' || l === 'dev'; }
function canAccessPlanPacks() { return isEmpireProPlan(); }

function setMockPlanLevel(level) {
  try {
    if (level == null) localStorage.removeItem('ethos_plan_level');
    else localStorage.setItem('ethos_plan_level', String(level));
  } catch (e) {}
  refreshCurrentView();
  /* Refresh top bar — Plan Packs subtitle may change with plan */
  if (window.dashboardState && window.updateTopBarContext) {
    window.updateTopBarContext(window.dashboardState.currentView);
  }
}

/* ── Toast (Stage 2 minimal, Stage 6 variants + optional action)
   showToast(message)
   showToast(message, 'success' | 'error' | 'warning' | 'info')
   showToast(message, 'success', 3200)                       // legacy positional duration
   showToast(message, 'success', { duration: 3200, actionLabel: 'Undo', onAction: fn }) */
function showToast(message, variant, options) {
  var host = document.getElementById('eeToastHost');
  if (!host) {
    host = document.createElement('div');
    host.id = 'eeToastHost';
    host.className = 'ee-toast-host';
    /* Stage 29: announce transient toast messages to screen readers. polite
       so they queue behind any in-progress announcement and never interrupt.
       aria-atomic stays off because each toast is its own self-contained
       child node - we want each new toast read in full, not the whole host
       re-read every time a toast is added. The Daily Log status pill uses
       its own role=status live region on a separate element (#dailylogSaveStatus,
       Stage 28) so there is no double-announce: autosave updates the pill,
       not a toast (Stage 26 explicitly does not toast autosaves). */
    host.setAttribute('aria-live', 'polite');
    host.setAttribute('role', 'status');
    document.body.appendChild(host);
  }
  var opts = {};
  if (typeof options === 'number') opts.duration = options;
  else if (options && typeof options === 'object') opts = options;

  var safeVariant = ({ success:1, error:1, warning:1, info:1 })[variant] ? variant : 'info';
  var el = document.createElement('div');
  el.className = 'ee-toast ee-toast-' + safeVariant;
  if (opts.actionLabel) el.classList.add('ee-toast-with-action');

  var iconCh = ({ success:'✓', error:'⚠', warning:'⚠', info:'ⓘ' })[safeVariant] || 'ⓘ';
  var iconEl = document.createElement('span');
  iconEl.className = 'ee-toast-ico';
  iconEl.textContent = iconCh;
  el.appendChild(iconEl);

  var msgEl = document.createElement('span');
  msgEl.className = 'ee-toast-msg';
  msgEl.textContent = String(message == null ? '' : message);
  el.appendChild(msgEl);

  if (opts.actionLabel && typeof opts.onAction === 'function') {
    var actionBtn = document.createElement('button');
    actionBtn.className = 'ee-toast-action';
    actionBtn.type = 'button';
    actionBtn.textContent = String(opts.actionLabel);
    actionBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      try { opts.onAction(); } catch (err) {}
      dismiss();
    });
    el.appendChild(actionBtn);
  }

  host.appendChild(el);
  requestAnimationFrame(function () { el.classList.add('ee-toast-show'); });
  var ms = (typeof opts.duration === 'number' && opts.duration > 0) ? opts.duration : 3200;
  var dismissed = false;
  function dismiss() {
    if (dismissed) return;
    dismissed = true;
    el.classList.remove('ee-toast-show');
    setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 240);
  }
  var timer = setTimeout(dismiss, ms);
  el.addEventListener('click', function () { clearTimeout(timer); dismiss(); });
}

/* ── Checkout + portal placeholders (defer to existing safe fns if present) ── */
function startPlanCheckout(planId) {
  if (typeof window.EE_START_CHECKOUT === 'function') {
    window.EE_START_CHECKOUT(planId);
    return;
  }
  showToast('Checkout will connect here for ' + planId + ' (placeholder)', 'info');
}

function openBillingPortal(btn) {
  if (typeof window.EE_OPEN_PORTAL === 'function') {
    window.EE_OPEN_PORTAL(btn);
    return;
  }
  showToast('Billing portal will connect here (placeholder)', 'info');
}

/* ── Plan comparison modal (Stage 2 — distinct from existing #upgradeModal) ── */
