function showPlanComparisonModal() {
  var modal = _ensurePlanModalShell();
  /* Stage 29: focus restore pattern. */
  _eeStashFocusOpener('planComparison', modal);
  modal.setAttribute('aria-hidden', 'false');
  modal.classList.add('ee-plan-modal-open');
  document.body.style.overflow = 'hidden';
}

function closePlanComparisonModal() {
  var modal = document.getElementById('eePlanModal');
  if (!modal) return;
  modal.setAttribute('aria-hidden', 'true');
  modal.classList.remove('ee-plan-modal-open');
  document.body.style.overflow = '';
  _eeRestoreFocusOpener('planComparison');
}

function _todayKeyYMD() {
  var d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

function maybeShowFirstLoadUpgradeModal() {
  if (!isFreePlan()) return;
  var key = 'ethos_upgrade_popup_seen_' + _todayKeyYMD();
  try {
    if (localStorage.getItem(key) === '1') return;
    localStorage.setItem(key, '1');
  } catch (e) {}
  /* Defer slightly so the dashboard paints first */
  setTimeout(showPlanComparisonModal, 600);
}

/* ── Locked Plan Packs overlay (renders inside renderPlanPacks for non-Pro) ── */
function renderLockedPlanPacksScreen(level) {
  var isFree = (level === 'free');
  var headline = isFree
    ? 'Choose a plan to unlock your Empire dashboard.'
    : 'Plan Packs are included with Empire Pro. Upgrade to unlock all 50 guided workflows.';
  var actions = isFree
    ? '<button class="ee-locked-cta" data-plan="empire-core">Start $30 — Empire Core</button>'
      + '<button class="ee-locked-cta ee-locked-cta-pro" data-plan="empire-pro">Start $40 — Empire Pro</button>'
    : '<button class="ee-locked-cta ee-locked-cta-pro" data-plan="empire-pro">Upgrade to Empire Pro</button>'
      + '<button class="ee-locked-cta" id="eeLockedCompare">Compare Plans</button>';

  /* Preview row — first 3 PLAN_PACKS_DATA entries as locked teasers */
  var previewCards = '';
  try {
    if (typeof PLAN_PACKS_DATA !== 'undefined' && PLAN_PACKS_DATA && PLAN_PACKS_DATA.length) {
      previewCards = PLAN_PACKS_DATA.slice(0, 3).map(function (p) {
        return '<div class="ee-locked-prev">'
          + '<div class="ee-locked-prev-icon">' + (p.icon || '⚡') + '</div>'
          + '<div class="ee-locked-prev-title">' + String(p.title || '').replace(/[<>]/g,'') + '</div>'
          + '<div class="ee-locked-prev-meta">' + String(p.category || '').replace(/[<>]/g,'') + ' · ' + (p.totalDays || '?') + ' days</div>'
          + '<div class="ee-locked-prev-lock">🔒</div>'
          + '</div>';
      }).join('');
    }
  } catch (e) {}

  return '<div class="ee-locked-wrap">'
    +   '<div class="ee-locked-card">'
    +     '<div class="ee-locked-kicker">' + (isFree ? 'EMPIRE' : 'EMPIRE PRO') + '</div>'
    +     '<div class="ee-locked-title">Plan Packs</div>'
    +     '<div class="ee-locked-headline">' + headline + '</div>'
    +     '<div class="ee-locked-actions">' + actions + '</div>'
    +   '</div>'
    +   (previewCards ? '<div class="ee-locked-prev-row">' + previewCards + '</div>' : '')
    + '</div>';
}

function attachLockedPlanPacksEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  Array.prototype.forEach.call(root.querySelectorAll('[data-plan]'), function (btn) {
    btn.addEventListener('click', function () { startPlanCheckout(btn.getAttribute('data-plan')); });
  });
  var cmp = root.querySelector('#eeLockedCompare');
  if (cmp) cmp.addEventListener('click', showPlanComparisonModal);
}

/* ── Settings tabs (General · Appearance · Billing · Data) ── */
function _planLabel(level) {
  return ({
    'free':        'Free Preview',
    'empire-core': 'Empire Core — $30/month',
    'empire-pro':  'Empire Pro — $40/month',
    'dev':         'Developer (full access)'
  })[level] || 'Free Preview';
}

function renderSettingsTabbed() {
  var level   = getUserPlanLevel();
  var tab     = (window._eeSettingsTab) || 'general';

  /* General tab content — preserves existing IDs the legacy event handler binds to */
  var generalHtml = ''
    + '<div class="dp-label">Graph</div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Auto Spin</div>'
    +   '<div class="dp-setting-sub">Rotate the sphere automatically</div></div>'
    +   '<button class="dp-toggle on" id="dpToggleSpin"></button></div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Node Labels</div>'
    +   '<div class="dp-setting-sub">Show world names below nodes</div></div>'
    +   '<button class="dp-toggle on" id="dpToggleLabels"></button></div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Connection Lines</div>'
    +   '<div class="dp-setting-sub">Show wave energy lines</div></div>'
    +   '<button class="dp-toggle on" id="dpToggleLines"></button></div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Reset View</div>'
    +   '<div class="dp-setting-sub">Center and restore default zoom</div></div>'
    +   '<button class="dp-setting-btn" id="dpBtnReset">Reset</button></div>'
    + '<div class="dp-label">Account</div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Sign Out</div></div>'
    +   '<button class="dp-setting-btn" id="dpBtnSignOut">Sign Out</button></div>';

  var appearanceHtml = ''
    + '<div class="dp-label">Appearance</div>'
    + '<div class="dp-setting-row"><div><div class="dp-setting-label">Sidebar</div>'
    +   '<div class="dp-setting-sub">Collapse the left menu to icons only</div></div>'
    +   '<button class="dp-setting-btn" id="eeAppearanceCollapse">Toggle Collapse</button></div>'
    + '<div class="ee-settings-note">More appearance options arrive in a future update.</div>';

  /* Billing actions per plan */
  var billingActions;
  if (level === 'free') {
    billingActions = ''
      + '<button class="ee-bill-cta" data-plan="empire-core">Upgrade to Empire Core</button>'
      + '<button class="ee-bill-cta ee-bill-cta-pro" data-plan="empire-pro">Upgrade to Empire Pro</button>';
  } else if (level === 'empire-core') {
    billingActions = ''
      + '<button class="ee-bill-cta ee-bill-cta-pro" data-plan="empire-pro">Upgrade to Empire Pro</button>'
      + '<button class="ee-bill-cta" id="eeBillManage">Manage Billing</button>'
      + '<button class="ee-bill-cta ee-bill-cta-danger" id="eeBillCancel">Cancel Plan</button>';
  } else if (level === 'empire-pro') {
    billingActions = ''
      + '<button class="ee-bill-cta" data-plan="empire-core">Downgrade to Empire Core</button>'
      + '<button class="ee-bill-cta" id="eeBillManage">Manage Billing</button>'
      + '<button class="ee-bill-cta ee-bill-cta-danger" id="eeBillCancel">Cancel Plan</button>';
  } else {
    billingActions = '<div class="ee-settings-note">Developer mode — billing actions are disabled.</div>';
  }

  /* Mock-tier switcher (only visible to dev token; lets you flip levels for testing)
     Stage 33-B-6: also gated behind EE_DEV_FLAGS_ALLOWED so production users
     never see the switcher even if the localStorage flag is somehow set. */
  var devSwitcher = '';
  var _devSwitcherAllowed = typeof window !== 'undefined' && window.EE_DEV_FLAGS_ALLOWED === true;
  if (_devSwitcherAllowed && (level === 'dev' || (function(){ try { return !!localStorage.getItem('ethos_plan_level'); } catch(e){ return false; } })())) {
    devSwitcher = ''
      + '<div class="ee-settings-note ee-settings-dev">'
      +   '<div class="ee-settings-dev-label">Test plan tier (local mock)</div>'
      +   '<div class="ee-settings-dev-row">'
      +     '<button class="ee-bill-cta" data-mock="free">Free</button>'
      +     '<button class="ee-bill-cta" data-mock="empire-core">Core</button>'
      +     '<button class="ee-bill-cta" data-mock="empire-pro">Pro</button>'
      +     '<button class="ee-bill-cta" data-mock="__clear">Use real</button>'
      +   '</div>'
      + '</div>';
  }

  var billingHtml = ''
    + '<div class="dp-label">Current Plan</div>'
    + '<div class="ee-bill-card">'
    +   '<div class="ee-bill-plan-name">' + _planLabel(level) + '</div>'
    +   '<div class="ee-bill-plan-status">' + (level === 'free' ? 'Preview access · no charge' : 'Status placeholder · renewal info from billing portal') + '</div>'
    + '</div>'
    + '<div class="dp-label">Actions</div>'
    + '<div class="ee-bill-actions">' + billingActions + '</div>'
    + devSwitcher;

  var dataHtml = ''
    + '<div class="dp-label">Local Data</div>'
    + '<div class="ee-settings-note">Notes, tasks, daily logs, and pack progress are stored in your browser. Clearing data resets only this device.</div>'
    + '<div class="ee-bill-actions">'
    +   '<button class="ee-bill-cta ee-bill-cta-danger" id="eeDataReset">Clear local dashboard data</button>'
    + '</div>';

  function tabBtn(id, label) {
    return '<button class="ee-stab' + (tab === id ? ' ee-stab-on' : '') + '" data-stab="' + id + '">' + label + '</button>';
  }

  return ''
    + '<div class="ee-settings-tabs" role="tablist">'
    +   tabBtn('general',    'General')
    +   tabBtn('appearance', 'Appearance')
    +   tabBtn('billing',    'Billing')
    +   tabBtn('data',       'Data')
    + '</div>'
    + '<div class="ee-stab-panel">'
    + (tab === 'general'    ? generalHtml    :
       tab === 'appearance' ? appearanceHtml :
       tab === 'billing'    ? billingHtml    :
       dataHtml)
    + '</div>';
}

function attachSettingsTabsEvents() {
  var root = document.getElementById('workspaceContent');
  if (!root) return;
  Array.prototype.forEach.call(root.querySelectorAll('.ee-stab'), function (btn) {
    btn.addEventListener('click', function () {
      window._eeSettingsTab = btn.getAttribute('data-stab') || 'general';
      refreshCurrentView();
    });
  });

  /* Billing buttons */
  Array.prototype.forEach.call(root.querySelectorAll('.ee-bill-actions [data-plan]'), function (btn) {
    btn.addEventListener('click', function () { startPlanCheckout(btn.getAttribute('data-plan')); });
  });
  var manage = root.querySelector('#eeBillManage');
  if (manage) manage.addEventListener('click', function () { openBillingPortal(manage); });
  var cancel = root.querySelector('#eeBillCancel');
  if (cancel) cancel.addEventListener('click', function () { openBillingPortal(cancel); });

  /* Appearance: toggle sidebar collapse */
  var collapseBtn = root.querySelector('#eeAppearanceCollapse');
  if (collapseBtn && window.toggleSidebarCollapsed) {
    collapseBtn.addEventListener('click', window.toggleSidebarCollapsed);
  }

  /* Mock tier switcher */
  Array.prototype.forEach.call(root.querySelectorAll('[data-mock]'), function (btn) {
    btn.addEventListener('click', function () {
      var v = btn.getAttribute('data-mock');
      setMockPlanLevel(v === '__clear' ? null : v);
      showToast('Plan tier: ' + getUserPlanLevel(), 'info', 1800);
    });
  });

  /* Data clear */
  var reset = root.querySelector('#eeDataReset');
  if (reset) reset.addEventListener('click', function () {
    if (!confirm('Clear local dashboard data on this device? (Notes, tasks, daily logs, pack progress, UI prefs)')) return;
    var keys = ['ee_notes','ee_tasks','ee_pack_progress','ee_plan_pack_access','ethos_sidebar_collapsed','ethos_dashboard_view','ethos_active_pack'];
    try {
      keys.forEach(function (k) { localStorage.removeItem(k); });
      Object.keys(localStorage).filter(function (k) { return k.indexOf('ee_daily_') === 0 || k.indexOf('ethos_upgrade_popup_seen_') === 0; })
        .forEach(function (k) { localStorage.removeItem(k); });
    } catch (e) {}
    showToast('Local dashboard data cleared.', 'info');
  });

  /* General tab: re-bind legacy graph/account handlers (same IDs as legacy renderSettings) */
  var tab = window._eeSettingsTab || 'general';
  if (tab === 'general' && typeof window !== 'undefined') {
    var tSpin   = root.querySelector('#dpToggleSpin');
    var tLabels = root.querySelector('#dpToggleLabels');
    var tLines  = root.querySelector('#dpToggleLines');
    var btnReset   = root.querySelector('#dpBtnReset');
    var btnSignOut = root.querySelector('#dpBtnSignOut');
    if (tSpin)   tSpin.addEventListener('click', function () {
      tSpin.classList.toggle('on');
      if (window.EE_GRAPH_API) window.EE_GRAPH_API.setAutoSpin(tSpin.classList.contains('on'));
    });
    if (tLabels) tLabels.addEventListener('click', function () {
      tLabels.classList.toggle('on');
      if (window.EE_GRAPH_API) window.EE_GRAPH_API.setLabels(tLabels.classList.contains('on'));
    });
    if (tLines)  tLines.addEventListener('click', function () {
      tLines.classList.toggle('on');
      if (window.EE_GRAPH_API) window.EE_GRAPH_API.setLines(tLines.classList.contains('on'));
    });
    if (btnReset)   btnReset.addEventListener('click',   function () { if (window.EE_GRAPH_API) window.EE_GRAPH_API.resetView(); });
    if (btnSignOut) btnSignOut.addEventListener('click', function () { if (window.EE_SIGN_OUT) window.EE_SIGN_OUT(); });
  }
}

/* ── Refresh whichever workspace is currently visible ── */
function refreshCurrentView() {
  var view = (window.dashboardState && window.dashboardState.currentView) || 'graph';
  if (view === 'graph') return;
  if (window.showWorkspaceView) window.showWorkspaceView(view);
}

function showGraphView() {
  dashboardState.currentView = 'graph';
  var ws = document.getElementById('dashboardWorkspace');
  if (ws) { ws.classList.remove('ws-active'); ws.setAttribute('aria-hidden', 'true'); }
  updateWorkspaceSidebarState('graph');
  /* ensure old panel is closed */
  if (window.EE_PANEL_API) window.EE_PANEL_API.closePanel();
}

function showWorkspaceView(viewId) {
  dashboardState.currentView = viewId;
  var ws = document.getElementById('dashboardWorkspace');
  if (!ws) return;

  var meta = WS_META[viewId] || { kicker: 'WORKSPACE', title: viewId, subtitle: '' };
  var kicker   = document.getElementById('workspaceKicker');
  var titleEl  = document.getElementById('workspaceTitle');
  var subtitleEl = document.getElementById('workspaceSubtitle');
  if (kicker)    kicker.textContent   = meta.kicker;
  if (titleEl)   titleEl.textContent  = meta.title;
  if (subtitleEl) subtitleEl.textContent = meta.subtitle;

  var contentEl = document.getElementById('workspaceContent');
  if (contentEl) {
    contentEl.innerHTML = renderWorkspaceContent(viewId);
    contentEl.scrollTop = 0;
  }

  ws.setAttribute('aria-hidden', 'false');
  ws.classList.add('ws-active');
  updateWorkspaceSidebarState(viewId);
  /* Stage 34-D-HOTFIX-R3: ensure the workspace scroll guards are armed
     after the workspace becomes visible. The flag inside
     _protectScrollableSurface short-circuits if already bound. */
  if (typeof bindWorkspaceScrollGuards === 'function') bindWorkspaceScrollGuards();
  /* Stage 34-D-HOTFIX-R4: refresh the back button label so it reflects
     the new view's context (e.g. "Plan Packs" while in marketplace,
     "Pack Overview" once a pack is opened, previousView name when
     coming from a non-graph view). */
  if (typeof window._updateWorkspaceBackButton === 'function') window._updateWorkspaceBackButton();

  /* bind workspace-specific events */
  if (viewId === 'plan-packs' && typeof attachPackEvents === 'function') {
    attachPackEvents();
  }
  if (window.EE_WORKSPACE_EVENTS && window.EE_WORKSPACE_EVENTS[viewId]) {
    window.EE_WORKSPACE_EVENTS[viewId]();
  }
  /* close old slide-in panel */
  if (window.EE_PANEL_API) window.EE_PANEL_API.closePanel();
}

function closeWorkspaceView() {
  showGraphView();
}

function updateWorkspaceSidebarState(viewId) {
  Array.prototype.forEach.call(document.querySelectorAll('.sb-item'), function (item) {
    var v = item.getAttribute('data-view');
    var on = (v === viewId);
    item.classList.toggle('active', on);
    /* Stage 30.4 - aria-current=page makes the active item announced as
       "current page" by screen readers and is the conventional inspector
       signal for verifying nav state in DevTools. */
    if (on) item.setAttribute('aria-current', 'page');
    else item.removeAttribute('aria-current');
  });
}

function switchDashboardView(viewId, extraData) {
  /* Stage 27: if we are LEAVING the daily log view with unsaved typing, flush
     synchronously before the workspace re-mount tears down the editor DOM.
     Otherwise the pending debounce can't fire (DOM gone) and the values get
     lost. Same shape as openDailyLogDate's flush. */
  try {
    if (dashboardState.currentView === 'daily' && viewId !== 'daily' &&
        typeof _dailyLogDirty !== 'undefined' && _dailyLogDirty &&
        typeof autosaveDailyLogNow === 'function') {
      autosaveDailyLogNow();
    }
  } catch (e) {}
  /* Stage 31.2B-HOTFIX: if we are LEAVING graph view, wipe any open planet
     focus panel / connected-worlds panel / Pro upgrade card so they cannot
     leak over the new workspace. Graph render state is also cleared so a
     planet does not stay visually .is-selected behind the workspace. Does
     nothing if we are staying in or entering graph. */
  if (dashboardState.currentView === 'graph' && viewId !== 'graph') {
    _eeCleanupGraphOverlays();
  }
  /* Stage 34-D-HOTFIX-R4: track previousView before reassigning so the
     contextual workspace back button can return to where the user was.
     Self-transitions don't update previousView (avoids losing real
     history on incidental re-routes). */
  if (dashboardState.currentView && dashboardState.currentView !== viewId) {
    dashboardState.previousView = dashboardState.currentView;
  }
  dashboardState.currentView = viewId;

  updateWorkspaceSidebarState(viewId);
  updateTopBarContext(viewId, extraData);
  setDashboardBackgroundMode(viewId);

  /* Stage 6: lightweight transition wrapping the workspace mount */
  function mount() {
    if (viewId === 'graph') {
      closeWorkspaceView();
      setGraphInteractionEnabled(true);
      showGraphHudForGraphView();
    } else {
      showWorkspaceView(viewId);
      setGraphInteractionEnabled(false);
      hideGraphHudForWorkspace();
    }
    if (typeof eeTransitionWorkspace === 'function') eeTransitionWorkspace('in');
  }
  /* Stage 30.4 - DO NOT run the 'out' leg before mounting. That leg fades the
     workspace to opacity:0 for 120ms, which is exactly when the 3D globe behind
     it becomes visible and the user sees the planet flash. Mount immediately,
     fade-in only. Polish is unchanged from the user's perspective on a new
     workspace; only the unwanted graph leak goes away. */
  mount();

  saveDashboardUiState();
  /* Stage 6: persist current view + pack market filter/search + pack detail tab */
  if (typeof eeSaveUiState === 'function') eeSaveUiState({
    currentView:   viewId,
    packFilter:    window._ppMarketFilter || 'All',
    packSearch:    window._ppMarketSearch || '',
    activePackTab: window._ppDetailTab    || 'overview'
  });
  /* Stage 13: refresh pinned reminder banner on every view change */
  if (typeof updateDailyReminderBanner === 'function') updateDailyReminderBanner();

  /* Stage 6: auto-close mobile slide-over after picking a view */
  var root = document.getElementById('dashRoot');
  if (root && root.classList.contains('sidebar-mobile-open')) {
    root.classList.remove('sidebar-mobile-open');
    var bd = document.getElementById('eeMobileBackdrop');
    if (bd) bd.classList.remove('ee-show');
  }
}

function initWorkspaceSystem() {
  /* Stage 34-D-HOTFIX-R4 — contextual workspace back button.
     The button at the top-left of every workspace view used to hard-route
     to Graph View. Inside Plan Packs that meant a pack-detail back jumped
     past the marketplace and dropped the user on the empty graph. New
     behavior:
       1. If a pack-internal back exists in the DOM (#ppBackToOverview on
          day view, #ppBackToMarket on pack overview) — defer to it. That
          keeps the pack closure in charge of its own filter / category /
          progress state.
       2. Else if dashboardState.previousView is set and not the current
          view — route there (e.g. user went notes → plan-packs, "Back"
          returns to notes).
       3. Else fall back to Graph View.
     The label + aria-label update on every showWorkspaceView and on
     #workspaceContent mutations (pack-internal nav re-renders inside the
     same view, so we need a DOM observer in addition to the view-change
     hook). */
  function _getWorkspaceBackContext() {
    var current = (dashboardState && dashboardState.currentView) || 'graph';
    if (current === 'plan-packs') {
      var dayBack = document.getElementById('ppBackToOverview');
      if (dayBack) return {
        label:    'Pack Overview',
        ariaText: 'Back to pack overview',
        handler:  function () { dayBack.click(); }
      };
      var marketBack = document.getElementById('ppBackToMarket');
      if (marketBack) return {
        label:    'Plan Packs',
        ariaText: 'Back to Plan Packs',
        handler:  function () { marketBack.click(); }
      };
    }
    var prev = dashboardState && dashboardState.previousView;
    if (prev && prev !== current && prev !== 'graph') {
      var meta = (typeof WS_META !== 'undefined' && WS_META[prev]) || null;
      var prevLabel = meta ? meta.title : prev;
      return {
        label:    prevLabel,
        ariaText: 'Back to ' + prevLabel,
        handler:  function () { if (window.switchDashboardView) window.switchDashboardView(prev); }
      };
    }
    return {
      label:    'Graph View',
      ariaText: 'Back to Graph View',
      handler:  function () {
        if (window.switchDashboardView) window.switchDashboardView('graph');
        else showGraphView();
      }
    };
  }
  function _updateWorkspaceBackButton() {
    var btn = document.getElementById('workspaceBackToGraph');
    if (!btn) return;
    var ctx = _getWorkspaceBackContext();
    var span = btn.querySelector('span');
    if (span) span.textContent = ctx.label;
    btn.setAttribute('aria-label', ctx.ariaText);
  }
  var backBtn = document.getElementById('workspaceBackToGraph');
  if (backBtn) backBtn.addEventListener('click', function () {
    /* Evaluate at click time so pack-internal navigation that happened
       after the last render is respected. */
    _getWorkspaceBackContext().handler();
  });
  /* Observe pack-internal re-renders so the label tracks day-view →
     pack-overview → marketplace transitions inside the same view. One
     MutationObserver, cheap, scoped to #workspaceContent's children. */
  var wsContent = document.getElementById('workspaceContent');
  if (wsContent && typeof MutationObserver === 'function' && !wsContent._eeBackBtnObserver) {
    var obs = new MutationObserver(function () { _updateWorkspaceBackButton(); });
    obs.observe(wsContent, { childList: true, subtree: true });
    wsContent._eeBackBtnObserver = obs;
  }
  /* Expose for showWorkspaceView and external callers. */
  window._updateWorkspaceBackButton = _updateWorkspaceBackButton;
  _updateWorkspaceBackButton();

  /* expose public API */
  window.dashboardState       = dashboardState;
  window.switchDashboardView  = switchDashboardView;
  window.showGraphView        = showGraphView;
  window.showWorkspaceView    = showWorkspaceView;
  window.closeWorkspaceView   = closeWorkspaceView;
  window.updateTopBarContext  = updateTopBarContext;
  /* Stage 34-B: expose workflow switcher helpers for runtime inspection and
     future stages (34-E will read getCurrentWorkflowMode from EE_GRAPH_API). */
  window.WORKFLOW_MODES         = WORKFLOW_MODES;
  window.getCurrentWorkflowMode = getCurrentWorkflowMode;
  window.cycleWorkflowMode      = cycleWorkflowMode;
  window.updateWorkflowSwitcher = updateWorkflowSwitcher;
  /* Stage 34-C: expose top-menu dropdown helpers for debugging and for
     future stages that may need to refresh active state programmatically. */
  window.closeTopMenuDropdowns  = closeTopMenuDropdowns;
  window.toggleTopMenuDropdown  = toggleTopMenuDropdown;
  window.bindTopMenuDropdowns   = bindTopMenuDropdowns;
  window.handleTopMenuViewClick = handleTopMenuViewClick;
  /* Stage 34-D-HOTFIX-R2: expose wheel/touch scroll-guard binder for
     debug + re-arming after late-mounted dropdown DOM. */
  window.bindDropdownScrollGuards = bindDropdownScrollGuards;
  /* Stage 34-D-HOTFIX-R3: expose workspace scroll-guard binder so a
     late-mounted view (or a hot edit) can re-arm guards from the console. */
  window.bindWorkspaceScrollGuards = bindWorkspaceScrollGuards;
  /* Stage 34-D: expose layout toggle + debug rollback helpers so a tester
     can re-show the legacy sidebar at runtime without touching the DOM. */
  window.applyTopMenuLayout            = applyTopMenuLayout;
  window.disableTopMenuLayoutForDebug  = disableTopMenuLayoutForDebug;
  window.enableTopMenuLayoutForDebug   = enableTopMenuLayoutForDebug;
  window.setDashboardBackgroundMode = setDashboardBackgroundMode;
  window.setGraphInteractionEnabled = setGraphInteractionEnabled;
  window.hideGraphHudForWorkspace   = hideGraphHudForWorkspace;
  window.showGraphHudForGraphView   = showGraphHudForGraphView;
  window.initSidebarCollapse        = initSidebarCollapse;
  window.toggleSidebarCollapsed     = toggleSidebarCollapsed;
  window.setSidebarCollapsed        = setSidebarCollapsed;
  window.EE_WORKSPACE_RENDER  = window.EE_WORKSPACE_RENDER  || {};
  window.EE_WORKSPACE_EVENTS  = window.EE_WORKSPACE_EVENTS  || {};

  /* Stage 1: My Active Plan workspace (empty state for now) */
  window.EE_WORKSPACE_RENDER['active-plan'] = renderActivePlan;
  window.EE_WORKSPACE_EVENTS['active-plan'] = attachActivePlanEvents;

  /* Stage 2: tabbed Settings + plan helpers + toast + checkout placeholders */
  window.EE_WORKSPACE_RENDER['settings']    = renderSettingsTabbed;
  window.EE_WORKSPACE_EVENTS['settings']    = attachSettingsTabsEvents;

  /* Gate Plan Packs through new plan-level helper. Pro users see the
     existing marketplace; Free / Core users see the new locked screen
     with preview cards. We override via window.EE_WORKSPACE_RENDER so
     the original renderPlanPacks closure is left untouched. */
  var _origPacksRender = window.EE_WORKSPACE_RENDER['plan-packs'];
  var _origPacksEvents = window.EE_WORKSPACE_EVENTS['plan-packs'];
  window.EE_WORKSPACE_RENDER['plan-packs'] = function () {
    if (canAccessPlanPacks()) {
      /* Sync the legacy access flag so the original renderPlanPacks
         (which checks EE_IS_PRO || ee_plan_pack_access) lets the user in.
         Real Pro users short-circuit on EE_IS_PRO so this is a no-op for them. */
      try { localStorage.setItem('ee_plan_pack_access', 'true'); } catch (e) {}
      return (typeof _origPacksRender === 'function') ? _origPacksRender() : wsPlaceholder('⚡', 'Plan Packs', 'Loading...');
    }
    /* Clear the legacy flag when access is revoked (e.g. mock downgrade) */
    try { localStorage.removeItem('ee_plan_pack_access'); } catch (e) {}
    return renderLockedPlanPacksScreen(getUserPlanLevel());
  };
  window.EE_WORKSPACE_EVENTS['plan-packs'] = function () {
    if (canAccessPlanPacks()) {
      if (typeof _origPacksEvents === 'function') _origPacksEvents();
      return;
    }
    attachLockedPlanPacksEvents();
  };

  /* Stage 5 - Dataview surface for active plan (prepend a small card) */
  var _origDataviewRender = window.EE_WORKSPACE_RENDER['dataview'];
  if (typeof _origDataviewRender === 'function') {
    window.EE_WORKSPACE_RENDER['dataview'] = function () {
      var apHtml = '';
      var ap = (typeof getActivePack === 'function') ? getActivePack() : null;
      if (ap) {
        var pp = _apReadProgress()[ap.id] || {};
        var done = 0;
        (ap.days || []).forEach(function (d) { if (pp['day_' + d.day]) done++; });
        var total = (ap.days || []).length;
        var pct = total ? Math.round(done/total*100) : 0;
        apHtml = '<div class="ap-dv-card">'
          + '<div class="ap-dv-kicker">ACTIVE PLAN</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Pack</div><div class="ap-dv-val">' + _apDpEsc(ap.title) + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Progress</div><div class="ap-dv-val">' + pct + '%</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Completed</div><div class="ap-dv-val">' + done + ' days</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Remaining</div><div class="ap-dv-val">' + Math.max(0, total - done) + ' days</div></div>'
          + '</div>'
          + '</div>';
      }
      /* Stage 12: Daily Execution summary - lightweight stats above the rest */
      var execHtml = '';
      if (typeof getRealStreak === 'function') {
        var streak = getRealStreak();
        var d7  = (typeof getSevenDaySummary  === 'function') ? getSevenDaySummary()  : [];
        var d30 = (typeof getThirtyDayHeatmap === 'function') ? getThirtyDayHeatmap() : [];
        var days7  = d7.reduce(function  (s, x) { return s + (x.completedDays || 0); }, 0);
        var days30 = d30.reduce(function (s, x) { return s + (x.completedDays || 0); }, 0);
        /* Stage 14: real checklist counts from the daily log */
        var clHist = (typeof getChecklistHistory === 'function') ? getChecklistHistory(7) : [];
        var clToday = clHist.length ? (clHist[clHist.length - 1].checked || 0) : 0;
        var clWeek  = clHist.reduce(function (s, x) { return s + (x.checked || 0); }, 0);
        execHtml = '<div class="dv-execution-card">'
          + '<div class="ap-dv-kicker">DAILY EXECUTION</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Current streak</div><div class="ap-dv-val">' + streak.currentStreak + ' day' + (streak.currentStreak === 1 ? '' : 's') + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Longest streak</div><div class="ap-dv-val">' + streak.longestStreak + ' day' + (streak.longestStreak === 1 ? '' : 's') + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Last 7 days</div><div class="ap-dv-val">' + days7 + ' day' + (days7 === 1 ? '' : 's') + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Last 30 days</div><div class="ap-dv-val">' + days30 + ' day' + (days30 === 1 ? '' : 's') + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Items today</div><div class="ap-dv-val">' + clToday + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Items last 7 days</div><div class="ap-dv-val">' + clWeek + '</div></div>'
          + '</div>'
          + '<div class="dv-exec-actions"><button class="dv-exec-link" id="dvOpenCalendar">Open Calendar</button></div>'
          + '</div>';
      }
      /* Stage 15: lightweight Notes summary card */
      var notesHtml = '';
      if (typeof getAllNotesForHub === 'function') {
        var allNotes = getAllNotesForHub();
        var packN    = allNotes.filter(function (n) { return n.sourceType === 'pack'; }).length;
        var genN     = allNotes.filter(function (n) { return n.sourceType === 'general'; }).length;
        var lastTs   = allNotes.length ? allNotes[0].updatedAt : 0;
        var lastRel  = (typeof _nhFormatRel === 'function') ? _nhFormatRel(lastTs) : 'Never edited';
        notesHtml = '<div class="dv-notes-card">'
          + '<div class="ap-dv-kicker">NOTES</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Total</div><div class="ap-dv-val">' + allNotes.length + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Pack notes</div><div class="ap-dv-val">' + packN + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">General</div><div class="ap-dv-val">' + genN + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Last edited</div><div class="ap-dv-val">' + _apDpEsc(lastRel) + '</div></div>'
          + '</div>'
          + '</div>';
      }
      /* Stage 17: lightweight Templates summary card */
      var tplHtml = '';
      if (typeof DASHBOARD_TEMPLATES !== 'undefined' && typeof getTemplateUsage === 'function') {
        var usage = getTemplateUsage();
        var notesFromTpl = usage.filter(function (u) { return !!u.createdNoteId; }).length;
        tplHtml = '<div class="dv-templates-card">'
          + '<div class="ap-dv-kicker">TEMPLATES</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Available</div><div class="ap-dv-val">' + DASHBOARD_TEMPLATES.length + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Used</div><div class="ap-dv-val">' + usage.length + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Notes from templates</div><div class="ap-dv-val">' + notesFromTpl + '</div></div>'
          + '</div>'
          + '</div>';
      }
      /* Stage 18: lightweight Tags summary card */
      var tagsCardHtml = '';
      if (typeof getTagsIndex === 'function') {
        var allTags    = getTagsIndex();
        var totalTags  = allTags.length;
        var mostUsed   = allTags[0] ? allTags[0].label : '-';
        var packTags   = allTags.filter(function (t) { return t.counts.packs > 0; }).length;
        var noteTags   = allTags.filter(function (t) { return t.counts.notes > 0; }).length;
        tagsCardHtml = '<div class="dv-tags-card">'
          + '<div class="ap-dv-kicker">TAGS</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Total tags</div><div class="ap-dv-val">' + totalTags + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Most used</div><div class="ap-dv-val">' + _apDpEsc(mostUsed) + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Pack tags</div><div class="ap-dv-val">' + packTags + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Note tags</div><div class="ap-dv-val">' + noteTags + '</div></div>'
          + '</div>'
          + '</div>';
      }
      /* Stage 21: lightweight Tasks summary card */
      var tasksCardHtml = '';
      if (typeof getTasks === 'function') {
        var allT     = getTasks();
        var todayKey21 = (typeof todayKey === 'function') ? todayKey() : '';
        var openT    = allT.filter(function (t) { return t.status !== 'done'; });
        var dueT     = openT.filter(function (t) { return t.dueDate === todayKey21; }).length;
        var ovrT     = openT.filter(function (t) { return t.dueDate && t.dueDate < todayKey21; }).length;
        var doneT    = allT.filter(function (t) { return t.status === 'done'; }).length;
        tasksCardHtml = '<div class="dv-tasks-card">'
          + '<div class="ap-dv-kicker">TASKS</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Open</div><div class="ap-dv-val">' + openT.length + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Due today</div><div class="ap-dv-val">' + dueT + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Overdue</div><div class="ap-dv-val">' + ovrT + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Completed</div><div class="ap-dv-val">' + doneT + '</div></div>'
          + '</div>'
          + '</div>';
      }
      /* Stage 24: lightweight Daily Log summary card */
      var dlCardHtml = '';
      if (typeof getDailyLogs === 'function') {
        var logs24    = getDailyLogs();
        var dates24   = Object.keys(logs24).sort();
        var todayK24  = (typeof todayKey === 'function') ? todayKey() : '';
        var lastDate  = dates24.length ? dates24[dates24.length - 1] : '-';
        var todaySaved = !!logs24[todayK24];
        dlCardHtml = '<div class="dv-dailylog-card">'
          + '<div class="ap-dv-kicker">DAILY LOG</div>'
          + '<div class="ap-dv-grid">'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Logs saved</div><div class="ap-dv-val">' + dates24.length + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Last log</div><div class="ap-dv-val">' + _apDpEsc(lastDate) + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Today saved</div><div class="ap-dv-val">' + (todaySaved ? 'Yes' : 'No') + '</div></div>'
          +   '<div class="ap-dv-cell"><div class="ap-dv-lbl">Days reflected</div><div class="ap-dv-val">' + dates24.length + '</div></div>'
          + '</div>'
          + '</div>';
      }
      return execHtml + apHtml + notesHtml + tplHtml + tagsCardHtml + tasksCardHtml + dlCardHtml + _origDataviewRender();
    };
    /* Stage 16: wire the Open Calendar link inside the Daily Execution card */
    var _origDataviewEvents = window.EE_WORKSPACE_EVENTS['dataview'];
    window.EE_WORKSPACE_EVENTS['dataview'] = function () {
      if (typeof _origDataviewEvents === 'function') { try { _origDataviewEvents(); } catch (e) {} }
      var openCal = document.getElementById('dvOpenCalendar');
      if (openCal) openCal.addEventListener('click', function () {
        if (window.switchDashboardView) window.switchDashboardView('calendar');
      });
    };
  }

  window.getUserPlanLevel      = getUserPlanLevel;
  window.isFreePlan            = isFreePlan;
  window.isEmpireCorePlan      = isEmpireCorePlan;
  window.isEmpireProPlan       = isEmpireProPlan;
  window.canAccessPlanPacks    = canAccessPlanPacks;
  window.setMockPlanLevel      = setMockPlanLevel;
  window.showToast             = window.showToast || showToast;
  window.startPlanCheckout     = startPlanCheckout;
  window.openBillingPortal     = openBillingPortal;
  window.showPlanComparisonModal  = showPlanComparisonModal;
  window.closePlanComparisonModal = closePlanComparisonModal;
  window.refreshCurrentView    = refreshCurrentView;
}

/* ══════════════════════════════════════
   RIGHT PANEL SYSTEM  (p20)
══════════════════════════════════════ */
function initRightPanel() {
  var dashRight  = document.getElementById('dashRight');
  var rpPanel    = document.getElementById('rpPanel');
  var rpToggle   = document.getElementById('rpToggle');
  var rpFilters  = document.getElementById('rpFilters');
  var rpWList    = document.getElementById('rpWList');
  var rpActReset = document.getElementById('rpActReset');
  var rpActLib   = document.getElementById('rpActLib');
  var rpActLearn = document.getElementById('rpActLearn');

  if (!dashRight) return;

  var rpListFilter = 'all';
  var lastWorldId  = null;

  /* ── Toggle open/close ── */
  if (rpToggle) {
    rpToggle.addEventListener('click', function () {
      var isOpen = dashRight.classList.toggle('rp-open');
      if (rpPanel) rpPanel.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
    });
  }

  /* Block panel interactions from reaching globe */
  if (rpPanel) {
    rpPanel.addEventListener('mousedown',  function (e) { e.stopPropagation(); });
    rpPanel.addEventListener('wheel',      function (e) { e.stopPropagation(); }, { passive: true });
    rpPanel.addEventListener('touchstart', function (e) { e.stopPropagation(); }, { passive: true });
    rpPanel.addEventListener('click',      function (e) { e.stopPropagation(); });
  }

  /* ── Filter tabs ── */
  if (rpFilters) {
    rpFilters.addEventListener('click', function (e) {
      var btn = e.target.closest('.rp-flt');
      if (!btn) return;
      rpListFilter = btn.getAttribute('data-f');
      Array.prototype.forEach.call(rpFilters.querySelectorAll('.rp-flt'), function (b) {
        b.classList.toggle('rp-flt-on', b === btn);
      });
      buildRpWorldList(rpListFilter);
    });
  }

  function rpEsc(s) {
    return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  /* ── Build compact world list ── */
  function buildRpWorldList(filter) {
    if (!rpWList) return;
    var items = [];

    /* Core */
    if (filter === 'all' || filter === 'linked') {
      items.push({ wid: 'gnCore', name: 'Empire Core', type: 'core', color: [212,175,55] });
    }

    /* Main worlds */
    SAT_NODES.forEach(function (n) {
      var d = WORLD_DATA[n.id];
      if (!d) return;
      if (filter === 'all' || filter === 'main' || filter === 'linked') {
        items.push({ wid: n.id, name: d.title, type: 'main', color: n.color });
      }
    });

    /* Outer worlds */
    if (filter === 'all' || filter === 'outer') {
      BUBBLE_NODES.forEach(function (b, i) {
        var wid = 'bubble-' + i;
        var d = WORLD_DATA[wid];
        if (!d) return;
        items.push({ wid: wid, name: d.title, type: 'outer', color: b.color });
      });
    } else if (filter === 'linked') {
      BUBBLE_NODES.forEach(function (b, i) {
        var wid = 'bubble-' + i;
        var d = WORLD_DATA[wid];
        if (!d) return;
        if (window.EE_GLOBE_API && window.EE_GLOBE_API.isLinked(wid)) {
          items.push({ wid: wid, name: d.title, type: 'outer', color: b.color });
        }
      });
    }

    if (items.length === 0) {
      rpWList.innerHTML = '<div style="font-size:0.60rem;color:rgba(255,255,255,0.20);padding:8px 0;">No worlds</div>';
      return;
    }

    rpWList.innerHTML = items.map(function (it) {
      var c = it.color;
      var rgb = c[0] + ',' + c[1] + ',' + c[2];
      var dotStyle = 'background:rgb(' + rgb + ');box-shadow:0 0 5px rgba(' + rgb + ',0.50)';
      var badgeCls = it.type === 'core' ? 'rp-badge-core'
                   : it.type === 'main' ? 'rp-badge-main'
                   : 'rp-badge-outer';
      var badgeTxt = it.type === 'core' ? 'Core'
                   : it.type === 'main' ? 'Main'
                   : 'Outer';
      return '<div class="rp-witem" data-wid="' + it.wid + '">'
        + '<div class="rp-witem-dot" style="' + dotStyle + '"></div>'
        + '<span class="rp-witem-name">' + rpEsc(it.name) + '</span>'
        + '<span class="rp-witem-badge ' + badgeCls + '">' + badgeTxt + '</span>'
        + '</div>';
    }).join('');

    /* Click world item → focus world or open library */
    Array.prototype.forEach.call(rpWList.querySelectorAll('.rp-witem'), function (item) {
      item.addEventListener('click', function () {
        var wid = item.getAttribute('data-wid');
        if (wid === 'gnCore') {
          if (window.EE_GLOBE_API) window.EE_GLOBE_API.openLibrary();
        } else {
          if (window.EE_GLOBE_API) {
            var api = window.EE_GLOBE_API;
            if (api.focusWorld) api.focusWorld(wid); else api.enterWorld(wid);
          }
        }
      });
    });
  }

  /* Initial list build */
  buildRpWorldList('all');

  /* ── Quick actions ── */
  if (rpActReset) {
    rpActReset.addEventListener('click', function () {
      if (window.EE_GRAPH_API) window.EE_GRAPH_API.resetView();
    });
  }
  if (rpActLib) {
    rpActLib.addEventListener('click', function () {
      if (window.EE_GLOBE_API) window.EE_GLOBE_API.openLibrary();
    });
  }
  if (rpActLearn) {
    rpActLearn.addEventListener('click', function () {
      if (lastWorldId && window.EE_GLOBE_API) {
        window.EE_GLOBE_API.enterWorld(lastWorldId);
      } else if (window.EE_GRAPH_API) {
        window.EE_GRAPH_API.resetView();
      }
    });
  }

  /* ── Public API used by globe engine ── */
  window.EE_RIGHT_PANEL = {
    setWorld: function (worldId) {
      lastWorldId = worldId;
      var d = WORLD_DATA[worldId];
      if (!d) return;

      var selEmpty = document.getElementById('rpSelEmpty');
      var selCard  = document.getElementById('rpSelCard');
      var selDot   = document.getElementById('rpSelDot');
      var selName  = document.getElementById('rpSelName');
      var selType  = document.getElementById('rpSelType');
      var selFill  = document.getElementById('rpSelFill');
      var selPct   = document.getElementById('rpSelPct');

      if (selEmpty) selEmpty.style.display = 'none';
      if (selCard)  selCard.style.display  = '';

      var col = d.color || '#d4af37';
      if (selDot)  {
        selDot.style.background = col;
        selDot.style.boxShadow  = '0 0 9px ' + col;
      }
      if (selName) selName.textContent = d.title;
      if (selType) {
        selType.textContent =
          worldId === 'gnCore'         ? 'CORE WORLD'
          : worldId.startsWith('bubble-') ? 'OUTER WORLD'
          : 'MAIN WORLD';
      }

      var pct = window.EE_GRAPH_API ? window.EE_GRAPH_API.getProgress(worldId) : 0;
      if (selFill) { selFill.style.width = pct + '%'; selFill.style.background = col; }
      if (selPct)  selPct.textContent = pct + '%';
    },
    clearWorld: function () {
      var selEmpty = document.getElementById('rpSelEmpty');
      var selCard  = document.getElementById('rpSelCard');
      if (selEmpty) selEmpty.style.display = '';
      if (selCard)  selCard.style.display  = 'none';
    },
    setStatus: function (status) {
      var dot  = document.getElementById('rpDot');
      var text = document.getElementById('rpStatusText');
      if (!dot || !text) return;
      dot.className  = 'rp-status-dot';
      text.className = 'rp-status-text';
      if (status === 'LIBRARY') {
        dot.classList.add('rp-sd-library');
        text.classList.add('rp-st-library');
        text.textContent = 'LIBRARY';
      } else if (status === 'FOCUSED') {
        dot.classList.add('rp-sd-focused');
        text.classList.add('rp-st-focused');
        text.textContent = 'FOCUSED';
      } else if (status === 'LEARNING') {
        dot.classList.add('rp-sd-learning');
        text.classList.add('rp-st-learning');
        text.textContent = 'LEARNING';
      } else {
        text.textContent = 'LIVE';
      }
    },
    rebuildList: buildRpWorldList
  };
}

/* ══════════════════════════════════════
   HEADER CONTROLS  (search + profile)
══════════════════════════════════════ */
function initHeader() {
  /* ── Search ── */
  var srchWrap  = document.getElementById('tbSrchWrap');
  var srchInput = document.getElementById('tbSrchInput');
  var srchDrop  = document.getElementById('tbSrchDrop');
  var srchOpen  = false;

  function positionSearchDrop() {
    var r = srchWrap.getBoundingClientRect();
    srchDrop.style.top  = (r.bottom + 6) + 'px';
    srchDrop.style.left = r.left + 'px';
  }

  function openSearchDrop() {
    if (srchOpen) return;
    /* Stage 27: Stage 19 global palette has fully replaced this dropdown.
       If it's installed, the top-bar input belongs to the palette, so the
       old Worlds/Lessons-only dropdown must not surface (used to flash open
       behind the modal on Tab focus). */
    if (window.__eeStage19SearchInstalled) return;
    srchOpen = true;
    srchWrap.classList.add('srch-active');
    positionSearchDrop();
    srchDrop.classList.add('sd-open');
    srchDrop.setAttribute('aria-hidden', 'false');
  }

  function closeSearchDrop() {
    if (!srchOpen) return;
    srchOpen = false;
    srchWrap.classList.remove('srch-active');
    srchDrop.classList.remove('sd-open');
    srchDrop.setAttribute('aria-hidden', 'true');
  }

  function buildSearchResults(q) {
    var results = [];
    q = (q || '').toLowerCase().trim();
    Object.keys(WORLD_DATA).forEach(function (wid) {
      var w = WORLD_DATA[wid];
      if (!q || w.title.toLowerCase().indexOf(q) >= 0 || (w.desc && w.desc.toLowerCase().indexOf(q) >= 0)) {
        results.push({ type: 'world', id: wid, label: w.title, sub: w.subtitle || '', color: w.color });
      }
    });
    Object.keys(WORLD_LESSONS).forEach(function (wid) {
      var w = WORLD_DATA[wid];
      var wl = WORLD_LESSONS[wid];
      Object.keys(wl).forEach(function (lk) {
        var l = wl[lk];
        var match = !q || lk.toLowerCase().indexOf(q) >= 0 || (l.title && l.title.toLowerCase().indexOf(q) >= 0);
        if (match) {
          results.push({ type: 'lesson', id: wid, lkey: lk, label: l.title || lk, sub: w ? w.title : wid, color: w ? w.color : '#888' });
        }
      });
    });
    return q ? results.slice(0, 12) : results.slice(0, 8);
  }

  function renderSearchResults(q) {
    var items = buildSearchResults(q);
    if (!items.length) {
      srchDrop.innerHTML = '<div class="tb-srch-empty">No results</div>';
      return;
    }
    var worlds  = items.filter(function (i) { return i.type === 'world'; });
    var lessons = items.filter(function (i) { return i.type === 'lesson'; });
    var html = '';
    if (worlds.length) {
      html += '<div class="tb-srch-section">Worlds</div>';
      worlds.forEach(function (r) {
        html += '<div class="tb-srch-item" data-type="world" data-id="' + r.id + '">' +
          '<span class="tb-srch-dot" style="background:' + r.color + '"></span>' +
          '<span class="tb-srch-label">' + r.label + '</span>' +
          '<span class="tb-srch-sub">' + r.sub + '</span></div>';
      });
    }
    if (lessons.length) {
      html += '<div class="tb-srch-section">Lessons</div>';
      lessons.forEach(function (r) {
        html += '<div class="tb-srch-item" data-type="lesson" data-id="' + r.id + '" data-lkey="' + encodeURIComponent(r.lkey) + '">' +
          '<span class="tb-srch-dot" style="background:' + r.color + ';opacity:0.55"></span>' +
          '<span class="tb-srch-label">' + r.label + '</span>' +
          '<span class="tb-srch-sub">' + r.sub + '</span></div>';
      });
    }
    srchDrop.innerHTML = html;
    srchDrop.querySelectorAll('.tb-srch-item').forEach(function (el) {
      el.addEventListener('mousedown', function (e) {
        e.preventDefault();
        var type = el.dataset.type;
        var id   = el.dataset.id;
        closeSearchDrop();
        srchInput.value = '';
        if (type === 'world') {
          if (window.EE_GLOBE_API) {
            if (id === 'gnCore') { window.EE_GLOBE_API.openLibrary(); }
            else { window.EE_GLOBE_API.focusWorld(id); }
          }
        } else {
          var lkey = decodeURIComponent(el.dataset.lkey);
          if (window.EE_GLOBE_API) window.EE_GLOBE_API.enterWorld(id);
          setTimeout(function () {
            if (window.EE_GLOBE_API && window.EE_GLOBE_API.openLesson) {
              window.EE_GLOBE_API.openLesson(id, lkey);
            }
          }, 400);
        }
      });
    });
  }

  if (srchInput) {
    srchInput.addEventListener('focus', function () {
      openSearchDrop();
      renderSearchResults(srchInput.value);
    });
    srchInput.addEventListener('input', function () {
      openSearchDrop();
      renderSearchResults(srchInput.value);
    });
    srchInput.addEventListener('blur', function () {
      setTimeout(closeSearchDrop, 180);
    });
    srchInput.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { closeSearchDrop(); srchInput.blur(); }
    });
  }

  document.addEventListener('keydown', function (e) {
    if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
      e.preventDefault();
      if (srchInput) { srchInput.focus(); openSearchDrop(); renderSearchResults(''); }
    }
  });

  /* ── Profile dropdown ── */
  var profWrap = document.getElementById('tbProfWrap');
  var profBtn  = document.getElementById('tbProfBtn');
  var profDrop = document.getElementById('tbProfDrop');
  var profAv   = document.getElementById('tbProfAv');
  var profOpen = false;

  /* Try to get user info from Firebase */
  var userName  = 'Empire User';
  var userEmail = '';
  try {
    var cu = firebase && firebase.auth && firebase.auth().currentUser;
    if (cu) { userName = cu.displayName || cu.email || 'Empire User'; userEmail = cu.email || ''; }
  } catch (e) {}

  function getInitials(name) {
    var parts = (name || 'EE').trim().split(/\s+/);
    return (parts[0].charAt(0) + (parts[1] ? parts[1].charAt(0) : '')).toUpperCase().slice(0, 2);
  }
  if (profAv) profAv.textContent = getInitials(userName);

  var themeState = { autoSpin: true, nodeLabels: true, energyLines: true, glow: true };

  function positionProfDrop() {
    var r = profBtn.getBoundingClientRect();
    profDrop.style.top   = (r.bottom + 6) + 'px';
    profDrop.style.right = (window.innerWidth - r.right) + 'px';
    profDrop.style.left  = 'auto';
  }

  function menuHTML() {
    var initials = getInitials(userName);
    var displayName = userName.length > 20 ? userName.slice(0, 20) + '…' : userName;
    return '<div class="tb-prof-header">' +
      '<div class="tb-prof-av-lg">' + initials + '</div>' +
      '<div><div class="tb-prof-name">' + displayName + '</div>' +
      (userEmail ? '<div class="tb-prof-email">' + userEmail + '</div>' : '') + '</div></div>' +
      '<div class="tp-menu-item" data-act="settings"><span class="tp-menu-icon">⚙</span><span class="tp-menu-label">Dashboard Settings</span><span class="tp-menu-arrow">›</span></div>' +
      '<div class="tp-menu-item" data-act="theme"><span class="tp-menu-icon">◐</span><span class="tp-menu-label">Theme Controls</span><span class="tp-menu-arrow">›</span></div>' +
      '<div class="tp-menu-item" data-act="progress"><span class="tp-menu-icon">◈</span><span class="tp-menu-label">My Progress</span><span class="tp-menu-arrow">›</span></div>' +
      '<div class="tp-divider"></div>' +
      '<div class="tp-menu-item tp-logout" data-act="logout"><span class="tp-menu-icon">↩</span><span class="tp-menu-label">Log Out</span></div>';
  }

  function themeHTML() {
    function row(label, key) {
      return '<div class="tp-toggle-row"><span class="tp-toggle-label">' + label + '</span>' +
        '<button class="tp-toggle' + (themeState[key] ? ' tg-on' : '') + '" data-tkey="' + key + '" aria-pressed="' + themeState[key] + '"></button></div>';
    }
    return '<div class="tp-sub-back" data-act="back">‹  Back</div>' +
      '<div class="tp-sub-title">Theme Controls</div>' +
      row('Auto Spin', 'autoSpin') +
      row('Node Labels', 'nodeLabels') +
      row('Energy Lines', 'energyLines') +
      row('Glow Effects', 'glow');
  }

  function progressHTML() {
    var raw = {};
    try { raw = JSON.parse(localStorage.getItem('ee_lesson_progress') || '{}'); } catch (e) {}
    var totalLessons = 0, completedLessons = 0, worldsStarted = 0;
    Object.keys(WORLD_LESSONS).forEach(function (wid) {
      var wl = WORLD_LESSONS[wid];
      var keys = Object.keys(wl);
      totalLessons += keys.length;
      var wDone = 0;
      keys.forEach(function (lk) {
        var l = wl[lk];
        var lid = l.id || lk;
        var st = raw[lid];
        if (st && (st.completed || (st.pct && st.pct >= 80))) { completedLessons++; wDone++; }
      });
      if (wDone > 0) worldsStarted++;
    });
    var pct = totalLessons > 0 ? Math.round((completedLessons / totalLessons) * 100) : 0;
    return '<div class="tp-sub-back" data-act="back">‹  Back</div>' +
      '<div class="tp-sub-title">My Progress</div>' +
      '<div class="tp-prog-bar-wrap"><div class="tp-prog-bar-fill" style="width:' + pct + '%"></div></div>' +
      '<div class="tp-prog-stat"><span class="tp-prog-lbl">Overall Completion</span><span class="tp-prog-val">' + pct + '%</span></div>' +
      '<div class="tp-prog-stat"><span class="tp-prog-lbl">Lessons Completed</span><span class="tp-prog-val">' + completedLessons + ' / ' + totalLessons + '</span></div>' +
      '<div class="tp-prog-stat"><span class="tp-prog-lbl">Worlds Active</span><span class="tp-prog-val">' + worldsStarted + ' / ' + Object.keys(WORLD_DATA).length + '</span></div>';
  }

  function renderProfDrop(view) {
    if (view === 'menu')     profDrop.innerHTML = menuHTML();
    if (view === 'theme')    profDrop.innerHTML = themeHTML();
    if (view === 'progress') profDrop.innerHTML = progressHTML();

    profDrop.querySelectorAll('[data-act]').forEach(function (el) {
      el.addEventListener('click', function () {
        var act = el.dataset.act;
        if (act === 'back')     { renderProfDrop('menu'); return; }
        if (act === 'theme')    { renderProfDrop('theme'); return; }
        if (act === 'progress') { renderProfDrop('progress'); return; }
        if (act === 'settings') {
          closeProf();
          if (window.EE_PANEL_API) window.EE_PANEL_API.openPanel('settings');
          return;
        }
        if (act === 'logout') {
          closeProf();
          if (window.EE_SIGN_OUT) window.EE_SIGN_OUT();
          return;
        }
      });
    });

    profDrop.querySelectorAll('.tp-toggle').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var key = btn.dataset.tkey;
        themeState[key] = !themeState[key];
        btn.classList.toggle('tg-on', themeState[key]);
        btn.setAttribute('aria-pressed', String(themeState[key]));
        if (window.EE_GRAPH_API) {
          if (key === 'autoSpin'    && window.EE_GRAPH_API.setAutoSpin)    window.EE_GRAPH_API.setAutoSpin(themeState[key]);
          if (key === 'nodeLabels'  && window.EE_GRAPH_API.setNodeLabels)  window.EE_GRAPH_API.setNodeLabels(themeState[key]);
          if (key === 'energyLines' && window.EE_GRAPH_API.setEnergyLines) window.EE_GRAPH_API.setEnergyLines(themeState[key]);
          if (key === 'glow'        && window.EE_GRAPH_API.setGlow)        window.EE_GRAPH_API.setGlow(themeState[key]);
        }
      });
    });
  }

  function openProf() {
    if (profOpen) return;
    profOpen = true;
    profWrap.classList.add('pf-open');
    positionProfDrop();
    renderProfDrop('menu');
    profDrop.classList.add('pd-open');
    profDrop.setAttribute('aria-hidden', 'false');
    /* Stage 30.4 - keep button's aria-expanded in sync with menu state. */
    if (profBtn) profBtn.setAttribute('aria-expanded', 'true');
  }

  function closeProf() {
    if (!profOpen) return;
    profOpen = false;
    profWrap.classList.remove('pf-open');
    profDrop.classList.remove('pd-open');
    profDrop.setAttribute('aria-hidden', 'true');
    if (profBtn) profBtn.setAttribute('aria-expanded', 'false');
  }

  if (profBtn) {
    /* Stage 30.4 - explicit type=button so this never submits ambient forms,
       and an initial aria-expanded so screen readers don't see a stale value. */
    profBtn.setAttribute('type', 'button');
    profBtn.setAttribute('aria-haspopup', 'menu');
    profBtn.setAttribute('aria-expanded', 'false');
    profBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      if (profOpen) closeProf(); else openProf();
    });
  }

  /* Stage 30.4 - Escape closes the profile menu (the search dropdown already
     has its own Escape handler on the input). Scoped to body keydown so it
     does not stack on every re-init (initHeader is one-shot in Stage 27). */
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && profOpen) { closeProf(); }
  });

  document.addEventListener('click', function (e) {
    if (profOpen  && profWrap  && !profWrap.contains(e.target))  closeProf();
    if (srchOpen  && srchWrap  && !srchWrap.contains(e.target))  closeSearchDrop();
  });
}

/* ── Global stubs (prevent inline onclick errors) ── */
window.closeModal       = function () {};
window.openModal        = function () {};
window.openUpgradeModal = function (name) {
  var modal  = document.getElementById('upgradeModal');
  var nameEl = document.getElementById('upgradeFeatureName');
  if (!modal) return;
  if (nameEl) nameEl.textContent = name || 'Full Access';
  /* Stage 29: focus restore pattern, shared with the newer plan-comparison
     modal. Uses a different key so the two never collide. */
  _eeStashFocusOpener('upgradeLegacy', modal);
  modal.style.display  = 'flex';
  document.body.style.overflow = 'hidden';
};
window.closeUpgradeModal = function () {
  var modal = document.getElementById('upgradeModal');
  if (modal) modal.style.display = 'none';
  document.body.style.overflow = '';
  _eeRestoreFocusOpener('upgradeLegacy');
};
window.startProCheckout   = function () { window.location.href = '../plan.html'; };
window.applyFreeTierState = function () {};

/* Stage 31.2D-B: graph view guidance hint - 6s passive fade.
   After ee:authReady (the same trigger that reveals the dashboard), give
   the user 6s of full-opacity hint copy then add .gh-faded so it settles
   at 0.28 opacity. Workspace switches hide/show it for free via the
   #dashRoot.hide-graph-hud CSS path (dashboard.css :3334 block). No
   localStorage, no first-run flag, no router changes - this is deliberately
   minimal per the Stage 31.2D-B spec. {once:true} so multiple authReady
   fires (re-login, session refresh) do not stack timers. */
(function () {
  if (typeof document === 'undefined') return;
  function scheduleHintFade() {
    var el = document.getElementById('graphHint');
    if (!el) return;
    setTimeout(function () {
      if (el && !el.classList.contains('gh-faded')) el.classList.add('gh-faded');
    }, 6000);
  }
  document.addEventListener('ee:authReady', scheduleHintFade, { once: true });
})();
